const SHARED = {"de":{"navMarkets":"Märkte","navScreener":"Screener","navTools":"Tools","navBlog":"Blog","navLiq":"Liquidationen","navFunding":"Funding","crumbHome":"Start","crumbGuides":"Ratgeber","faqH":"FAQ","footNote":"Nur zur Information — keine Finanzberatung. Erkunde die Live-Daten im <a href=\"/markets/\">Markt-Hub</a>."},"es":{"navMarkets":"Mercados","navScreener":"Screener","navTools":"Herramientas","navBlog":"Blog","navLiq":"Liquidaciones","navFunding":"Funding","crumbHome":"Inicio","crumbGuides":"Guías","faqH":"Preguntas frecuentes","footNote":"Solo informativo — no es asesoramiento financiero. Explora los datos en vivo en el <a href=\"/markets/\">hub de mercados</a>."},"pt":{"navMarkets":"Mercados","navScreener":"Screener","navTools":"Ferramentas","navBlog":"Blog","navLiq":"Liquidações","navFunding":"Funding","crumbHome":"Início","crumbGuides":"Guias","faqH":"Perguntas frequentes","footNote":"Apenas informativo — não é aconselhamento financeiro. Explore os dados ao vivo no <a href=\"/markets/\">hub de mercados</a>."},"fr":{"navMarkets":"Marchés","navScreener":"Screener","navTools":"Outils","navBlog":"Blog","navLiq":"Liquidations","navFunding":"Funding","crumbHome":"Accueil","crumbGuides":"Guides","faqH":"FAQ","footNote":"À titre informatif uniquement — pas un conseil financier. Explorez les données en direct sur le <a href=\"/markets/\">hub des marchés</a>."},"nl":{"navMarkets":"Markten","navScreener":"Screener","navTools":"Tools","navBlog":"Blog","navLiq":"Liquidaties","navFunding":"Funding","crumbHome":"Home","crumbGuides":"Gidsen","faqH":"FAQ","footNote":"Alleen ter informatie — geen financieel advies. Verken de live data op de <a href=\"/markets/\">markten-hub</a>."},"ru":{"navMarkets":"Рынки","navScreener":"Скринер","navTools":"Инструменты","navBlog":"Блог","navLiq":"Ликвидации","navFunding":"Фандинг","crumbHome":"Главная","crumbGuides":"Руководства","faqH":"Частые вопросы","footNote":"Только для информации — не финансовый совет. Изучите живые данные в <a href=\"/markets/\">хабе рынков</a>."},"tr":{"navMarkets":"Piyasalar","navScreener":"Tarayıcı","navTools":"Araçlar","navBlog":"Blog","navLiq":"Likidasyonlar","navFunding":"Funding","crumbHome":"Ana sayfa","crumbGuides":"Rehberler","faqH":"SSS","footNote":"Yalnızca bilgilendirme amaçlıdır — finansal tavsiye değildir. Canlı verileri <a href=\"/markets/\">piyasa merkezinde</a> keşfedin."},"zh":{"navMarkets":"行情","navScreener":"筛选器","navTools":"工具","navBlog":"博客","navLiq":"强平","navFunding":"资金费","crumbHome":"首页","crumbGuides":"指南","faqH":"常见问题","footNote":"仅供参考——非投资建议。在<a href=\"/markets/\">行情中心</a>探索实时数据。"},"ja":{"navMarkets":"マーケット","navScreener":"スクリーナー","navTools":"ツール","navBlog":"ブログ","navLiq":"清算","navFunding":"資金調達","crumbHome":"ホーム","crumbGuides":"ガイド","faqH":"よくある質問","footNote":"情報提供のみ——投資助言ではありません。ライブデータは<a href=\"/markets/\">マーケットハブ</a>でご覧ください。"},"ko":{"navMarkets":"마켓","navScreener":"스크리너","navTools":"도구","navBlog":"블로그","navLiq":"청산","navFunding":"펀딩","crumbHome":"홈","crumbGuides":"가이드","faqH":"자주 묻는 질문","footNote":"정보 제공용일 뿐 — 투자 조언이 아닙니다. 실시간 데이터는 <a href=\"/markets/\">마켓 허브</a>에서 살펴보세요."},"ar":{"navMarkets":"الأسواق","navScreener":"الماسح","navTools":"الأدوات","navBlog":"المدونة","navLiq":"التصفيات","navFunding":"التمويل","crumbHome":"الرئيسية","crumbGuides":"الأدلة","faqH":"الأسئلة الشائعة","footNote":"للمعلومات فقط — ليست نصيحة مالية. استكشف البيانات المباشرة في <a href=\"/markets/\">مركز الأسواق</a>."},"id":{"navMarkets":"Pasar","navScreener":"Screener","navTools":"Alat","navBlog":"Blog","navLiq":"Likuidasi","navFunding":"Funding","crumbHome":"Beranda","crumbGuides":"Panduan","faqH":"Tanya jawab","footNote":"Hanya untuk informasi — bukan nasihat keuangan. Jelajahi data langsung di <a href=\"/markets/\">hub pasar</a>."}};

const CASES = {"de":{"how-to-read-funding-rates":{"title":"Krypto-Funding-Raten lesen","desc":"Ein Ratgeber in klarem Deutsch zu Perpetual-Funding-Raten: was positives und negatives Funding bedeutet, wie man überfüllte Longs und Shorts erkennt und wie man Funding-Extreme nutzt.","toolLabel":"Live-Funding-Scanner","body":"<h2>Was eine Funding-Rate ist</h2><p>Bei einem Perpetual-Future gibt es keinen Verfall, daher nutzen Börsen eine kleine wiederkehrende Zahlung — die <strong>Funding-Rate</strong> —, um den Perp-Preis am Spot zu halten. Sie wird meist alle 8 Stunden zwischen Longs und Shorts ausgetauscht.</p>\n<h2>Positives vs. negatives Funding</h2><p><strong>Positives Funding</strong> bedeutet, der Perp handelt über Spot, also <em>zahlen Longs an Shorts</em> — der Markt lehnt sich long. <strong>Negatives Funding</strong> bedeutet, der Perp handelt unter Spot, also <em>zahlen Shorts an Longs</em> — der Markt lehnt sich short.</p>\n<h2>Extreme lesen</h2><p>Ist das Funding sehr positiv, sind Longs überfüllt und zahlen eine Prämie zum Halten; ein Stillstand im Preis kann einen <strong>Long-Squeeze</strong> auslösen. Ist das Funding tief negativ, sind Shorts überfüllt und eine Erholung kann einen <strong>Short-Squeeze</strong> erzwingen. Funding ist als Signal am stärksten zusammen mit <a href=\"/open-interest/\">Open Interest</a> und <a href=\"/long-short/\">Long/Short-Positionierung</a>.</p>\n<h2>Achte auf die Kosten</h2><p>Bei hohem Hebel summieren sich die Funding-Kosten schnell und können eine Position leise auszehren, selbst wenn der Preis flach ist. Rechne sie immer in deine Haltedauer ein.</p>","faq":[["Was bedeutet eine hohe Funding-Rate?","Hohes positives Funding bedeutet, der Markt ist stark long und Longs zahlen zum Halten — ein Zeichen überfüllter Longs, das bei einem Rücksetzer einen Short-Squeeze befeuern kann."],["Ist negatives Funding bullisch?","Negatives Funding bedeutet, Shorts sind überfüllt und zahlen an Longs. Es wird oft konträr als Setup für einen Squeeze nach oben gelesen, ist aber nur ein Signal neben Funding, Open Interest und Preis."]]},"how-to-read-liquidations":{"title":"Krypto-Liquidationen lesen","desc":"Verstehe Krypto-Liquidationen: was sie sind, der Unterschied zwischen Long- und Short-Liquidationen und wie Liquidationskaskaden Volatilität antreiben.","toolLabel":"Live-Liquidations-Tracker","body":"<h2>Was eine Liquidation ist</h2><p>Eine <strong>Liquidation</strong> ist, wenn eine Börse eine gehebelte Position zwangsschließt, weil die Margin des Traders den Verlust nicht mehr decken kann. Die Position wird zum Markt geschlossen und der Trader verliert seine Margin. Bei hohem Hebel liegt der Liquidationspreis sehr nah am Einstieg.</p>\n<h2>Long- vs. Short-Liquidationen</h2><p><strong>Long-Liquidationen</strong> sind überhebelte Käufer, die bei fallendem Preis ausgelöscht werden. <strong>Short-Liquidationen</strong> sind Verkäufer, die bei steigendem Preis ausgelöscht werden. Eine große einseitige Spitze markiert oft ein lokales Extrem — eine Flut von Long-Liquidationen kann einen Boden markieren, eine Welle von Short-Liquidationen kann eine Rally befeuern.</p>\n<h2>Liquidationskaskaden</h2><p>Liquidationen wirken wie Brennstoff. Trifft der Preis eine Zone voller Hebel, treiben die Zwangsorders den Preis weiter und lösen mehr Liquidationen aus — eine <strong>Kaskade</strong>. Zu beobachten, wo der Hebel am schwersten ist, hilft, den überfüllten Trade zu meiden.</p>\n<h2>Nutze es mit dem Rest</h2><p>Kombiniere Liquidationen mit <a href=\"/funding/\">Funding</a> und <a href=\"/open-interest/\">Open Interest</a>: ein Rückgang des Open Interest folgt meist einer Kaskade, wenn Hebel ausgespült wird.</p>","faq":[["Was verursacht eine Liquidation?","Eine Position wird liquidiert, wenn sich der Preis so weit gegen sie bewegt, dass die Margin den Verlust nicht mehr decken kann, also schließt die Börse sie automatisch."],["Sind Long- oder Short-Liquidationen bullisch?","Eine Spitze von Long-Liquidationen (bei einem Einbruch) kann einen lokalen Boden markieren; eine Spitze von Short-Liquidationen (bei einer Rally) kann einen Squeeze nach oben befeuern."]]},"what-is-open-interest":{"title":"Was ist Open Interest bei Krypto?","desc":"Open Interest erklärt: wie es sich von Volumen unterscheidet, was steigendes und fallendes OI signalisiert und wie man OI neben dem Preis liest.","toolLabel":"Live-Open-Interest-Tracker","body":"<h2>Open Interest vs. Volumen</h2><p><strong>Open Interest (OI)</strong> ist der Gesamtwert aller offenen Perpetual-Futures-Positionen auf einem Coin. Anders als Volumen — das jeden Trade zählt — misst OI, wie viel Hebel aktuell im Markt <em>offen</em> ist.</p>\n<h2>Steigendes und fallendes OI</h2><p>Steigendes OI bedeutet, neue Positionen und frischer Hebel kommen herein. Fallendes OI bedeutet, Trader schließen. Ein plötzlicher Rückgang des OI folgt meist einer <a href=\"/liquidations/\">Liquidationskaskade</a>, wenn überhebelte Positionen ausgespült werden.</p>\n<h2>OI mit dem Preis lesen</h2><p><strong>Preis hoch + OI hoch</strong> = neues Geld stützt die Bewegung (stärkerer Trend). <strong>Preis hoch + OI runter</strong> = Short-Eindeckung statt frischer Nachfrage. Starker OI-Aufbau plus einseitiges <a href=\"/funding/\">Funding</a> signalisiert ein überfülltes, fragiles Setup.</p>","faq":[["Ist hohes Open Interest bullisch oder bärisch?","Für sich genommen keines — es hängt vom Preis ab. Steigendes OI mit steigendem Preis deutet auf neue Käufer; steigendes OI mit fallendem Preis auf neue Verkäufer."],["Was bedeutet fallendes Open Interest?","Fallendes OI bedeutet, dass Positionen geschlossen werden, oft nachdem eine Liquidationskaskade Hebel aus dem Markt gespült hat."]]},"long-short-ratio-explained":{"title":"Krypto-Long/Short-Verhältnis erklärt","desc":"Was das Long/Short-Verhältnis über die Trader-Positionierung verrät, wie man überfüllte Extreme liest und warum es am besten konträr genutzt wird.","toolLabel":"Live-Long/Short-Verhältnis","body":"<h2>Was es misst</h2><p>Das <strong>Long/Short-Verhältnis</strong> zeigt, welcher Prozentsatz der Trader-Konten auf einem Coin long versus short positioniert ist. Es ist eine Momentaufnahme der Crowd-Positionierung und Stimmung.</p>\n<h2>Die Crowd lesen</h2><p>Erfahrene Trader lesen Extreme oft <strong>konträr</strong>. Wenn die meisten Konten bereits long sind, ist das Kaufen weitgehend verbraucht und die Crowd ist einem <strong>Long-Squeeze</strong> ausgesetzt. Ist die Crowd stark short, kann eine Erholung einen <strong>Short-Squeeze</strong> erzwingen.</p>\n<h2>Ein Signal, nicht das ganze Bild</h2><p>Ein überfülltes Buch kann überfüllt bleiben, während ein Trend läuft. Kombiniere das Verhältnis mit <a href=\"/funding/\">Funding</a> (was die Crowd zum Halten zahlt) und <a href=\"/liquidations/\">Liquidationen</a> (wo Hebel ausgespült wird), bevor du handelst.</p>","faq":[["Was ist ein gutes Long/Short-Verhältnis?","Es gibt keinen einzelnen guten Wert — es ist an Extremen am nützlichsten. Ein sehr hoher Long-Anteil warnt vor überfüllten Longs; ein sehr hoher Short-Anteil vor überfüllten Shorts."],["Wie nutzen Trader das Long/Short-Verhältnis?","Viele lesen es konträr: sie faden die überpositionierte Seite und bestätigen immer mit Funding, Open Interest und Preisbewegung."]]},"what-is-liquidation-price":{"title":"Was ist ein Liquidationspreis bei Krypto?","desc":"Was ein Liquidationspreis ist, wie Hebel ihn näher an deinen Einstieg rückt und wie du ihn vor dem Öffnen einer Position berechnest.","toolLabel":"Liquidationspreis-Rechner","body":"<h2>Was es ist</h2><p>Dein <strong>Liquidationspreis</strong> ist der Preis, bei dem eine Börse deine gehebelte Position zwangsschließt, weil deine Margin den Verlust nicht mehr decken kann. Überschreite ihn und du verlierst deine Margin. Ihn vor dem Einstieg zu kennen ist die wichtigste Zahl im gehebelten Handel.</p>\n<h2>Wie Hebel ihn verschiebt</h2><p>Je höher dein Hebel, desto näher liegt der Liquidationspreis am Einstieg. Bei 5× wird ein Long bei etwa 20 % Einbruch liquidiert; bei 100× bei etwa 1 % Bewegung. Deshalb ist hoher Hebel so fragil — ein gewöhnlicher Docht kann eine Position auslöschen.</p>\n<h2>Wie er berechnet wird</h2><p>Für einen isolierten Long gilt grob: Liquidation ≈ Einstieg × (1 − 1/Hebel + Erhaltungsmargen-Rate); Shorts drehen das Vorzeichen um. Der genaue Wert hängt von der Erhaltungsmarge und den Gebühren der Börse ab, also bestätige ihn mit einem <a href=\"/btc-liquidation-calculator/\">Liquidationsrechner</a> für deinen Coin und Hebel.</p>\n<h2>Gib ihm Raum</h2><p>Wähle Größe und Hebel so, dass der Liquidationspreis jenseits des Rauschens liegt — hinter offensichtlichen Unterstützungen und Widerständen und jüngsten Dochten — nicht direkt auf deinem Einstieg. Siehe auch <a href=\"/guides/how-to-avoid-liquidation/\">wie man Liquidation vermeidet</a>.</p>","faq":[["Wie wird der Liquidationspreis berechnet?","Grob: Liquidation ≈ Einstieg × (1 − 1/Hebel + Erhaltungsmarge) für einen Long, bei Shorts umgekehrt. Der genaue Wert hängt von der Erhaltungsmargen-Rate und den Gebühren der Börse ab."],["Bedeutet höherer Hebel einen näheren Liquidationspreis?","Ja. Bei 100× liegt der Liquidationspreis nur etwa 1 % vom Einstieg, bei 5× näher an 20 % — höherer Hebel lässt fast keinen Raum für Bewegung gegen dich."]]},"isolated-vs-cross-margin":{"title":"Isolierte vs. Cross-Margin erklärt","desc":"Der Unterschied zwischen isolierter und Cross-Margin, der Risiko-Kompromiss und welcher Modus zu welchem Trader-Typ passt.","toolLabel":"Auf Paper Trade üben","body":"<h2>Isolierte Margin</h2><p>Bei <strong>isolierter Margin</strong> ist nur die einer Position zugewiesene Margin im Risiko. Liquidiert sie, ist der Verlust auf diese Margin begrenzt und der Rest deines Guthabens bleibt unberührt. Es ist die sicherere Standardwahl für Trades mit hohem Hebel.</p>\n<h2>Cross-Margin</h2><p>Bei <strong>Cross-Margin</strong> stützt dein gesamtes Kontoguthaben die Position. Das schiebt den Liquidationspreis weiter weg, aber ein einziger schlechter Trade kann das ganze Konto leeren, nicht nur die Margin einer Position.</p>\n<h2>Was wann nutzen</h2><p>Die meisten Trader nutzen <strong>isoliert</strong> für Setups mit definiertem Risiko und hohem Hebel, und <strong>cross</strong> für Positionen mit niedrigerem Hebel, die sie aktiv managen oder hedgen. Der Kompromiss: isoliert begrenzt deinen Verlust; cross senkt das Liquidationsrisiko, erhöht aber deinen maximalen Verlust. So oder so, prüfe zuerst den <a href=\"/guides/what-is-liquidation-price/\">Liquidationspreis</a>.</p>","faq":[["Ist isolierte oder Cross-Margin sicherer?","Isoliert ist sicherer zum Begrenzen von Verlusten — nur die zugewiesene Margin ist im Risiko. Cross-Margin ist schwerer zu liquidieren, setzt aber dein ganzes Guthaben aufs Spiel."],["Wann sollte ich Cross-Margin nutzen?","Cross passt zu Positionen mit niedrigerem Hebel, die du aktiv managst oder hedgst, wo der Trade Volatilität überstehen soll, ohne Margin nachzuschießen."]]},"how-to-calculate-position-size":{"title":"Positionsgröße bei Krypto berechnen","desc":"Dimensioniere jeden Trade nach Risiko, nicht nach Bauchgefühl: wie man die Positionsgröße aus Konto, Stop-Distanz und Risiko pro Trade ermittelt.","toolLabel":"Positionsgrößen-Rechner","body":"<h2>Risiko zuerst, Größe danach</h2><p>Professionelle Dimensionierung beginnt mit einer Zahl: wie viel du beim Trade zu verlieren bereit bist. Eine gängige Regel ist, <strong>1–2 % des Kontos pro Trade</strong> zu riskieren. Deine Positionsgröße folgt dann aus deiner Stop-Distanz.</p>\n<h2>Die Formel</h2><p>Positionsgröße = (Konto × Risiko %) ÷ (Stop-Distanz %). Riskierst du 20 $ und dein Stop ist 2 % entfernt, nimmst du 1.000 $ Exposure — unabhängig vom Hebel. Hebel bestimmt nur die nötige Margin, nicht dein Risiko.</p>\n<h2>Hebel ist nicht Risiko</h2><p>Das übersehen die meisten Anfänger: dein Risiko wird von Größe und Stop bestimmt, nicht vom Hebel. 10× auf einer kleinen, gut gestoppten Position kann weit sicherer sein als 2× auf einer überdimensionierten. Nutze einen <a href=\"/calculators?c=size\">Positionsgrößen-Rechner</a>, damit jeder Trade denselben Betrag riskiert, und behalte deinen <a href=\"/guides/what-is-liquidation-price/\">Liquidationspreis</a> im Auge.</p>","faq":[["Wie viel sollte ich pro Trade riskieren?","Eine weit verbreitete Richtlinie sind 1–2 % des Kontos pro Trade, damit eine Verlustserie das Konto nicht sprengen kann."],["Ändert Hebel meine Positionsgröße?","Nein — dein Risiko wird von Positionsgröße und Stop-Distanz bestimmt. Hebel legt nur die nötige Margin fest, um diese Position zu halten."]]},"what-is-leverage-in-crypto":{"title":"Was ist Hebel im Krypto-Handel?","desc":"Hebel einfach erklärt: wie 10× oder 100× funktioniert, was es mit deinem Liquidationspreis macht und wie man ihn nutzt, ohne sich zu sprengen.","toolLabel":"Liquidationsrechner","body":"<h2>Was Hebel macht</h2><p><strong>Hebel</strong> lässt dich eine Position kontrollieren, die größer ist als deine Margin. Bei 10× kontrolliert eine 100-$-Margin 1.000 $ Exposure, also wird eine 1-%-Bewegung zu einem 10-%-Schwung auf deiner Margin — Gewinne und Verluste werden beide verstärkt.</p>\n<h2>Der Haken: Liquidation</h2><p>Die Kehrseite ist dein <a href=\"/guides/what-is-liquidation-price/\">Liquidationspreis</a>. Je höher der Hebel, desto kleiner die Bewegung, die dich auslöscht — grob 1 % bei 100×, 2 % bei 50×, 10 % bei 10×. Verstärktes Aufwärtspotenzial kommt mit verstärkter Fragilität.</p>\n<h2>Sinnvoll nutzen</h2><p>Hebel ist ein Werkzeug für Kapitaleffizienz, keine Zahl zum Maximieren. Dimensioniere nach <a href=\"/guides/how-to-calculate-position-size/\">Risiko</a>, halte den Liquidationspreis jenseits des Rauschens und denke daran, dass Funding-Kosten mit der Positionsgröße skalieren, nicht mit der Margin.</p>","faq":[["Was bedeutet 10× Hebel?","10× bedeutet, deine Position ist das Zehnfache deiner Margin: 100 $ kontrollieren 1.000 $, also entspricht eine 1-%-Preisbewegung einer 10-%-Bewegung auf deiner Margin — in beide Richtungen."],["Ist hoher Hebel schlecht?","Hoher Hebel ist nicht per se schlecht, aber er rückt deinen Liquidationspreis sehr nah an den Einstieg. Die meisten Blow-ups kommen vom Überdimensionieren bei hohem Hebel, nicht vom Hebel selbst."]]},"maker-vs-taker-fees":{"title":"Maker- vs. Taker-Gebühren erklärt","desc":"Was Maker- und Taker-Gebühren sind, warum Taker mehr zahlen und wie sich der Unterschied für aktive Futures-Trader summiert.","toolLabel":"Börsengebühren vergleichen","body":"<h2>Der Unterschied</h2><p>Eine <strong>Maker</strong>-Order fügt dem Buch Liquidität hinzu — eine Limit-Order, die ruht und auf Ausführung wartet. Eine <strong>Taker</strong>-Order entzieht Liquidität — eine Market-Order oder ein sofort ausgeführtes Limit, das ein bestehendes Angebot nimmt. Börsen verlangen von Takern mehr, weil Maker die Liquidität liefern, gegen die alle handeln.</p>\n<h2>Typische Sätze</h2><p>Auf großen USDT-Perpetuals liegen Maker-Gebühren um 0,02 % und Taker-Gebühren bei 0,04–0,06 %. Klingt winzig, aber ein Daytrader mit dutzenden Round-Trips zahlt sie immer wieder — und Taker zahlen sie auf beiden Seiten.</p>\n<h2>Wie man weniger zahlt</h2><p>Nutze ruhende <strong>Limit-Orders</strong>, um wo möglich die Maker-Gebühr zu erhalten, halte den Börsen-Token für einen Rabatt und steige mit wachsendem Volumen die VIP-Stufen hinauf. Wenn Gebühren deine Priorität sind, <a href=\"/lowest-fee-crypto-exchange/\">vergleiche zuerst Börsen nach Taker-Gebühr</a>.</p>","faq":[["Warum zahlen Taker mehr als Maker?","Taker entziehen Liquidität, indem sie bestehende Orders ausführen, während Maker durch ruhende Orders im Buch Liquidität hinzufügen. Börsen belohnen Maker mit niedrigeren Gebühren, weil sie den Markt liquide halten."],["Wie zahle ich Maker-Gebühren?","Platziere Limit-Orders, die im Buch ruhen, statt Market-Orders, die sofort ausführen. Wartet deine Order auf eine Zuordnung, qualifiziert sie sich für die niedrigere Maker-Gebühr."]]},"how-to-avoid-liquidation":{"title":"Wie man Liquidation im Krypto-Handel vermeidet","desc":"Praktische Wege, eine gehebelte Position vor der Liquidation zu bewahren — von Größe und Stops bis zu Margin-Modus und Funding.","toolLabel":"Prüfe deinen Liquidationspreis","body":"<h2>Kenne den Preis, bevor du einsteigst</h2><p>Berechne zuerst deinen <a href=\"/guides/what-is-liquidation-price/\">Liquidationspreis</a> und stelle sicher, dass er jenseits jüngster Dochte und offensichtlicher Unterstützungen und Widerstände liegt — nicht direkt neben deinem Einstieg.</p>\n<h2>Nutze weniger Hebel, als du kannst</h2><p>Nur weil eine Börse 125× bietet, heißt das nicht, dass du ihn nutzen solltest. Niedrigerer Hebel schiebt den Liquidationspreis weiter vom Einstieg weg und verschafft dir Raum, über die Zeit recht zu behalten.</p>\n<h2>Setze immer einen Stop-Loss</h2><p>Ein Stop schließt dich zu einem Preis, den <em>du</em> wählst, bevor die Liquidations-Engine der Börse es zu einem schlechteren tut.</p>\n<h2>Dimensioniere nach Risiko</h2><p>Riskiere feste 1–2 % pro Trade mit einem <a href=\"/guides/how-to-calculate-position-size/\">Positionsgrößen-Rechner</a>, damit kein einzelner Trade echten Schaden anrichten kann.</p>\n<h2>Bevorzuge isolierte Margin</h2><p><a href=\"/guides/isolated-vs-cross-margin/\">Isolierte Margin</a> begrenzt den Verlust auf eine Position. Schieße Margin bewusst nach, nicht in Panik.</p>\n<h2>Achte auf Funding</h2><p>Bei hohem Hebel zehrt <a href=\"/funding/\">Funding</a> eine Position leise aus, selbst wenn der Preis flach ist — rechne es bei langen Haltedauern ein.</p>","faq":[["Was ist der beste Weg, Liquidation zu vermeiden?","Nutze niedrigeren Hebel, setze immer einen Stop-Loss, dimensioniere nach einem festen Risikoprozentsatz und halte deinen Liquidationspreis weit jenseits jüngster Volatilität."],["Verhindert ein Stop-Loss eine Liquidation?","Ein Stop-Loss schließt deine Position zu deinem gewählten Preis, bevor die Börsen-Liquidation auslöst, also verhindert er in der Praxis die meisten Liquidationen — vorausgesetzt, er füllt in schnellen Märkten."]]},"perpetual-vs-futures":{"title":"Perpetual vs. Futures: Was ist der Unterschied?","desc":"Perpetual-Swaps versus datierte Futures: Verfall, Funding und warum Perps den Krypto-Hebelhandel dominieren.","toolLabel":"Live-Funding-Scanner","body":"<h2>Datierte Futures</h2><p>Ein traditioneller <strong>Futures-Kontrakt</strong> hat ein Verfallsdatum. An diesem Datum settelt er zum Spot-Preis, also konvergiert der Kontraktpreis zum Spot, je näher der Verfall rückt. Du handelst ihn für eine feste Laufzeit, dann ist er weg.</p>\n<h2>Perpetual-Swaps</h2><p>Ein <strong>Perpetual</strong> („Perp\") verfällt nie. Um seinen Preis ohne Verfall am Spot zu halten, nutzen Börsen eine wiederkehrende <a href=\"/funding/\">Funding-Zahlung</a> zwischen Longs und Shorts. Dieser Mechanismus ersetzt das Settlement.</p>\n<h2>Warum Perps Krypto dominieren</h2><p>Perps lassen Trader Hebel unbegrenzt halten, ohne Rollover, weshalb sie den Großteil des Krypto-Derivatevolumens ausmachen. Der Kompromiss ist Funding: bei hohem Hebel kann es eine Position leise auszehren, selbst wenn der Preis flach ist.</p>","faq":[["Verfallen Perpetual-Kontrakte?","Nein. Perpetual-Swaps verfallen nie — eine wiederkehrende Funding-Zahlung hält ihren Preis am Spot statt an einem Settlement-Datum."],["Was ist der Unterschied zwischen Futures und Perpetuals?","Datierte Futures settlen an einem Verfallsdatum, während Perpetuals unbegrenzt laufen und Funding-Zahlungen nutzen, um nahe am Spot zu bleiben. Der Krypto-Handel wird von Perpetuals dominiert."]]},"long-vs-short-crypto":{"title":"Long vs. Short bei Krypto erklärt","desc":"Was es bedeutet, mit Hebel long oder short zu gehen, wie jede Seite Geld verdient oder verliert und wie sich die Liquidation unterscheidet.","toolLabel":"Long & Short üben","body":"<h2>Long gehen</h2><p>Ein <strong>Long</strong> wettet, dass der Preis steigt. Du profitierst, wenn der Preis steigt, und verlierst, wenn er fällt. Ein Long wird liquidiert, wenn der Preis weit genug fällt, dass deine Margin den Verlust nicht mehr decken kann.</p>\n<h2>Short gehen</h2><p>Ein <strong>Short</strong> wettet, dass der Preis fällt. Du profitierst, wenn der Preis fällt, und verlierst, wenn er steigt — Shorten lässt dich in einem Abwärtstrend Geld verdienen. Ein Short wird liquidiert, wenn der Preis weit genug gegen dich steigt.</p>\n<h2>Das Risiko ist nicht symmetrisch</h2><p>Ein Long kann nur auf null fallen, aber ein Short hat unbegrenzten theoretischen Verlust, wenn der Preis weiter steigt — weshalb Short-Squeezes heftig sein können. So oder so legt der Hebel fest, wie nah dein <a href=\"/guides/what-is-liquidation-price/\">Liquidationspreis</a> am Einstieg liegt. Teste beide Seiten risikofrei auf <a href=\"/paper-trade\">Paper Trade</a>.</p>","faq":[["Was bedeutet Short gehen bei Krypto?","Shorten bedeutet, darauf zu wetten, dass der Preis fällt: du profitierst, wenn er fällt, und verlierst, wenn er steigt, was dich in einem Abwärtstrend Geld verdienen lässt."],["Ist Shorten riskanter als Long gehen?","Ein Short hat unbegrenzten theoretischen Verlust, wenn der Preis weiter steigt, während ein Long nur auf null fallen kann — ein ungehedgter Short kann also riskanter sein, und Short-Squeezes können scharf sein."]]},"what-is-mark-price":{"title":"Was ist der Mark-Preis bei Krypto-Futures?","desc":"Warum Börsen auf dem Mark-Preis liquidieren, nicht auf dem Last-Preis, und wie er dich davor schützt, von einem dünnen Orderbuch ausgewickt zu werden.","toolLabel":"Liquidationsrechner","body":"<h2>Last-Preis vs. Mark-Preis</h2><p>Der <strong>Last-Preis</strong> ist einfach der jüngste Trade auf dieser Börse. Der <strong>Mark-Preis</strong> ist eine fairere Referenz — meist aus einem Index mehrerer Spot-Märkte plus einer Funding-Basis gebildet —, die Einzelbörsen-Spitzen glättet.</p>\n<h2>Warum es wichtig ist</h2><p>Börsen berechnen deinen unrealisierten PnL und deine <a href=\"/guides/what-is-liquidation-price/\">Liquidation</a> gegen den <strong>Mark-Preis</strong>, nicht den Last-Preis. Das schützt dich davor, von einem kurzen Docht auf einem dünnen Buch liquidiert zu werden, der den wahren Markt nicht widerspiegelt.</p>\n<h2>Worauf achten</h2><p>In schnellen Märkten kann der Last-Preis weit über den Mark-Preis schießen. Deine Position wird am Mark beurteilt, also prüfe ihn — nicht den blinkenden Last-Preis —, wenn du nahe an deinem Liquidationsniveau bist.</p>","faq":[["Warum nutzen Börsen den Mark-Preis für Liquidation?","Der Mark-Preis ist ein indexbasierter fairer Wert, der Einzelbörsen-Spitzen glättet, sodass ein kurzer Docht auf einem dünnen Orderbuch eine gesunde Position nicht fälschlich liquidieren kann."],["Ist der Mark-Preis dasselbe wie der Last-Preis?","Nein. Der Last-Preis ist der jüngste Trade auf dieser Börse; der Mark-Preis ist ein fairerer indexbasierter Wert, der zur Berechnung von PnL und Liquidationen genutzt wird."]]}},"es":{"how-to-read-funding-rates":{"title":"Cómo leer las funding rates en cripto","desc":"Una guía sencilla sobre las funding rates de los perpetuos: qué significan el funding positivo y negativo, cómo detectar longs y shorts saturados, y cómo aprovechar los extremos del funding.","toolLabel":"Escáner de funding en vivo","body":"<h2>Qué es una funding rate</h2><p>En un futuro perpetuo no hay vencimiento, así que los exchanges usan un pequeño pago recurrente — la <strong>funding rate</strong> — para mantener el precio del perp anclado al spot. Normalmente se intercambia cada 8 horas entre longs y shorts.</p>\n<h2>Funding positivo vs negativo</h2><p>El <strong>funding positivo</strong> significa que el perp cotiza por encima del spot, así que los <em>longs pagan a los shorts</em> — el mercado está inclinado al lado long. El <strong>funding negativo</strong> significa que el perp cotiza por debajo del spot, así que los <em>shorts pagan a los longs</em> — el mercado está inclinado al lado short.</p>\n<h2>Leer los extremos</h2><p>Cuando el funding es muy positivo, los longs están saturados y pagando una prima por mantener la posición; un estancamiento del precio puede desencadenar un <strong>long squeeze</strong>. Cuando el funding es profundamente negativo, los shorts están saturados y un rebote puede forzar un <strong>short squeeze</strong>. El funding es más potente como señal junto al <a href=\"/open-interest/\">open interest</a> y el <a href=\"/long-short/\">posicionamiento long/short</a>.</p>\n<h2>Vigila el coste</h2><p>Con apalancamiento alto, el coste del funding se compone rápido y puede drenar una posición de forma silenciosa incluso cuando el precio está plano. Tenlo siempre en cuenta en tu tiempo de exposición.</p>","faq":[["¿Qué significa una funding rate alta?","Un funding positivo alto significa que el mercado está fuertemente posicionado en long y los longs están pagando por mantener la posición — una señal de longs saturados que puede alimentar un short squeeze en un retroceso."],["¿Es alcista el funding negativo?","El funding negativo significa que los shorts están saturados y pagando a los longs. A menudo se lee de forma contraria como un escenario para un squeeze al alza, pero es solo una señal entre el funding, el open interest y el precio."]]},"how-to-read-liquidations":{"title":"Cómo leer las liquidaciones en cripto","desc":"Entiende las liquidaciones en cripto: qué son, la diferencia entre liquidaciones de longs y de shorts, y cómo las cascadas de liquidaciones impulsan la volatilidad.","toolLabel":"Rastreador de liquidaciones en vivo","body":"<h2>Qué es una liquidación</h2><p>Una <strong>liquidación</strong> ocurre cuando un exchange cierra a la fuerza una posición apalancada porque el margen del trader ya no puede cubrir la pérdida. La posición se cierra a mercado y el trader pierde su margen. Con apalancamiento alto, el precio de liquidación queda muy cerca de la entrada.</p>\n<h2>Liquidaciones de longs vs shorts</h2><p>Las <strong>liquidaciones de longs</strong> son compradores sobreapalancados barridos cuando el precio cae. Las <strong>liquidaciones de shorts</strong> son vendedores barridos cuando el precio sube. Un gran pico unidireccional suele marcar un extremo local — una purga de liquidaciones de longs puede marcar un suelo, y una ola de liquidaciones de shorts puede alimentar un rally.</p>\n<h2>Cascadas de liquidaciones</h2><p>Las liquidaciones actúan como combustible. Cuando el precio llega a una zona cargada de apalancamiento, las órdenes forzadas empujan el precio aún más, desencadenando más liquidaciones — una <strong>cascada</strong>. Observar dónde se concentra más el apalancamiento te ayuda a evitar el trade saturado.</p>\n<h2>Úsalo junto al resto</h2><p>Combina las liquidaciones con el <a href=\"/funding/\">funding</a> y el <a href=\"/open-interest/\">open interest</a>: una caída del open interest suele seguir a una cascada a medida que se purga el apalancamiento.</p>","faq":[["¿Qué causa una liquidación?","Una posición se liquida cuando el precio se mueve en su contra lo suficiente como para que el margen ya no pueda cubrir la pérdida, así que el exchange la cierra automáticamente."],["¿Son alcistas las liquidaciones de longs o de shorts?","Un pico de liquidaciones de longs (en una caída) puede marcar un suelo local; un pico de liquidaciones de shorts (en un rally) puede alimentar un squeeze al alza."]]},"what-is-open-interest":{"title":"¿Qué es el open interest en cripto?","desc":"El open interest explicado: en qué se diferencia del volumen, qué señalan un OI creciente y decreciente, y cómo leer el OI junto al precio.","toolLabel":"Rastreador de open interest en vivo","body":"<h2>Open interest vs volumen</h2><p>El <strong>open interest (OI)</strong> es el valor total de todas las posiciones abiertas de futuros perpetuos en una moneda. A diferencia del volumen — que cuenta cada operación — el OI mide cuánto apalancamiento está actualmente <em>abierto</em> en el mercado.</p>\n<h2>OI creciente y decreciente</h2><p>Un OI creciente significa que entran nuevas posiciones y apalancamiento fresco. Un OI decreciente significa que los traders están cerrando posiciones. Una caída repentina del OI suele seguir a una <a href=\"/liquidations/\">cascada de liquidaciones</a> a medida que se purgan las posiciones sobreapalancadas.</p>\n<h2>Leer el OI con el precio</h2><p><strong>Precio arriba + OI arriba</strong> = dinero nuevo respaldando el movimiento (tendencia más fuerte). <strong>Precio arriba + OI abajo</strong> = cierre de shorts en lugar de demanda fresca. Una fuerte acumulación de OI más un <a href=\"/funding/\">funding</a> unidireccional señala un escenario saturado y frágil.</p>","faq":[["¿Es alcista o bajista un open interest alto?","Ninguno de los dos por sí solo — depende del precio. Un OI creciente con precio creciente sugiere nuevos compradores; un OI creciente con precio cayendo sugiere nuevos vendedores."],["¿Qué significa un open interest decreciente?","Un OI decreciente significa que se están cerrando posiciones, a menudo después de que una cascada de liquidaciones purgue el apalancamiento del mercado."]]},"long-short-ratio-explained":{"title":"El long/short ratio en cripto explicado","desc":"Qué te dice el long/short ratio sobre el posicionamiento de los traders, cómo leer los extremos saturados, y por qué se usa mejor de forma contraria.","toolLabel":"Long/short ratio en vivo","body":"<h2>Qué mide</h2><p>El <strong>long/short ratio</strong> muestra qué porcentaje de las cuentas de los traders está posicionado en long frente a short en una moneda. Es una instantánea del posicionamiento y el sentimiento de la multitud.</p>\n<h2>Leer a la multitud</h2><p>Los traders experimentados suelen leer los extremos de forma <strong>contraria</strong>. Cuando la mayoría de las cuentas ya está en long, la compra está prácticamente agotada y la multitud queda expuesta a un <strong>long squeeze</strong>. Cuando la multitud está fuertemente en short, un rebote puede forzar un <strong>short squeeze</strong>.</p>\n<h2>Una señal, no el cuadro completo</h2><p>Un libro saturado puede seguir saturado mientras una tendencia avanza. Combina el ratio con el <a href=\"/funding/\">funding</a> (lo que paga la multitud por mantener la posición) y las <a href=\"/liquidations/\">liquidaciones</a> (dónde se purga el apalancamiento) antes de actuar.</p>","faq":[["¿Cuál es un buen long/short ratio?","No hay un único valor bueno — es más útil en los extremos. Una proporción de longs muy alta advierte de longs saturados; una proporción de shorts muy alta advierte de shorts saturados."],["¿Cómo usan los traders el long/short ratio?","Muchos lo leen de forma contraria: operando contra el lado sobreposicionado, y confirmando siempre con el funding, el open interest y la acción del precio."]]},"what-is-liquidation-price":{"title":"¿Qué es el precio de liquidación en cripto?","desc":"Qué es un precio de liquidación, cómo el apalancamiento lo acerca a tu entrada, y cómo calcularlo antes de abrir una posición.","toolLabel":"Calculadora de precio de liquidación","body":"<h2>Qué es</h2><p>Tu <strong>precio de liquidación</strong> es el precio al que un exchange cierra a la fuerza tu posición apalancada porque tu margen ya no puede cubrir la pérdida. Si lo cruzas, pierdes tu margen. Conocerlo antes de entrar es el número más importante del trading apalancado.</p>\n<h2>Cómo lo mueve el apalancamiento</h2><p>Cuanto mayor es tu apalancamiento, más cerca queda el precio de liquidación de tu entrada. A 5× un long se liquida con una caída de aproximadamente el 20%; a 100× es un movimiento de alrededor del 1%. Por eso el apalancamiento alto es tan frágil — una mecha cualquiera puede barrer una posición.</p>\n<h2>Cómo se calcula</h2><p>Para un long aislado, liquidación ≈ entrada × (1 − 1/apalancamiento + tasa de margen de mantenimiento); en los shorts se invierte el signo. La cifra exacta depende del margen de mantenimiento y las comisiones del exchange, así que confírmala con una <a href=\"/btc-liquidation-calculator/\">calculadora de liquidación</a> para tu moneda y apalancamiento.</p>\n<h2>Dale margen</h2><p>Ajusta tu tamaño y apalancamiento para que el precio de liquidación quede más allá del ruido — más allá de los soportes y resistencias obvios y de las mechas recientes — y no pegado a tu entrada. Mira también <a href=\"/guides/how-to-avoid-liquidation/\">cómo evitar la liquidación</a>.</p>","faq":[["¿Cómo se calcula el precio de liquidación?","A grandes rasgos, liquidación ≈ entrada × (1 − 1/apalancamiento + margen de mantenimiento) para un long, con los shorts invertidos. El valor preciso depende de la tasa de margen de mantenimiento y de las comisiones del exchange."],["¿Un apalancamiento más alto significa un precio de liquidación más cercano?","Sí. A 100× el precio de liquidación está a solo un 1% de la entrada, mientras que a 5× está más cerca del 20% — un apalancamiento más alto deja casi ningún margen para que el precio se mueva en tu contra."]]},"isolated-vs-cross-margin":{"title":"Margen aislado vs cruzado explicado","desc":"La diferencia entre margen aislado y cruzado, el compromiso de riesgo, y qué modo conviene a cada estilo de trader.","toolLabel":"Practica en Paper Trade","body":"<h2>Margen aislado</h2><p>En el <strong>margen aislado</strong>, solo está en riesgo el margen que asignas a una posición. Si se liquida, la pérdida queda limitada a ese margen y el resto de tu saldo permanece intacto. Es la opción por defecto más segura para trades con apalancamiento alto.</p>\n<h2>Margen cruzado</h2><p>En el <strong>margen cruzado</strong>, el saldo completo de tu cuenta respalda la posición. Eso aleja el precio de liquidación, pero un solo mal trade puede drenar toda la cuenta, no solo el margen de una posición.</p>\n<h2>Cuál usar</h2><p>La mayoría de los traders usan el <strong>aislado</strong> para escenarios de riesgo definido y apalancamiento alto, y el <strong>cruzado</strong> para posiciones de menor apalancamiento que gestionan o cubren activamente. El compromiso: el aislado limita tu pérdida; el cruzado reduce el riesgo de liquidación pero eleva tu pérdida máxima. En cualquier caso, comprueba primero el <a href=\"/guides/what-is-liquidation-price/\">precio de liquidación</a>.</p>","faq":[["¿Es más seguro el margen aislado o el cruzado?","El aislado es más seguro para limitar pérdidas — solo está en riesgo el margen asignado. El margen cruzado es más difícil de liquidar pero pone en juego todo tu saldo."],["¿Cuándo debería usar el margen cruzado?","El cruzado conviene a posiciones de menor apalancamiento que gestionas o cubres activamente, donde quieres que el trade sobreviva a la volatilidad sin añadir margen."]]},"how-to-calculate-position-size":{"title":"Cómo calcular el tamaño de posición en cripto","desc":"Dimensiona cada trade por riesgo, no por intuición: cómo calcular el tamaño de posición a partir de tu cuenta, la distancia del stop y el riesgo por trade.","toolLabel":"Calculadora de tamaño de posición","body":"<h2>Primero el riesgo, después el tamaño</h2><p>El dimensionamiento profesional parte de un solo número: cuánto estás dispuesto a perder en el trade. Una regla común es arriesgar <strong>el 1–2% de tu cuenta por trade</strong>. El tamaño de tu posición se deriva entonces de la distancia de tu stop.</p>\n<h2>La fórmula</h2><p>Tamaño de posición = (cuenta × riesgo %) ÷ (distancia del stop %). Si arriesgas 20 $ y tu stop está a un 2% de distancia, tomas 1.000 $ de exposición — independientemente del apalancamiento. El apalancamiento solo determina el margen requerido, no tu riesgo.</p>\n<h2>El apalancamiento no es el riesgo</h2><p>Este es el punto que la mayoría de los principiantes pasan por alto: tu riesgo lo fijan el tamaño y el stop, no el apalancamiento. 10× en una posición pequeña y bien protegida con stop puede ser mucho más seguro que 2× en una sobredimensionada. Usa una <a href=\"/calculators?c=size\">calculadora de tamaño de posición</a> para que cada trade arriesgue lo mismo, y vigila tu <a href=\"/guides/what-is-liquidation-price/\">precio de liquidación</a>.</p>","faq":[["¿Cuánto debería arriesgar por trade?","Una pauta ampliamente usada es el 1–2% de tu cuenta por trade, de modo que una racha de pérdidas no pueda reventar la cuenta."],["¿El apalancamiento cambia el tamaño de mi posición?","No — tu riesgo lo fijan el tamaño de la posición y la distancia del stop. El apalancamiento solo determina el margen necesario para mantener esa posición."]]},"what-is-leverage-in-crypto":{"title":"¿Qué es el apalancamiento en el trading de cripto?","desc":"El apalancamiento explicado de forma sencilla: cómo funcionan 10× o 100×, qué le hace a tu precio de liquidación, y cómo usarlo sin reventar la cuenta.","toolLabel":"Calculadora de liquidación","body":"<h2>Qué hace el apalancamiento</h2><p>El <strong>apalancamiento</strong> te permite controlar una posición mayor que tu margen. A 10× un margen de 100 $ controla 1.000 $ de exposición, así que un movimiento del 1% se convierte en una oscilación del 10% sobre tu margen — las ganancias y las pérdidas se magnifican por igual.</p>\n<h2>El truco: la liquidación</h2><p>La contrapartida es tu <a href=\"/guides/what-is-liquidation-price/\">precio de liquidación</a>. Cuanto mayor es el apalancamiento, menor es el movimiento que te barre — aproximadamente un 1% a 100×, un 2% a 50×, un 10% a 10×. La ganancia magnificada viene con una fragilidad magnificada.</p>\n<h2>Usarlo con sensatez</h2><p>El apalancamiento es una herramienta de eficiencia de capital, no un número que haya que llevar al máximo. Dimensiona por <a href=\"/guides/how-to-calculate-position-size/\">riesgo</a>, mantén el precio de liquidación más allá del ruido, y recuerda que los costes de funding escalan con el tamaño de la posición, no con el margen.</p>","faq":[["¿Qué significa un apalancamiento de 10x?","10× significa que tu posición es diez veces tu margen: 100 $ controlan 1.000 $, así que un movimiento del precio del 1% equivale a un movimiento del 10% sobre tu margen — en ambas direcciones."],["¿Es malo el apalancamiento alto?","El apalancamiento alto no es malo de por sí, pero pone tu precio de liquidación muy cerca de la entrada. La mayoría de las reventadas vienen de sobredimensionar con apalancamiento alto, no del apalancamiento en sí."]]},"maker-vs-taker-fees":{"title":"Comisiones maker vs taker explicadas","desc":"Qué son las comisiones maker y taker, por qué los takers pagan más, y cómo se acumula la diferencia para los traders activos de futuros.","toolLabel":"Compara comisiones de exchanges","body":"<h2>La diferencia</h2><p>Una orden <strong>maker</strong> añade liquidez al libro — una orden límite que se queda esperando a ser ejecutada. Una orden <strong>taker</strong> retira liquidez — una orden a mercado, o una orden límite que se ejecuta al instante, que toma una oferta existente. Los exchanges cobran más a los takers porque los makers proporcionan la liquidez contra la que todos operan.</p>\n<h2>Tasas típicas</h2><p>En los principales perpetuos de USDT, las comisiones maker rondan el 0.02% y las taker el 0.04–0.06%. Suena minúsculo, pero un day trader que hace docenas de operaciones de ida y vuelta lo paga una y otra vez — y los takers lo pagan en ambos lados.</p>\n<h2>Cómo pagar menos</h2><p>Usa <strong>órdenes límite</strong> que reposen en el libro para calificar para la comisión maker donde puedas, mantén el token del exchange para obtener un descuento, y escala los niveles VIP a medida que crece tu volumen. Si las comisiones son tu prioridad, <a href=\"/lowest-fee-crypto-exchange/\">compara primero los exchanges por comisión taker</a>.</p>","faq":[["¿Por qué pagan más los takers que los makers?","Los takers retiran liquidez al ejecutar órdenes existentes, mientras que los makers añaden liquidez al dejar órdenes en reposo en el libro. Los exchanges premian a los makers con comisiones más bajas porque mantienen el mercado líquido."],["¿Cómo pago comisiones maker?","Coloca órdenes límite que reposen en el libro en lugar de órdenes a mercado que se ejecutan al instante. Si tu orden espera a ser emparejada, califica para la comisión maker más baja."]]},"how-to-avoid-liquidation":{"title":"Cómo evitar la liquidación en el trading de cripto","desc":"Formas prácticas de evitar que una posición apalancada sea liquidada — desde el dimensionamiento y los stops hasta el modo de margen y el funding.","toolLabel":"Comprueba tu precio de liquidación","body":"<h2>Conoce el precio antes de entrar</h2><p>Calcula primero tu <a href=\"/guides/what-is-liquidation-price/\">precio de liquidación</a> y asegúrate de que quede más allá de las mechas recientes y de los soportes y resistencias obvios — y no justo al lado de tu entrada.</p>\n<h2>Usa menos apalancamiento del que puedes</h2><p>Que un exchange ofrezca 125× no significa que debas usarlo. Un apalancamiento más bajo aleja el precio de liquidación de la entrada y te da margen para tener razón con el tiempo.</p>\n<h2>Pon siempre un stop-loss</h2><p>Un stop te cierra a un precio que <em>tú</em> eliges, antes de que el motor de liquidación del exchange lo haga por ti a uno peor.</p>\n<h2>Dimensiona por riesgo</h2><p>Arriesga un 1–2% fijo por trade usando una <a href=\"/guides/how-to-calculate-position-size/\">calculadora de tamaño de posición</a>, de modo que ningún trade pueda hacer daño real.</p>\n<h2>Prefiere el margen aislado</h2><p>El <a href=\"/guides/isolated-vs-cross-margin/\">margen aislado</a> limita la pérdida a una sola posición. Añade margen de forma deliberada, no presa del pánico.</p>\n<h2>Atento al funding</h2><p>Con apalancamiento alto, el <a href=\"/funding/\">funding</a> drena una posición de forma silenciosa incluso cuando el precio está plano — tenlo en cuenta en las posiciones de largo plazo.</p>","faq":[["¿Cuál es la mejor manera de evitar la liquidación?","Usa menos apalancamiento, pon siempre un stop-loss, dimensiona por un porcentaje de riesgo fijo, y mantén tu precio de liquidación bien lejos de la volatilidad reciente."],["¿Un stop-loss evita la liquidación?","Un stop-loss cierra tu posición a tu precio elegido antes de que se active la liquidación del exchange, así que en la práctica evita la mayoría de las liquidaciones — siempre que se ejecute en mercados rápidos."]]},"perpetual-vs-futures":{"title":"Perpetuos vs futuros: ¿cuál es la diferencia?","desc":"Swaps perpetuos frente a futuros con vencimiento: expiración, funding, y por qué los perps dominan el trading apalancado de cripto.","toolLabel":"Escáner de funding en vivo","body":"<h2>Futuros con vencimiento</h2><p>Un <strong>contrato de futuros</strong> tradicional tiene una fecha de vencimiento. En esa fecha se liquida al precio spot, así que el precio del contrato converge hacia el spot a medida que se acerca el vencimiento. Lo operas durante un plazo fijo y luego desaparece.</p>\n<h2>Swaps perpetuos</h2><p>Un <strong>perpetuo</strong> (\"perp\") nunca vence. Para mantener su precio anclado al spot sin un vencimiento, los exchanges usan un <a href=\"/funding/\">pago de funding</a> recurrente entre longs y shorts. Ese mecanismo sustituye a la liquidación por vencimiento.</p>\n<h2>Por qué los perps dominan en cripto</h2><p>Los perps permiten a los traders mantener apalancamiento de forma indefinida sin rollover, y por eso constituyen la inmensa mayoría del volumen de derivados de cripto. La contrapartida es el funding: con apalancamiento alto puede drenar una posición de forma silenciosa incluso cuando el precio está plano.</p>","faq":[["¿Vencen los contratos perpetuos?","No. Los swaps perpetuos nunca vencen — un pago de funding recurrente mantiene su precio ligado al spot en lugar de una fecha de liquidación."],["¿Cuál es la diferencia entre futuros y perpetuos?","Los futuros con vencimiento se liquidan en una fecha de expiración, mientras que los perpetuos corren indefinidamente y usan pagos de funding para mantenerse cerca del spot. El trading de cripto está dominado por los perpetuos."]]},"long-vs-short-crypto":{"title":"Ir long vs short en cripto explicado","desc":"Qué significa ir long o short con apalancamiento, cómo gana o pierde dinero cada lado, y en qué se diferencia la liquidación.","toolLabel":"Practica long y short","body":"<h2>Ir long</h2><p>Un <strong>long</strong> apuesta a que el precio subirá. Ganas a medida que el precio sube y pierdes a medida que cae. Un long se liquida cuando el precio cae lo suficiente como para que tu margen ya no pueda cubrir la pérdida.</p>\n<h2>Ir short</h2><p>Un <strong>short</strong> apuesta a que el precio caerá. Ganas a medida que el precio cae y pierdes a medida que sube — operar en corto te permite ganar dinero en una tendencia bajista. Un short se liquida cuando el precio sube lo suficiente en tu contra.</p>\n<h2>El riesgo no es simétrico</h2><p>Un long solo puede caer hasta cero, pero un short tiene una pérdida teórica ilimitada si el precio sigue subiendo — por eso los short squeezes pueden ser violentos. En cualquier caso, el apalancamiento determina lo cerca que queda tu <a href=\"/guides/what-is-liquidation-price/\">precio de liquidación</a> de la entrada. Prueba ambos lados sin riesgo en <a href=\"/paper-trade\">Paper Trade</a>.</p>","faq":[["¿Qué significa ir short en cripto?","Ir short significa apostar a que el precio caerá: ganas cuando baja y pierdes cuando sube, lo que te permite ganar dinero en una tendencia bajista."],["¿Es más arriesgado ir short que ir long?","Un short tiene una pérdida teórica ilimitada si el precio sigue subiendo, mientras que un long solo puede caer hasta cero — así que un short sin cobertura puede ser más arriesgado, y los short squeezes pueden ser bruscos."]]},"what-is-mark-price":{"title":"¿Qué es el mark price en los futuros de cripto?","desc":"Por qué los exchanges liquidan según el mark price y no el last price, y cómo te protege de ser barrido por una mecha en un libro de órdenes con poca liquidez.","toolLabel":"Calculadora de liquidación","body":"<h2>Last price vs mark price</h2><p>El <strong>last price</strong> es simplemente la operación más reciente en ese exchange. El <strong>mark price</strong> es una referencia más justa — normalmente construida a partir de un índice de varios mercados spot más una base de funding — que suaviza los picos de un solo exchange.</p>\n<h2>Por qué importa</h2><p>Los exchanges calculan tu PnL no realizado y tu <a href=\"/guides/what-is-liquidation-price/\">liquidación</a> según el <strong>mark price</strong>, no el last price. Esto te protege de ser liquidado por una mecha breve en un libro con poca liquidez que no refleja el mercado real.</p>\n<h2>Qué vigilar</h2><p>En mercados rápidos, el last price puede dispararse muy por encima del mark price. Tu posición se juzga según el mark, así que compruébalo — y no el last price parpadeante — cuando estés cerca de tu nivel de liquidación.</p>","faq":[["¿Por qué los exchanges usan el mark price para la liquidación?","El mark price es un valor justo basado en un índice que suaviza los picos de un solo exchange, de modo que una mecha breve en un libro de órdenes con poca liquidez no pueda liquidar erróneamente una posición sana."],["¿Es el mark price lo mismo que el last price?","No. El last price es la operación más reciente en ese exchange; el mark price es un valor más justo basado en un índice que se usa para calcular el PnL y las liquidaciones."]]}},"pt":{"how-to-read-funding-rates":{"title":"Como Ler as Taxas de Funding em Cripto","desc":"Um guia em linguagem simples sobre as taxas de funding dos perpétuos: o que significam o funding positivo e negativo, como identificar longs e shorts sobrelotados e como aproveitar os extremos de funding.","toolLabel":"Scanner de funding ao vivo","body":"<h2>O que é uma taxa de funding</h2><p>Num futuro perpétuo não há vencimento, por isso as exchanges usam um pequeno pagamento recorrente — a <strong>taxa de funding</strong> — para manter o preço do perp colado ao spot. Normalmente é trocada de 8 em 8 horas entre longs e shorts.</p>\n<h2>Funding positivo vs negativo</h2><p>O <strong>funding positivo</strong> significa que o perp transaciona acima do spot, por isso <em>os longs pagam aos shorts</em> — o mercado está inclinado para o lado long. O <strong>funding negativo</strong> significa que o perp transaciona abaixo do spot, por isso <em>os shorts pagam aos longs</em> — o mercado está inclinado para o lado short.</p>\n<h2>Ler os extremos</h2><p>Quando o funding está muito positivo, os longs estão sobrelotados e a pagar um prémio para manter a posição; uma estagnação no preço pode despoletar um <strong>long squeeze</strong>. Quando o funding está profundamente negativo, os shorts estão sobrelotados e um ressalto pode forçar um <strong>short squeeze</strong>. O funding é mais forte como sinal quando combinado com o <a href=\"/open-interest/\">open interest</a> e o <a href=\"/long-short/\">posicionamento long/short</a>.</p>\n<h2>Atenção ao custo</h2><p>Com alavancagem elevada, o custo do funding compõe-se rapidamente e pode drenar discretamente uma posição mesmo com o preço parado. Tem sempre isto em conta no teu tempo de permanência na posição.</p>","faq":[["O que significa uma taxa de funding elevada?","Um funding positivo elevado significa que o mercado está fortemente long e os longs estão a pagar para manter a posição — um sinal de longs sobrelotados que pode alimentar um short squeeze numa correção."],["O funding negativo é altista?","O funding negativo significa que os shorts estão sobrelotados e a pagar aos longs. É frequentemente lido de forma contrária, como um cenário para um squeeze em alta, mas é apenas um sinal entre funding, open interest e preço."]]},"how-to-read-liquidations":{"title":"Como Ler as Liquidações em Cripto","desc":"Compreende as liquidações em cripto: o que são, a diferença entre liquidações de longs e de shorts, e como as cascatas de liquidação geram volatilidade.","toolLabel":"Tracker de liquidações ao vivo","body":"<h2>O que é uma liquidação</h2><p>Uma <strong>liquidação</strong> acontece quando uma exchange força o fecho de uma posição alavancada porque a margem do trader já não consegue cobrir a perda. A posição é fechada a mercado e o trader perde a sua margem. Com alavancagem elevada, o preço de liquidação fica muito próximo da entrada.</p>\n<h2>Liquidações de longs vs shorts</h2><p>As <strong>liquidações de longs</strong> são compradores sobrealavancados eliminados quando o preço cai. As <strong>liquidações de shorts</strong> são vendedores eliminados quando o preço sobe. Um grande pico unilateral marca frequentemente um extremo local — uma vaga de liquidações de longs pode marcar um fundo, uma onda de liquidações de shorts pode alimentar um rally.</p>\n<h2>Cascatas de liquidação</h2><p>As liquidações funcionam como combustível. Quando o preço atinge uma zona carregada de alavancagem, as ordens forçadas empurram o preço ainda mais, despoletando mais liquidações — uma <strong>cascata</strong>. Observar onde a alavancagem está mais concentrada ajuda-te a evitar o trade sobrelotado.</p>\n<h2>Usa em conjunto com o resto</h2><p>Combina as liquidações com o <a href=\"/funding/\">funding</a> e o <a href=\"/open-interest/\">open interest</a>: uma queda do open interest costuma seguir-se a uma cascata, à medida que a alavancagem é eliminada.</p>","faq":[["O que provoca uma liquidação?","Uma posição é liquidada quando o preço se move contra ela o suficiente para que a margem já não consiga cobrir a perda, pelo que a exchange a fecha automaticamente."],["As liquidações de longs ou de shorts são altistas?","Um pico de liquidações de longs (numa queda) pode marcar um fundo local; um pico de liquidações de shorts (num rally) pode alimentar um squeeze em alta."]]},"what-is-open-interest":{"title":"O Que É o Open Interest em Cripto?","desc":"O open interest explicado: como difere do volume, o que sinalizam o OI crescente e decrescente, e como ler o OI em conjunto com o preço.","toolLabel":"Tracker de open interest ao vivo","body":"<h2>Open interest vs volume</h2><p>O <strong>open interest (OI)</strong> é o valor total de todas as posições abertas de futuros perpétuos numa moeda. Ao contrário do volume — que conta cada transação — o OI mede quanta alavancagem está atualmente <em>aberta</em> no mercado.</p>\n<h2>OI crescente e decrescente</h2><p>Um OI crescente significa que estão a entrar novas posições e alavancagem fresca. Um OI decrescente significa que os traders estão a fechar posições. Uma queda súbita do OI costuma seguir-se a uma <a href=\"/liquidations/\">cascata de liquidação</a>, à medida que as posições sobrealavancadas são eliminadas.</p>\n<h2>Ler o OI com o preço</h2><p><strong>Preço a subir + OI a subir</strong> = dinheiro novo a sustentar o movimento (tendência mais forte). <strong>Preço a subir + OI a descer</strong> = cobertura de shorts em vez de procura fresca. Uma acumulação forte de OI mais um <a href=\"/funding/\">funding</a> unilateral assinala um cenário sobrelotado e frágil.</p>","faq":[["Um open interest elevado é altista ou baixista?","Nenhum dos dois por si só — depende do preço. Um OI crescente com preço a subir sugere novos compradores; um OI crescente com preço a descer sugere novos vendedores."],["O que significa um open interest decrescente?","Um OI decrescente significa que as posições estão a ser fechadas, muitas vezes depois de uma cascata de liquidação eliminar a alavancagem do mercado."]]},"long-short-ratio-explained":{"title":"O Rácio Long/Short em Cripto Explicado","desc":"O que o rácio long/short te diz sobre o posicionamento dos traders, como ler os extremos sobrelotados e porque é melhor usá-lo de forma contrária.","toolLabel":"Rácio long/short ao vivo","body":"<h2>O que mede</h2><p>O <strong>rácio long/short</strong> mostra que percentagem das contas dos traders está posicionada long versus short numa moeda. É um instantâneo do posicionamento e do sentimento da multidão.</p>\n<h2>Ler a multidão</h2><p>Os traders experientes leem frequentemente os extremos de forma <strong>contrária</strong>. Quando a maioria das contas já está long, o impulso comprador está em grande parte esgotado e a multidão fica exposta a um <strong>long squeeze</strong>. Quando a multidão está fortemente short, um ressalto pode forçar um <strong>short squeeze</strong>.</p>\n<h2>Um sinal, não o quadro completo</h2><p>Um livro sobrelotado pode permanecer sobrelotado enquanto uma tendência corre. Combina o rácio com o <a href=\"/funding/\">funding</a> (o que a multidão paga para manter a posição) e as <a href=\"/liquidations/\">liquidações</a> (onde a alavancagem é eliminada) antes de agires.</p>","faq":[["Qual é um bom rácio long/short?","Não existe um único valor bom — é mais útil nos extremos. Uma fatia de longs muito elevada alerta para longs sobrelotados; uma fatia de shorts muito elevada alerta para shorts sobrelotados."],["Como é que os traders usam o rácio long/short?","Muitos leem-no de forma contrária: indo contra o lado sobreposicionado e confirmando sempre com o funding, o open interest e a ação de preço."]]},"what-is-liquidation-price":{"title":"O Que É um Preço de Liquidação em Cripto?","desc":"O que é um preço de liquidação, como a alavancagem o aproxima da tua entrada e como calculá-lo antes de abrires uma posição.","toolLabel":"Calculadora de preço de liquidação","body":"<h2>O que é</h2><p>O teu <strong>preço de liquidação</strong> é o preço a que uma exchange força o fecho da tua posição alavancada porque a tua margem já não consegue cobrir a perda. Ultrapassa-o e perdes a tua margem. Conhecê-lo antes de entrares é o número mais importante no trading alavancado.</p>\n<h2>Como a alavancagem o move</h2><p>Quanto maior for a tua alavancagem, mais próximo o preço de liquidação fica da tua entrada. A 5× um long é liquidado com uma queda de cerca de 20%; a 100× é com um movimento de cerca de 1%. É por isso que a alavancagem elevada é tão frágil — um pavio normal pode eliminar uma posição.</p>\n<h2>Como é calculado</h2><p>Para um long isolado, liquidação ≈ entrada × (1 − 1/alavancagem + taxa de margem de manutenção); nos shorts o sinal inverte-se. O valor exato depende da margem de manutenção e das taxas da exchange, por isso confirma-o com uma <a href=\"/btc-liquidation-calculator/\">calculadora de liquidação</a> para a tua moeda e alavancagem.</p>\n<h2>Dá-lhe espaço</h2><p>Define o teu tamanho e alavancagem para que o preço de liquidação fique para além do ruído — depois de suportes e resistências óbvios e de pavios recentes — e não em cima da tua entrada. Vê também <a href=\"/guides/how-to-avoid-liquidation/\">como evitar a liquidação</a>.</p>","faq":[["Como se calcula o preço de liquidação?","Aproximadamente, liquidação ≈ entrada × (1 − 1/alavancagem + margem de manutenção) para um long, com os shorts invertidos. O valor preciso depende da taxa de margem de manutenção e das taxas da exchange."],["Uma alavancagem maior significa um preço de liquidação mais próximo?","Sim. A 100× o preço de liquidação fica apenas a cerca de 1% da entrada, enquanto a 5× fica mais perto dos 20% — uma alavancagem maior deixa quase nenhum espaço para o preço se mover contra ti."]]},"isolated-vs-cross-margin":{"title":"Margem Isolada vs Cruzada Explicada","desc":"A diferença entre margem isolada e cruzada, o compromisso de risco e qual o modo que se adequa a cada estilo de trader.","toolLabel":"Pratica no Paper Trade","body":"<h2>Margem isolada</h2><p>Na <strong>margem isolada</strong>, apenas a margem que atribuis a uma posição está em risco. Se for liquidada, a perda fica limitada a essa margem e o resto do teu saldo permanece intacto. É o padrão mais seguro para trades de alavancagem elevada.</p>\n<h2>Margem cruzada</h2><p>Na <strong>margem cruzada</strong>, o saldo total da tua conta sustenta a posição. Isso afasta mais o preço de liquidação, mas um único mau trade pode drenar a conta inteira, e não apenas a margem de uma posição.</p>\n<h2>Qual usar</h2><p>A maioria dos traders usa <strong>isolada</strong> para cenários de risco definido e alavancagem elevada, e <strong>cruzada</strong> para posições de menor alavancagem que gerem ou cobrem ativamente. O compromisso: a isolada limita a tua perda; a cruzada reduz o risco de liquidação mas aumenta a tua perda máxima. Em qualquer dos casos, verifica primeiro o <a href=\"/guides/what-is-liquidation-price/\">preço de liquidação</a>.</p>","faq":[["A margem isolada ou cruzada é mais segura?","A isolada é mais segura para limitar perdas — apenas a margem atribuída está em risco. A margem cruzada é mais difícil de liquidar mas põe todo o teu saldo em jogo."],["Quando devo usar margem cruzada?","A cruzada adequa-se a posições de menor alavancagem que geres ou cobres ativamente, onde queres que o trade sobreviva à volatilidade sem teres de reforçar a margem."]]},"how-to-calculate-position-size":{"title":"Como Calcular o Tamanho da Posição em Cripto","desc":"Dimensiona cada trade pelo risco e não pelo instinto: como calcular o tamanho da posição a partir da tua conta, da distância do stop e do risco por trade.","toolLabel":"Calculadora de tamanho de posição","body":"<h2>Risco primeiro, tamanho depois</h2><p>O dimensionamento profissional parte de um número: quanto estás disposto a perder no trade. Uma regra comum é arriscar <strong>1–2% da tua conta por trade</strong>. O tamanho da tua posição decorre depois da distância do teu stop.</p>\n<h2>A fórmula</h2><p>Tamanho da posição = (conta × risco %) ÷ (distância do stop %). Se arriscares $20 e o teu stop estiver a 2% de distância, assumes $1,000 de exposição — independentemente da alavancagem. A alavancagem só define a margem necessária, não o teu risco.</p>\n<h2>A alavancagem não é o risco</h2><p>É este o ponto que a maioria dos iniciantes ignora: o teu risco é definido pelo tamanho e pelo stop, não pela alavancagem. 10× numa posição pequena e bem protegida por stop pode ser muito mais seguro do que 2× numa sobredimensionada. Usa uma <a href=\"/calculators?c=size\">calculadora de tamanho de posição</a> para que cada trade arrisque o mesmo montante, e mantém um olho no teu <a href=\"/guides/what-is-liquidation-price/\">preço de liquidação</a>.</p>","faq":[["Quanto devo arriscar por trade?","Uma orientação muito usada é 1–2% da tua conta por trade, para que uma série de perdas não possa rebentar com a conta."],["A alavancagem altera o tamanho da minha posição?","Não — o teu risco é definido pelo tamanho da posição e pela distância do stop. A alavancagem só determina a margem necessária para manter essa posição."]]},"what-is-leverage-in-crypto":{"title":"O Que É a Alavancagem no Trading de Cripto?","desc":"A alavancagem explicada de forma simples: como funciona 10× ou 100×, o que faz ao teu preço de liquidação e como usá-la sem rebentares.","toolLabel":"Calculadora de liquidação","body":"<h2>O que a alavancagem faz</h2><p>A <strong>alavancagem</strong> permite-te controlar uma posição maior do que a tua margem. A 10× uma margem de $100 controla $1,000 de exposição, por isso um movimento de 1% torna-se uma variação de 10% na tua margem — ganhos e perdas são ambos amplificados.</p>\n<h2>O senão: a liquidação</h2><p>O reverso é o teu <a href=\"/guides/what-is-liquidation-price/\">preço de liquidação</a>. Quanto maior a alavancagem, menor o movimento que te elimina — cerca de 1% a 100×, 2% a 50×, 10% a 10×. Um potencial amplificado vem com uma fragilidade amplificada.</p>\n<h2>Usá-la com bom senso</h2><p>A alavancagem é uma ferramenta de eficiência de capital, não um número para maximizar. Dimensiona pelo <a href=\"/guides/how-to-calculate-position-size/\">risco</a>, mantém o preço de liquidação para além do ruído e lembra-te de que os custos de funding escalam com o tamanho da posição, não com a margem.</p>","faq":[["O que significa alavancagem de 10x?","10× significa que a tua posição é dez vezes a tua margem: $100 controlam $1,000, por isso um movimento de preço de 1% equivale a um movimento de 10% na tua margem — em ambas as direções."],["A alavancagem elevada é má?","A alavancagem elevada não é intrinsecamente má, mas põe o teu preço de liquidação muito perto da entrada. A maioria dos rebentamentos vem do sobredimensionamento com alavancagem elevada, e não da alavancagem em si."]]},"maker-vs-taker-fees":{"title":"Taxas Maker vs Taker Explicadas","desc":"O que são as taxas maker e taker, porque é que os takers pagam mais e como a diferença se acumula para traders de futuros ativos.","toolLabel":"Comparar taxas das exchanges","body":"<h2>A diferença</h2><p>Uma ordem <strong>maker</strong> adiciona liquidez ao livro — uma ordem limite que fica em espera, à espera de ser preenchida. Uma ordem <strong>taker</strong> remove liquidez — uma ordem a mercado, ou uma limite que preenche de imediato, que aceita uma oferta existente. As exchanges cobram mais aos takers porque os makers fornecem a liquidez contra a qual todos transacionam.</p>\n<h2>Taxas típicas</h2><p>Nos principais perpétuos USDT, as taxas maker rondam os 0.02% e as taker os 0.04–0.06%. Parece insignificante, mas um day trader que faz dezenas de ida-e-volta paga-a vezes sem conta — e os takers pagam-na de ambos os lados.</p>\n<h2>Como pagar menos</h2><p>Usa <strong>ordens limite</strong> em espera para qualificares para a taxa maker sempre que possível, mantém o token da exchange para um desconto e sobe os níveis VIP à medida que o volume cresce. Se as taxas são a tua prioridade, <a href=\"/lowest-fee-crypto-exchange/\">compara primeiro as exchanges pela taxa taker</a>.</p>","faq":[["Porque é que os takers pagam mais do que os makers?","Os takers removem liquidez ao preencher ordens existentes, enquanto os makers adicionam liquidez ao colocar ordens em espera no livro. As exchanges recompensam os makers com taxas mais baixas porque mantêm o mercado líquido."],["Como pago taxas maker?","Coloca ordens limite que fiquem em espera no livro em vez de ordens a mercado que preenchem de imediato. Se a tua ordem espera para ser correspondida, qualifica-se para a taxa maker mais baixa."]]},"how-to-avoid-liquidation":{"title":"Como Evitar a Liquidação no Trading de Cripto","desc":"Formas práticas de impedir que uma posição alavancada seja liquidada — do dimensionamento e stops ao modo de margem e ao funding.","toolLabel":"Verifica o teu preço de liquidação","body":"<h2>Conhece o preço antes de entrares</h2><p>Calcula primeiro o teu <a href=\"/guides/what-is-liquidation-price/\">preço de liquidação</a> e certifica-te de que fica para além de pavios recentes e de suportes e resistências óbvios — e não mesmo ao lado da tua entrada.</p>\n<h2>Usa menos alavancagem do que podes</h2><p>O facto de uma plataforma oferecer 125× não significa que devas usá-la. Uma alavancagem menor afasta o preço de liquidação da entrada e dá-te espaço para teres razão ao longo do tempo.</p>\n<h2>Define sempre um stop-loss</h2><p>Um stop fecha-te a um preço que <em>tu</em> escolhes, antes que o motor de liquidação da exchange o faça por ti a um pior.</p>\n<h2>Dimensiona pelo risco</h2><p>Arrisca uns fixos 1–2% por trade usando uma <a href=\"/guides/how-to-calculate-position-size/\">calculadora de tamanho de posição</a>, para que nenhum trade isolado possa causar danos reais.</p>\n<h2>Prefere a margem isolada</h2><p>A <a href=\"/guides/isolated-vs-cross-margin/\">margem isolada</a> limita a perda a uma posição. Adiciona margem de forma deliberada, e não em pânico.</p>\n<h2>Cuidado com o funding</h2><p>Com alavancagem elevada, o <a href=\"/funding/\">funding</a> drena discretamente uma posição mesmo com o preço parado — tem isso em conta nas permanências longas.</p>","faq":[["Qual é a melhor forma de evitar a liquidação?","Usa menos alavancagem, define sempre um stop-loss, dimensiona por uma percentagem de risco fixa e mantém o teu preço de liquidação bem para além da volatilidade recente."],["Um stop-loss evita a liquidação?","Um stop-loss fecha a tua posição ao preço que escolheste antes de a liquidação da exchange disparar, por isso, na prática, evita a maioria das liquidações — desde que preencha em mercados rápidos."]]},"perpetual-vs-futures":{"title":"Perpétuo vs Futuros: Qual É a Diferença?","desc":"Swaps perpétuos versus futuros com data: vencimento, funding e porque é que os perps dominam o trading alavancado em cripto.","toolLabel":"Scanner de funding ao vivo","body":"<h2>Futuros com data</h2><p>Um <strong>contrato de futuros</strong> tradicional tem uma data de vencimento. Nessa data, liquida ao preço spot, por isso o preço do contrato converge para o spot à medida que o vencimento se aproxima. Transaciona-lo durante um prazo fixo e depois deixa de existir.</p>\n<h2>Swaps perpétuos</h2><p>Um <strong>perpétuo</strong> (\"perp\") nunca vence. Para manter o seu preço colado ao spot sem um vencimento, as exchanges usam um <a href=\"/funding/\">pagamento de funding</a> recorrente entre longs e shorts. Esse mecanismo substitui a liquidação.</p>\n<h2>Porque é que os perps dominam em cripto</h2><p>Os perps permitem aos traders manter alavancagem indefinidamente sem rollover, e é por isso que representam a esmagadora maioria do volume de derivados em cripto. O compromisso é o funding: com alavancagem elevada, pode drenar discretamente uma posição mesmo com o preço parado.</p>","faq":[["Os contratos perpétuos vencem?","Não. Os swaps perpétuos nunca vencem — um pagamento de funding recorrente mantém o seu preço ligado ao spot em vez de uma data de liquidação."],["Qual é a diferença entre futuros e perpétuos?","Os futuros com data liquidam numa data de vencimento, enquanto os perpétuos correm indefinidamente e usam pagamentos de funding para se manterem perto do spot. O trading de cripto é dominado pelos perpétuos."]]},"long-vs-short-crypto":{"title":"Ir Long vs Short em Cripto Explicado","desc":"O que significa ir long ou short com alavancagem, como cada lado ganha ou perde dinheiro e como a liquidação difere.","toolLabel":"Pratica long e short","body":"<h2>Ir long</h2><p>Um <strong>long</strong> aposta que o preço vai subir. Lucras à medida que o preço sobe e perdes à medida que cai. Um long é liquidado quando o preço cai o suficiente para que a tua margem já não consiga cobrir a perda.</p>\n<h2>Ir short</h2><p>Um <strong>short</strong> aposta que o preço vai cair. Lucras à medida que o preço cai e perdes à medida que sobe — o short permite-te ganhar dinheiro numa tendência de baixa. Um short é liquidado quando o preço sobe o suficiente contra ti.</p>\n<h2>O risco não é simétrico</h2><p>Um long só pode cair até zero, mas um short tem perda teórica ilimitada se o preço continuar a subir — e é por isso que os short squeezes podem ser violentos. Em qualquer dos casos, a alavancagem define quão próximo o teu <a href=\"/guides/what-is-liquidation-price/\">preço de liquidação</a> fica da entrada. Testa os dois lados sem risco no <a href=\"/paper-trade\">Paper Trade</a>.</p>","faq":[["O que significa ir short em cripto?","Ir short significa apostar que o preço vai cair: lucras quando cai e perdes quando sobe, o que te permite ganhar dinheiro numa tendência de baixa."],["Ir short é mais arriscado do que ir long?","Um short tem perda teórica ilimitada se o preço continuar a subir, enquanto um long só pode cair até zero — por isso um short sem cobertura pode ser mais arriscado, e os short squeezes podem ser abruptos."]]},"what-is-mark-price":{"title":"O Que É o Mark Price em Futuros de Cripto?","desc":"Porque é que as exchanges liquidam pelo mark price e não pelo último preço, e como isso te protege de seres eliminado por um pavio num livro de ordens fino.","toolLabel":"Calculadora de liquidação","body":"<h2>Último preço vs mark price</h2><p>O <strong>último preço</strong> é simplesmente a transação mais recente nessa exchange. O <strong>mark price</strong> é uma referência mais justa — normalmente construída a partir de um índice de vários mercados spot mais uma base de funding — que suaviza os picos de uma única exchange.</p>\n<h2>Porque é que importa</h2><p>As exchanges calculam o teu PnL não realizado e a tua <a href=\"/guides/what-is-liquidation-price/\">liquidação</a> face ao <strong>mark price</strong>, e não ao último preço. Isto protege-te de seres liquidado por um pavio breve num livro fino que não reflete o verdadeiro mercado.</p>\n<h2>O que observar</h2><p>Em mercados rápidos, o último preço pode disparar bem para além do mark price. A tua posição é avaliada pelo mark, por isso verifica-o — e não o último preço a piscar — quando estiveres perto do teu nível de liquidação.</p>","faq":[["Porque é que as exchanges usam o mark price para a liquidação?","O mark price é um valor justo baseado num índice que suaviza os picos de uma única exchange, por isso um pavio breve num livro de ordens fino não pode liquidar erradamente uma posição saudável."],["O mark price é o mesmo que o último preço?","Não. O último preço é a transação mais recente nessa exchange; o mark price é um valor mais justo baseado num índice, usado para calcular o PnL e as liquidações."]]}},"fr":{"how-to-read-funding-rates":{"title":"Comment lire les funding rates crypto","desc":"Un guide clair sur les funding rates des perpétuels : ce que signifient un funding positif et négatif, comment repérer les longs et les shorts surchargés, et comment exploiter les extrêmes de funding.","toolLabel":"Scanner de funding en direct","body":"<h2>Ce qu’est un funding rate</h2><p>Sur un future perpétuel il n’y a pas d’échéance, alors les plateformes utilisent un petit paiement récurrent — le <strong>funding rate</strong> — pour maintenir le prix du perp ancré au spot. Il est généralement échangé toutes les 8 heures entre les longs et les shorts.</p>\n<h2>Funding positif vs négatif</h2><p>Un <strong>funding positif</strong> signifie que le perp se négocie au-dessus du spot, donc <em>les longs paient les shorts</em> — le marché penche du côté long. Un <strong>funding négatif</strong> signifie que le perp se négocie en dessous du spot, donc <em>les shorts paient les longs</em> — le marché penche du côté short.</p>\n<h2>Lire les extrêmes</h2><p>Quand le funding est très positif, les longs sont surchargés et paient une prime pour rester en position ; un blocage du prix peut déclencher un <strong>long squeeze</strong>. Quand le funding est profondément négatif, les shorts sont surchargés et un rebond peut provoquer un <strong>short squeeze</strong>. Le funding est le plus puissant en tant que signal aux côtés de l’<a href=\"/open-interest/\">open interest</a> et du <a href=\"/long-short/\">positionnement long/short</a>.</p>\n<h2>Surveillez le coût</h2><p>À fort levier, le coût du funding se compose rapidement et peut discrètement vider une position même quand le prix est plat. Intégrez-le toujours à votre durée de détention.</p>","faq":[["Que signifie un funding rate élevé ?","Un funding fortement positif signifie que le marché est massivement long et que les longs paient pour rester en position — un signe de longs surchargés qui peut alimenter un short squeeze lors d’un repli."],["Un funding négatif est-il haussier ?","Un funding négatif signifie que les shorts sont surchargés et paient les longs. On le lit souvent à contre-courant comme une configuration propice à un squeeze à la hausse, mais ce n’est qu’un signal parmi le funding, l’open interest et le prix."]]},"how-to-read-liquidations":{"title":"Comment lire les liquidations crypto","desc":"Comprenez les liquidations crypto : ce qu’elles sont, la différence entre liquidations longues et courtes, et comment les cascades de liquidations alimentent la volatilité.","toolLabel":"Tracker de liquidations en direct","body":"<h2>Ce qu’est une liquidation</h2><p>Une <strong>liquidation</strong>, c’est lorsqu’une plateforme ferme de force une position à effet de levier parce que la marge du trader ne peut plus couvrir la perte. La position est fermée au marché et le trader perd sa marge. À fort levier, le prix de liquidation se situe très près du prix d’entrée.</p>\n<h2>Liquidations longues vs courtes</h2><p>Les <strong>liquidations longues</strong> sont des acheteurs sur-leviérés balayés quand le prix chute. Les <strong>liquidations courtes</strong> sont des vendeurs balayés quand le prix monte. Un gros pic unilatéral marque souvent un extrême local — un déluge de liquidations longues peut marquer un creux, une vague de liquidations courtes peut alimenter un rallye.</p>\n<h2>Les cascades de liquidations</h2><p>Les liquidations agissent comme du carburant. Quand le prix atteint une zone bourrée de levier, les ordres forcés poussent le prix plus loin, déclenchant davantage de liquidations — une <strong>cascade</strong>. Observer où le levier est le plus concentré aide à éviter le trade surchargé.</p>\n<h2>Utilisez-les avec le reste</h2><p>Associez les liquidations au <a href=\"/funding/\">funding</a> et à l’<a href=\"/open-interest/\">open interest</a> : une baisse de l’open interest suit généralement une cascade, à mesure que le levier est balayé.</p>","faq":[["Qu’est-ce qui provoque une liquidation ?","Une position est liquidée quand le prix évolue contre elle suffisamment loin pour que la marge ne puisse plus couvrir la perte, alors la plateforme la ferme automatiquement."],["Les liquidations longues ou courtes sont-elles haussières ?","Un pic de liquidations longues (lors d’une chute) peut marquer un creux local ; un pic de liquidations courtes (lors d’un rallye) peut alimenter un squeeze à la hausse."]]},"what-is-open-interest":{"title":"Qu’est-ce que l’open interest en crypto ?","desc":"L’open interest expliqué : en quoi il diffère du volume, ce que signalent une OI en hausse et en baisse, et comment lire l’OI aux côtés du prix.","toolLabel":"Tracker d’open interest en direct","body":"<h2>Open interest vs volume</h2><p>L’<strong>open interest (OI)</strong> est la valeur totale de toutes les positions ouvertes sur les futures perpétuels d’une crypto. Contrairement au volume — qui compte chaque transaction — l’OI mesure la quantité de levier actuellement <em>ouverte</em> sur le marché.</p>\n<h2>OI en hausse et en baisse</h2><p>Une OI en hausse signifie que de nouvelles positions et un levier frais entrent. Une OI en baisse signifie que les traders clôturent. Une chute soudaine de l’OI suit généralement une <a href=\"/liquidations/\">cascade de liquidations</a>, à mesure que les positions sur-leviérées sont balayées.</p>\n<h2>Lire l’OI avec le prix</h2><p><strong>Prix en hausse + OI en hausse</strong> = de l’argent neuf soutient le mouvement (tendance plus forte). <strong>Prix en hausse + OI en baisse</strong> = couverture de shorts plutôt qu’une demande fraîche. Une forte accumulation d’OI plus un <a href=\"/funding/\">funding</a> unilatéral signalent une configuration surchargée et fragile.</p>","faq":[["Un open interest élevé est-il haussier ou baissier ?","Ni l’un ni l’autre en soi — cela dépend du prix. Une OI en hausse avec un prix en hausse suggère de nouveaux acheteurs ; une OI en hausse avec un prix en baisse suggère de nouveaux vendeurs."],["Que signifie une baisse de l’open interest ?","Une OI en baisse signifie que des positions sont clôturées, souvent après qu’une cascade de liquidations a balayé le levier hors du marché."]]},"long-short-ratio-explained":{"title":"Le ratio long/short crypto expliqué","desc":"Ce que le ratio long/short vous dit sur le positionnement des traders, comment lire les extrêmes surchargés, et pourquoi il s’utilise au mieux à contre-courant.","toolLabel":"Ratio long/short en direct","body":"<h2>Ce qu’il mesure</h2><p>Le <strong>ratio long/short</strong> montre quel pourcentage des comptes des traders est positionné long par rapport à short sur une crypto. C’est un instantané du positionnement et du sentiment de la foule.</p>\n<h2>Lire la foule</h2><p>Les traders expérimentés lisent souvent les extrêmes <strong>à contre-courant</strong>. Quand la plupart des comptes sont déjà longs, l’achat est largement épuisé et la foule est exposée à un <strong>long squeeze</strong>. Quand la foule est massivement short, un rebond peut provoquer un <strong>short squeeze</strong>.</p>\n<h2>Un signal, pas le tableau complet</h2><p>Un carnet surchargé peut le rester pendant qu’une tendance se déroule. Combinez le ratio avec le <a href=\"/funding/\">funding</a> (ce que la foule paie pour rester en position) et les <a href=\"/liquidations/\">liquidations</a> (où le levier est balayé) avant d’agir.</p>","faq":[["Qu’est-ce qu’un bon ratio long/short ?","Il n’y a pas de valeur unique idéale — il est le plus utile aux extrêmes. Une part très élevée de longs avertit de longs surchargés ; une part très élevée de shorts avertit de shorts surchargés."],["Comment les traders utilisent-ils le ratio long/short ?","Beaucoup le lisent à contre-courant : en fadant le côté trop positionné, et en confirmant toujours avec le funding, l’open interest et l’action des prix."]]},"what-is-liquidation-price":{"title":"Qu’est-ce qu’un prix de liquidation en crypto ?","desc":"Ce qu’est un prix de liquidation, comment le levier le rapproche de votre entrée, et comment le calculer avant d’ouvrir une position.","toolLabel":"Calculateur de prix de liquidation","body":"<h2>Ce que c’est</h2><p>Votre <strong>prix de liquidation</strong> est le prix auquel une plateforme ferme de force votre position à effet de levier parce que votre marge ne peut plus couvrir la perte. Franchissez-le et vous perdez votre marge. Le connaître avant d’entrer est le chiffre le plus important du trading à effet de levier.</p>\n<h2>Comment le levier le déplace</h2><p>Plus votre levier est élevé, plus le prix de liquidation se rapproche de votre entrée. À 5× un long est liquidé sur une baisse d’environ 20 % ; à 100× c’est un mouvement d’environ 1 %. C’est pourquoi le fort levier est si fragile — une mèche ordinaire peut anéantir une position.</p>\n<h2>Comment il se calcule</h2><p>Pour un long isolé, liquidation ≈ entrée × (1 − 1/levier + taux de marge de maintenance) ; les shorts inversent le signe. Le chiffre exact dépend de la marge de maintenance et des frais de la plateforme, alors confirmez-le avec un <a href=\"/btc-liquidation-calculator/\">calculateur de liquidation</a> pour votre crypto et votre levier.</p>\n<h2>Laissez-lui de la marge</h2><p>Réglez votre taille et votre levier pour que le prix de liquidation se situe au-delà du bruit — au-delà des supports et résistances évidents et des mèches récentes — et non collé à votre entrée. Voir aussi <a href=\"/guides/how-to-avoid-liquidation/\">comment éviter la liquidation</a>.</p>","faq":[["Comment le prix de liquidation est-il calculé ?","Grossièrement, liquidation ≈ entrée × (1 − 1/levier + marge de maintenance) pour un long, les shorts étant inversés. La valeur précise dépend du taux de marge de maintenance et des frais de la plateforme."],["Un levier plus élevé signifie-t-il un prix de liquidation plus proche ?","Oui. À 100× le prix de liquidation n’est qu’à environ 1 % de l’entrée, tandis qu’à 5× il est plus proche de 20 % — un levier plus élevé ne laisse presque aucune marge pour que le prix évolue contre vous."]]},"isolated-vs-cross-margin":{"title":"Marge isolée vs marge croisée expliquée","desc":"La différence entre marge isolée et marge croisée, le compromis de risque, et quel mode convient à quel style de trader.","toolLabel":"S’entraîner sur Paper Trade","body":"<h2>Marge isolée</h2><p>En <strong>marge isolée</strong>, seule la marge que vous affectez à une position est en jeu. Si elle est liquidée, la perte est plafonnée à cette marge et le reste de votre solde est intact. C’est le réglage par défaut le plus sûr pour les trades à fort levier.</p>\n<h2>Marge croisée</h2><p>En <strong>marge croisée</strong>, tout le solde de votre compte garantit la position. Cela éloigne le prix de liquidation, mais un seul mauvais trade peut vider tout le compte, et pas seulement la marge d’une position.</p>\n<h2>Laquelle utiliser</h2><p>La plupart des traders utilisent la marge <strong>isolée</strong> pour les configurations à risque défini et fort levier, et la marge <strong>croisée</strong> pour les positions à faible levier qu’ils gèrent activement ou couvrent. Le compromis : l’isolée plafonne votre perte ; la croisée réduit le risque de liquidation mais augmente votre perte maximale. Dans tous les cas, vérifiez d’abord le <a href=\"/guides/what-is-liquidation-price/\">prix de liquidation</a>.</p>","faq":[["La marge isolée ou croisée est-elle plus sûre ?","L’isolée est plus sûre pour plafonner les pertes — seule la marge affectée est en jeu. La marge croisée est plus difficile à liquider mais met tout votre solde en jeu."],["Quand devrais-je utiliser la marge croisée ?","La croisée convient aux positions à faible levier que vous gérez ou couvrez activement, lorsque vous voulez que le trade survive à la volatilité sans rajouter de marge."]]},"how-to-calculate-position-size":{"title":"Comment calculer la taille de position en crypto","desc":"Dimensionnez chaque trade par le risque, pas au feeling : comment déterminer la taille de position à partir de votre compte, de la distance du stop et du risque par trade.","toolLabel":"Calculateur de taille de position","body":"<h2>Le risque d’abord, la taille ensuite</h2><p>Le dimensionnement professionnel part d’un seul chiffre : combien vous êtes prêt à perdre sur le trade. Une règle courante est de risquer <strong>1–2 % de votre compte par trade</strong>. Votre taille de position découle ensuite de la distance de votre stop.</p>\n<h2>La formule</h2><p>Taille de position = (compte × risque %) ÷ (distance du stop %). Si vous risquez $20 et que votre stop est à 2 %, vous prenez $1,000 d’exposition — quel que soit le levier. Le levier ne fait que définir la marge requise, pas votre risque.</p>\n<h2>Le levier n’est pas le risque</h2><p>C’est le point que la plupart des débutants ratent : votre risque est défini par la taille et le stop, pas par le levier. 10× sur une position petite et bien stoppée peut être bien plus sûr que 2× sur une position surdimensionnée. Utilisez un <a href=\"/calculators?c=size\">calculateur de taille de position</a> pour que chaque trade risque le même montant, et gardez un œil sur votre <a href=\"/guides/what-is-liquidation-price/\">prix de liquidation</a>.</p>","faq":[["Combien devrais-je risquer par trade ?","Une ligne directrice très répandue est de 1–2 % de votre compte par trade, afin qu’une série de pertes ne puisse pas faire sauter le compte."],["Le levier change-t-il ma taille de position ?","Non — votre risque est défini par la taille de position et la distance du stop. Le levier ne fait que déterminer la marge nécessaire pour tenir cette position."]]},"what-is-leverage-in-crypto":{"title":"Qu’est-ce que le levier dans le trading crypto ?","desc":"Le levier expliqué simplement : comment fonctionne le 10× ou le 100×, ce qu’il fait à votre prix de liquidation, et comment l’utiliser sans tout faire sauter.","toolLabel":"Calculateur de liquidation","body":"<h2>Ce que fait le levier</h2><p>Le <strong>levier</strong> vous permet de contrôler une position plus grande que votre marge. À 10× une marge de $100 contrôle $1,000 d’exposition, donc un mouvement de 1 % devient une variation de 10 % sur votre marge — gains et pertes sont tous deux amplifiés.</p>\n<h2>Le piège : la liquidation</h2><p>Le revers, c’est votre <a href=\"/guides/what-is-liquidation-price/\">prix de liquidation</a>. Plus le levier est élevé, plus le mouvement qui vous anéantit est petit — environ 1 % à 100×, 2 % à 50×, 10 % à 10×. Un potentiel de hausse amplifié s’accompagne d’une fragilité amplifiée.</p>\n<h2>L’utiliser intelligemment</h2><p>Le levier est un outil d’efficacité du capital, pas un chiffre à pousser au maximum. Dimensionnez par le <a href=\"/guides/how-to-calculate-position-size/\">risque</a>, gardez le prix de liquidation au-delà du bruit, et rappelez-vous que les coûts de funding évoluent avec la taille de position, pas avec la marge.</p>","faq":[["Que signifie un levier de 10x ?","10× signifie que votre position vaut dix fois votre marge : $100 contrôle $1,000, donc un mouvement de prix de 1 % équivaut à un mouvement de 10 % sur votre marge — dans les deux sens."],["Un fort levier est-il mauvais ?","Un fort levier n’est pas intrinsèquement mauvais, mais il place votre prix de liquidation très près de l’entrée. La plupart des explosions de compte viennent du surdimensionnement à fort levier, pas du levier en lui-même."]]},"maker-vs-taker-fees":{"title":"Frais maker vs taker expliqués","desc":"Ce que sont les frais maker et taker, pourquoi les takers paient plus, et comment la différence s’accumule pour les traders de futures actifs.","toolLabel":"Comparer les frais des plateformes","body":"<h2>La différence</h2><p>Un ordre <strong>maker</strong> ajoute de la liquidité au carnet — un ordre limite qui se pose et attend d’être exécuté. Un ordre <strong>taker</strong> retire de la liquidité — un ordre au marché, ou un ordre limite qui s’exécute instantanément, qui prend une offre existante. Les plateformes facturent davantage les takers parce que les makers fournissent la liquidité contre laquelle tout le monde trade.</p>\n<h2>Taux typiques</h2><p>Sur les principaux perpétuels USDT, les frais maker tournent autour de 0,02 % et les frais taker de 0,04–0,06 %. Ça paraît minuscule, mais un day trader effectuant des dizaines d’allers-retours les paie encore et encore — et les takers les paient des deux côtés.</p>\n<h2>Comment payer moins</h2><p>Utilisez des <strong>ordres limites</strong> qui se posent pour bénéficier du frais maker quand vous le pouvez, détenez le token de la plateforme pour une réduction, et grimpez les paliers VIP à mesure que le volume augmente. Si les frais sont votre priorité, <a href=\"/lowest-fee-crypto-exchange/\">comparez d’abord les plateformes par frais taker</a>.</p>","faq":[["Pourquoi les takers paient-ils plus que les makers ?","Les takers retirent de la liquidité en exécutant des ordres existants, tandis que les makers ajoutent de la liquidité en posant des ordres dans le carnet. Les plateformes récompensent les makers par des frais plus bas parce qu’ils maintiennent le marché liquide."],["Comment payer les frais maker ?","Placez des ordres limites qui se posent dans le carnet plutôt que des ordres au marché qui s’exécutent instantanément. Si votre ordre attend d’être apparié, il est éligible au frais maker plus bas."]]},"how-to-avoid-liquidation":{"title":"Comment éviter la liquidation dans le trading crypto","desc":"Des moyens concrets d’empêcher une position à effet de levier d’être liquidée — du dimensionnement et des stops au mode de marge et au funding.","toolLabel":"Vérifiez votre prix de liquidation","body":"<h2>Connaissez le prix avant d’entrer</h2><p>Calculez d’abord votre <a href=\"/guides/what-is-liquidation-price/\">prix de liquidation</a> et assurez-vous qu’il se situe au-delà des mèches récentes et des supports et résistances évidents — et non juste à côté de votre entrée.</p>\n<h2>Utilisez moins de levier que vous ne le pouvez</h2><p>Ce n’est pas parce qu’une plateforme propose 125× que vous devriez l’utiliser. Un levier plus bas éloigne le prix de liquidation de l’entrée et vous achète de la marge pour avoir raison avec le temps.</p>\n<h2>Posez toujours un stop-loss</h2><p>Un stop vous ferme à un prix que <em>vous</em> choisissez, avant que le moteur de liquidation de la plateforme ne le fasse pour vous à un prix pire.</p>\n<h2>Dimensionnez par le risque</h2><p>Risquez 1–2 % fixe par trade en utilisant un <a href=\"/guides/how-to-calculate-position-size/\">calculateur de taille de position</a>, pour qu’aucun trade unique ne puisse faire de vrais dégâts.</p>\n<h2>Préférez la marge isolée</h2><p>La <a href=\"/guides/isolated-vs-cross-margin/\">marge isolée</a> plafonne la perte à une seule position. Ajoutez de la marge délibérément, pas dans la panique.</p>\n<h2>Attention au funding</h2><p>À fort levier, le <a href=\"/funding/\">funding</a> vide discrètement une position même quand le prix est plat — intégrez-le aux détentions longues.</p>","faq":[["Quelle est la meilleure façon d’éviter la liquidation ?","Utilisez moins de levier, posez toujours un stop-loss, dimensionnez par un pourcentage de risque fixe, et gardez votre prix de liquidation bien au-delà de la volatilité récente."],["Un stop-loss empêche-t-il la liquidation ?","Un stop-loss ferme votre position au prix que vous avez choisi avant que la liquidation de la plateforme ne se déclenche, donc en pratique il empêche la plupart des liquidations — à condition qu’il s’exécute sur des marchés rapides."]]},"perpetual-vs-futures":{"title":"Perpétuel vs futures : quelle est la différence ?","desc":"Les swaps perpétuels face aux futures à échéance : expiration, funding, et pourquoi les perps dominent le trading crypto à effet de levier.","toolLabel":"Scanner de funding en direct","body":"<h2>Les futures à échéance</h2><p>Un <strong>contrat à terme</strong> traditionnel a une date d’expiration. À cette date, il se règle au prix spot, donc le prix du contrat converge vers le spot à l’approche de l’échéance. Vous le tradez pour une durée fixe, puis il disparaît.</p>\n<h2>Les swaps perpétuels</h2><p>Un <strong>perpétuel</strong> (« perp ») n’expire jamais. Pour maintenir son prix ancré au spot sans échéance, les plateformes utilisent un <a href=\"/funding/\">paiement de funding</a> récurrent entre les longs et les shorts. Ce mécanisme remplace le règlement.</p>\n<h2>Pourquoi les perps dominent la crypto</h2><p>Les perps permettent aux traders de tenir un effet de levier indéfiniment sans rollover, ce qui explique qu’ils représentent la grande majorité du volume des dérivés crypto. Le compromis, c’est le funding : à fort levier, il peut discrètement vider une position même quand le prix est plat.</p>","faq":[["Les contrats perpétuels expirent-ils ?","Non. Les swaps perpétuels n’expirent jamais — un paiement de funding récurrent maintient leur prix lié au spot plutôt qu’à une date de règlement."],["Quelle est la différence entre futures et perpétuels ?","Les futures à échéance se règlent à une date d’expiration, tandis que les perpétuels tournent indéfiniment et utilisent des paiements de funding pour rester proches du spot. Le trading crypto est dominé par les perpétuels."]]},"long-vs-short-crypto":{"title":"Aller long vs short en crypto expliqué","desc":"Ce que signifie aller long ou short avec du levier, comment chaque côté gagne ou perd de l’argent, et comment la liquidation diffère.","toolLabel":"S’entraîner au long et au short","body":"<h2>Aller long</h2><p>Un <strong>long</strong> parie que le prix va monter. Vous profitez quand le prix monte et perdez quand il baisse. Un long est liquidé quand le prix chute suffisamment pour que votre marge ne puisse plus couvrir la perte.</p>\n<h2>Aller short</h2><p>Un <strong>short</strong> parie que le prix va baisser. Vous profitez quand le prix baisse et perdez quand il monte — le short vous permet de gagner de l’argent dans une tendance baissière. Un short est liquidé quand le prix monte suffisamment contre vous.</p>\n<h2>Le risque n’est pas symétrique</h2><p>Un long ne peut tomber qu’à zéro, mais un short a une perte théorique illimitée si le prix continue de monter — c’est pourquoi les short squeezes peuvent être violents. Dans tous les cas, le levier détermine à quelle distance de l’entrée se situe votre <a href=\"/guides/what-is-liquidation-price/\">prix de liquidation</a>. Testez les deux côtés sans risque sur <a href=\"/paper-trade\">Paper Trade</a>.</p>","faq":[["Que signifie aller short en crypto ?","Shorter, c’est parier que le prix va baisser : vous profitez quand il baisse et perdez quand il monte, ce qui vous permet de gagner de l’argent dans une tendance baissière."],["Shorter est-il plus risqué qu’aller long ?","Un short a une perte théorique illimitée si le prix continue de monter, tandis qu’un long ne peut tomber qu’à zéro — donc un short non couvert peut être plus risqué, et les short squeezes peuvent être brutaux."]]},"what-is-mark-price":{"title":"Qu’est-ce que le mark price en futures crypto ?","desc":"Pourquoi les plateformes liquident sur le mark price, pas le last price, et comment cela vous protège d’être sorti par une mèche sur un carnet d’ordres mince.","toolLabel":"Calculateur de liquidation","body":"<h2>Last price vs mark price</h2><p>Le <strong>last price</strong> est simplement la transaction la plus récente sur cette plateforme. Le <strong>mark price</strong> est une référence plus juste — généralement construite à partir d’un indice de plusieurs marchés spot plus une base de funding — qui lisse les pics propres à une seule plateforme.</p>\n<h2>Pourquoi ça compte</h2><p>Les plateformes calculent votre PnL latent et votre <a href=\"/guides/what-is-liquidation-price/\">liquidation</a> par rapport au <strong>mark price</strong>, pas au last price. Cela vous protège d’être liquidé par une brève mèche sur un carnet mince qui ne reflète pas le vrai marché.</p>\n<h2>Ce qu’il faut surveiller</h2><p>Sur des marchés rapides, le last price peut grimper bien au-delà du mark price. Votre position est jugée sur le mark, alors vérifiez-le — et non le last price qui clignote — quand vous êtes proche de votre niveau de liquidation.</p>","faq":[["Pourquoi les plateformes utilisent-elles le mark price pour la liquidation ?","Le mark price est une juste valeur basée sur un indice qui lisse les pics propres à une seule plateforme, de sorte qu’une brève mèche sur un carnet d’ordres mince ne puisse pas liquider à tort une position saine."],["Le mark price est-il identique au last price ?","Non. Le last price est la transaction la plus récente sur cette plateforme ; le mark price est une valeur plus juste basée sur un indice, utilisée pour calculer le PnL et les liquidations."]]}},"nl":{"how-to-read-funding-rates":{"title":"Hoe je crypto funding rates leest","desc":"Een begrijpelijke gids over funding rates van perpetuals: wat positieve en negatieve funding betekenen, hoe je drukke longs en shorts herkent, en hoe je funding-extremen gebruikt.","toolLabel":"Live funding-scanner","body":"<h2>Wat een funding rate is</h2><p>Op een perpetual future is er geen vervaldatum, dus gebruiken exchanges een kleine terugkerende betaling — de <strong>funding rate</strong> — om de perp-prijs aan de spotprijs gekoppeld te houden. Die wordt meestal elke 8 uur uitgewisseld tussen longs en shorts.</p>\n<h2>Positieve vs negatieve funding</h2><p><strong>Positieve funding</strong> betekent dat de perp boven spot handelt, dus <em>longs betalen shorts</em> — de markt leunt long. <strong>Negatieve funding</strong> betekent dat de perp onder spot handelt, dus <em>shorts betalen longs</em> — de markt leunt short.</p>\n<h2>Extremen lezen</h2><p>Wanneer funding sterk positief is, zijn longs druk en betalen ze een premie om hun positie aan te houden; een stilstand in de prijs kan een <strong>long squeeze</strong> uitlokken. Wanneer funding diep negatief is, zijn shorts druk en kan een opvering een <strong>short squeeze</strong> forceren. Funding is het sterkst als signaal samen met <a href=\"/open-interest/\">open interest</a> en <a href=\"/long-short/\">long/short-positionering</a>.</p>\n<h2>Let op de kosten</h2><p>Bij hoge leverage stapelen de fundingkosten zich snel op en kunnen ze stilletjes een positie leegtrekken, zelfs als de prijs vlak blijft. Reken die altijd mee in je aanhoudtijd.</p>","faq":[["Wat betekent een hoge funding rate?","Hoge positieve funding betekent dat de markt zwaar long zit en longs betalen om hun positie aan te houden — een teken van drukke longs die bij een terugval een short squeeze kunnen voeden."],["Is negatieve funding bullish?","Negatieve funding betekent dat shorts druk zijn en longs betalen. Het wordt vaak contrair gelezen als opzet voor een squeeze hogerop, maar het is één signaal tussen funding, open interest en prijs."]]},"how-to-read-liquidations":{"title":"Hoe je crypto-liquidaties leest","desc":"Begrijp crypto-liquidaties: wat ze zijn, het verschil tussen long- en short-liquidaties, en hoe liquidatiecascades volatiliteit aanjagen.","toolLabel":"Live liquidatie-tracker","body":"<h2>Wat een liquidatie is</h2><p>Een <strong>liquidatie</strong> is wanneer een exchange een hefboompositie gedwongen sluit omdat de margin van de trader het verlies niet langer kan dekken. De positie wordt tegen marktprijs gesloten en de trader verliest zijn margin. Bij hoge leverage ligt de liquidatieprijs heel dicht bij de instap.</p>\n<h2>Long- vs short-liquidaties</h2><p><strong>Long-liquidaties</strong> zijn over-leveraged kopers die worden weggevaagd wanneer de prijs daalt. <strong>Short-liquidaties</strong> zijn verkopers die worden weggevaagd wanneer de prijs stijgt. Een grote eenzijdige piek markeert vaak een lokaal extreem — een golf van long-liquidaties kan een bodem markeren, een golf van short-liquidaties kan een rally voeden.</p>\n<h2>Liquidatiecascades</h2><p>Liquidaties werken als brandstof. Wanneer de prijs een zone raakt die volgepakt is met leverage, duwen de gedwongen orders de prijs verder, wat meer liquidaties uitlokt — een <strong>cascade</strong>. Kijken waar de leverage het zwaarst ligt, helpt je de drukke trade te vermijden.</p>\n<h2>Gebruik het met de rest</h2><p>Combineer liquidaties met <a href=\"/funding/\">funding</a> en <a href=\"/open-interest/\">open interest</a>: een daling in open interest volgt meestal op een cascade naarmate leverage wordt weggespoeld.</p>","faq":[["Wat veroorzaakt een liquidatie?","Een positie wordt geliquideerd wanneer de prijs er ver genoeg tegenin beweegt dat de margin het verlies niet langer kan dekken, dus de exchange sluit hem automatisch."],["Zijn long- of short-liquidaties bullish?","Een piek van long-liquidaties (bij een daling) kan een lokale bodem markeren; een piek van short-liquidaties (bij een rally) kan een squeeze hogerop voeden."]]},"what-is-open-interest":{"title":"Wat is open interest in crypto?","desc":"Open interest uitgelegd: hoe het verschilt van volume, wat stijgende en dalende OI signaleren, en hoe je OI naast de prijs leest.","toolLabel":"Live open interest-tracker","body":"<h2>Open interest vs volume</h2><p><strong>Open interest (OI)</strong> is de totale waarde van alle openstaande perpetual-futuresposities op een coin. Anders dan volume — dat elke trade telt — meet OI hoeveel leverage er momenteel <em>open</em> staat in de markt.</p>\n<h2>Stijgende en dalende OI</h2><p>Stijgende OI betekent dat nieuwe posities en verse leverage binnenkomen. Dalende OI betekent dat traders posities sluiten. Een plotselinge daling in OI volgt meestal op een <a href=\"/liquidations/\">liquidatiecascade</a> naarmate over-leveraged posities worden weggespoeld.</p>\n<h2>OI lezen met de prijs</h2><p><strong>Prijs omhoog + OI omhoog</strong> = nieuw geld dat de beweging schraagt (sterkere trend). <strong>Prijs omhoog + OI omlaag</strong> = short covering in plaats van verse vraag. Zware OI-opbouw plus eenzijdige <a href=\"/funding/\">funding</a> wijst op een drukke, fragiele opzet.</p>","faq":[["Is hoge open interest bullish of bearish?","Op zichzelf geen van beide — het hangt af van de prijs. Stijgende OI met stijgende prijs suggereert nieuwe kopers; stijgende OI met dalende prijs suggereert nieuwe verkopers."],["Wat betekent dalende open interest?","Dalende OI betekent dat posities worden gesloten, vaak nadat een liquidatiecascade leverage uit de markt heeft gespoeld."]]},"long-short-ratio-explained":{"title":"Crypto long/short-ratio uitgelegd","desc":"Wat de long/short-ratio je vertelt over de positionering van traders, hoe je drukke extremen leest, en waarom je hem het best contrair gebruikt.","toolLabel":"Live long/short-ratio","body":"<h2>Wat het meet</h2><p>De <strong>long/short-ratio</strong> laat zien welk percentage van de traderaccounts long versus short gepositioneerd is op een coin. Het is een momentopname van crowd-positionering en sentiment.</p>\n<h2>De crowd lezen</h2><p>Ervaren traders lezen extremen vaak <strong>contrair</strong>. Wanneer de meeste accounts al long zitten, is het kopen grotendeels op en is de crowd blootgesteld aan een <strong>long squeeze</strong>. Wanneer de crowd zwaar short zit, kan een opvering een <strong>short squeeze</strong> forceren.</p>\n<h2>Eén signaal, niet het hele plaatje</h2><p>Een druk orderboek kan druk blijven terwijl een trend doorloopt. Combineer de ratio met <a href=\"/funding/\">funding</a> (wat de crowd betaalt om aan te houden) en <a href=\"/liquidations/\">liquidaties</a> (waar leverage wordt weggespoeld) voordat je handelt.</p>","faq":[["Wat is een goede long/short-ratio?","Er is geen enkele goede waarde — hij is het nuttigst bij extremen. Een heel hoog long-aandeel waarschuwt voor drukke longs; een heel hoog short-aandeel waarschuwt voor drukke shorts."],["Hoe gebruiken traders de long/short-ratio?","Velen lezen hem contrair: ze faden de over-gepositioneerde kant en bevestigen altijd met funding, open interest en price action."]]},"what-is-liquidation-price":{"title":"Wat is een liquidatieprijs in crypto?","desc":"Wat een liquidatieprijs is, hoe leverage hem dichter bij je instap brengt, en hoe je hem berekent voordat je een positie opent.","toolLabel":"Liquidatieprijs-calculator","body":"<h2>Wat het is</h2><p>Je <strong>liquidatieprijs</strong> is de prijs waarop een exchange je hefboompositie gedwongen sluit omdat je margin het verlies niet langer kan dekken. Steek je hem over, dan verlies je je margin. Hem kennen voordat je instapt is het allerbelangrijkste getal bij handelen met leverage.</p>\n<h2>Hoe leverage hem verplaatst</h2><p>Hoe hoger je leverage, hoe dichter de liquidatieprijs bij je instap ligt. Bij 5× wordt een long geliquideerd bij ruwweg een daling van 20%; bij 100× is het ruwweg een beweging van 1%. Daarom is hoge leverage zo fragiel — een gewone wick kan een positie wegvagen.</p>\n<h2>Hoe het berekend wordt</h2><p>Voor een isolated long geldt liquidatie ≈ instap × (1 − 1/leverage + maintenance-margin rate); shorts keren het teken om. Het exacte getal hangt af van de maintenance margin en fees van de exchange, dus bevestig het met een <a href=\"/btc-liquidation-calculator/\">liquidatiecalculator</a> voor jouw coin en leverage.</p>\n<h2>Geef het ruimte</h2><p>Stel je positiegrootte en leverage zo in dat de liquidatieprijs voorbij de ruis ligt — voorbij duidelijke support en resistance en recente wicks — niet bovenop je instap. Zie ook <a href=\"/guides/how-to-avoid-liquidation/\">hoe je liquidatie vermijdt</a>.</p>","faq":[["Hoe wordt de liquidatieprijs berekend?","Ruwweg: liquidatie ≈ instap × (1 − 1/leverage + maintenance margin) voor een long, met shorts omgekeerd. De precieze waarde hangt af van de maintenance-margin rate en fees van de exchange."],["Betekent hogere leverage een dichtere liquidatieprijs?","Ja. Bij 100× ligt de liquidatieprijs maar zo'n 1% van de instap, terwijl het bij 5× dichter bij 20% ligt — hogere leverage laat de prijs bijna geen ruimte om tegen je in te bewegen."]]},"isolated-vs-cross-margin":{"title":"Isolated vs cross margin uitgelegd","desc":"Het verschil tussen isolated en cross margin, de risico-afweging, en welke modus bij welk type trader past.","toolLabel":"Oefen met Paper Trade","body":"<h2>Isolated margin</h2><p>Bij <strong>isolated margin</strong> staat alleen de margin die je aan een positie toewijst op het spel. Als hij liquideert, is het verlies beperkt tot die margin en blijft de rest van je saldo onaangeroerd. Het is de veiligere standaard voor trades met hoge leverage.</p>\n<h2>Cross margin</h2><p>Bij <strong>cross margin</strong> dekt je hele accountsaldo de positie. Dat duwt de liquidatieprijs verder weg, maar één slechte trade kan het hele account leegtrekken, niet alleen de margin van één positie.</p>\n<h2>Welke te gebruiken</h2><p>De meeste traders gebruiken <strong>isolated</strong> voor opzetten met afgebakend risico en hoge leverage, en <strong>cross</strong> voor posities met lagere leverage die ze actief beheren of hedgen. De afweging: isolated begrenst je verlies; cross verlaagt het liquidatierisico maar verhoogt je maximale verlies. Hoe dan ook, controleer eerst de <a href=\"/guides/what-is-liquidation-price/\">liquidatieprijs</a>.</p>","faq":[["Is isolated of cross margin veiliger?","Isolated is veiliger om verliezen te begrenzen — alleen de toegewezen margin staat op het spel. Cross margin is moeilijker te liquideren, maar zet je hele saldo op het spel."],["Wanneer moet ik cross margin gebruiken?","Cross past bij posities met lagere leverage die je actief beheert of hedgt, waar je wilt dat de trade volatiliteit overleeft zonder margin bij te storten."]]},"how-to-calculate-position-size":{"title":"Hoe je positiegrootte berekent in crypto","desc":"Bepaal elke trade op basis van risico, niet op gevoel: hoe je positiegrootte berekent uit je account, stopafstand en risico per trade.","toolLabel":"Positiegrootte-calculator","body":"<h2>Risico eerst, grootte daarna</h2><p>Professionele sizing begint bij één getal: hoeveel je bereid bent te verliezen op de trade. Een gangbare regel is om <strong>1–2% van je account per trade</strong> te riskeren. Je positiegrootte volgt dan uit je stopafstand.</p>\n<h2>De formule</h2><p>Positiegrootte = (account × risico %) ÷ (stopafstand %). Als je $20 riskeert en je stop 2% verwijderd is, neem je $1,000 aan exposure — ongeacht leverage. Leverage bepaalt alleen de vereiste margin, niet je risico.</p>\n<h2>Leverage is geen risico</h2><p>Dit is het punt dat de meeste beginners missen: je risico wordt bepaald door grootte en stop, niet door leverage. 10× op een kleine, goed-gestopte positie kan veel veiliger zijn dan 2× op een te grote. Gebruik een <a href=\"/calculators?c=size\">positiegrootte-calculator</a> zodat elke trade hetzelfde bedrag riskeert, en houd je <a href=\"/guides/what-is-liquidation-price/\">liquidatieprijs</a> in de gaten.</p>","faq":[["Hoeveel moet ik per trade riskeren?","Een veelgebruikte richtlijn is 1–2% van je account per trade, zodat een reeks verliezen het account niet kan opblazen."],["Verandert leverage mijn positiegrootte?","Nee — je risico wordt bepaald door positiegrootte en stopafstand. Leverage bepaalt alleen de margin die nodig is om die positie aan te houden."]]},"what-is-leverage-in-crypto":{"title":"Wat is leverage in crypto-trading?","desc":"Leverage eenvoudig uitgelegd: hoe 10× of 100× werkt, wat het met je liquidatieprijs doet, en hoe je het gebruikt zonder op te blazen.","toolLabel":"Liquidatiecalculator","body":"<h2>Wat leverage doet</h2><p><strong>Leverage</strong> laat je een positie beheren die groter is dan je margin. Bij 10× beheert $100 margin $1,000 aan exposure, dus een beweging van 1% wordt een schommeling van 10% op je margin — winsten én verliezen worden beide uitvergroot.</p>\n<h2>De keerzijde: liquidatie</h2><p>De keerzijde is je <a href=\"/guides/what-is-liquidation-price/\">liquidatieprijs</a>. Hoe hoger de leverage, hoe kleiner de beweging die je wegvaagt — ruwweg 1% bij 100×, 2% bij 50×, 10% bij 10×. Uitvergrote opwaartse kansen komen met uitvergrote fragiliteit.</p>\n<h2>Het verstandig gebruiken</h2><p>Leverage is een tool voor kapitaalefficiëntie, geen getal om te maximaliseren. Bepaal je grootte op <a href=\"/guides/how-to-calculate-position-size/\">risico</a>, houd de liquidatieprijs voorbij de ruis, en onthoud dat fundingkosten meeschalen met positiegrootte, niet met margin.</p>","faq":[["Wat betekent 10x leverage?","10× betekent dat je positie tien keer je margin is: $100 beheert $1,000, dus een prijsbeweging van 1% staat gelijk aan een beweging van 10% op je margin — in beide richtingen."],["Is hoge leverage slecht?","Hoge leverage is niet inherent slecht, maar het zet je liquidatieprijs heel dicht bij de instap. De meeste blow-ups komen door te grote posities bij hoge leverage, niet door leverage zelf."]]},"maker-vs-taker-fees":{"title":"Maker- vs taker-fees uitgelegd","desc":"Wat maker- en taker-fees zijn, waarom takers meer betalen, en hoe het verschil oploopt voor actieve futures-traders.","toolLabel":"Vergelijk exchange-fees","body":"<h2>Het verschil</h2><p>Een <strong>maker</strong>-order voegt liquiditeit toe aan het orderboek — een limietorder die blijft staan en wacht op uitvoering. Een <strong>taker</strong>-order haalt liquiditeit weg — een marktorder, of een limietorder die direct vult, die een bestaand bod oppakt. Exchanges rekenen takers meer omdat makers de liquiditeit leveren waartegen iedereen handelt.</p>\n<h2>Typische tarieven</h2><p>Op grote USDT-perpetuals liggen maker-fees rond 0.02% en taker-fees 0.04–0.06%. Het klinkt minuscuul, maar een daytrader die tientallen round trips doet betaalt het keer op keer — en takers betalen het aan beide kanten.</p>\n<h2>Hoe je minder betaalt</h2><p>Gebruik blijvende <strong>limietorders</strong> om waar mogelijk in aanmerking te komen voor de maker-fee, houd de exchange-token aan voor een korting, en klim de VIP-tiers op naarmate je volume groeit. Als fees je prioriteit zijn, <a href=\"/lowest-fee-crypto-exchange/\">vergelijk exchanges eerst op taker-fee</a>.</p>","faq":[["Waarom betalen takers meer dan makers?","Takers halen liquiditeit weg door bestaande orders te vullen, terwijl makers liquiditeit toevoegen door orders op het boek te laten staan. Exchanges belonen makers met lagere fees omdat ze de markt liquide houden."],["Hoe betaal ik maker-fees?","Plaats limietorders die op het boek blijven staan in plaats van marktorders die direct vullen. Als je order wacht om gematcht te worden, komt hij in aanmerking voor de lagere maker-fee."]]},"how-to-avoid-liquidation":{"title":"Hoe je liquidatie vermijdt in crypto-trading","desc":"Praktische manieren om te voorkomen dat een hefboompositie geliquideerd wordt — van sizing en stops tot marginmodus en funding.","toolLabel":"Controleer je liquidatieprijs","body":"<h2>Ken de prijs voordat je instapt</h2><p>Bereken eerst je <a href=\"/guides/what-is-liquidation-price/\">liquidatieprijs</a> en zorg dat hij voorbij recente wicks en duidelijke support en resistance ligt — niet vlak naast je instap.</p>\n<h2>Gebruik minder leverage dan je kunt</h2><p>Alleen omdat een platform 125× aanbiedt, betekent niet dat je het moet gebruiken. Lagere leverage duwt de liquidatieprijs verder van de instap en koopt je ruimte om mettertijd gelijk te krijgen.</p>\n<h2>Zet altijd een stop-loss</h2><p>Een stop sluit je op een prijs die <em>jij</em> kiest, voordat de liquidatie-engine van de exchange het voor je doet op een slechtere.</p>\n<h2>Bepaal je grootte op risico</h2><p>Riskeer een vaste 1–2% per trade met een <a href=\"/guides/how-to-calculate-position-size/\">positiegrootte-calculator</a>, zodat geen enkele trade echte schade kan aanrichten.</p>\n<h2>Verkies isolated margin</h2><p><a href=\"/guides/isolated-vs-cross-margin/\">Isolated margin</a> begrenst het verlies tot één positie. Voeg margin bewust toe, niet in paniek.</p>\n<h2>Let op funding</h2><p>Bij hoge leverage trekt <a href=\"/funding/\">funding</a> stilletjes een positie leeg, zelfs als de prijs vlak blijft — reken het mee bij lange aanhoudtijden.</p>","faq":[["Wat is de beste manier om liquidatie te vermijden?","Gebruik lagere leverage, zet altijd een stop-loss, bepaal je grootte op een vast risicopercentage, en houd je liquidatieprijs ruim voorbij recente volatiliteit."],["Voorkomt een stop-loss liquidatie?","Een stop-loss sluit je positie op je gekozen prijs voordat de liquidatie van de exchange zou afgaan, dus in de praktijk voorkomt het de meeste liquidaties — mits hij vult in snelle markten."]]},"perpetual-vs-futures":{"title":"Perpetual vs futures: wat is het verschil?","desc":"Perpetual swaps versus futures met vervaldatum: expiratie, funding, en waarom perps de crypto-leverage-handel domineren.","toolLabel":"Live funding-scanner","body":"<h2>Futures met vervaldatum</h2><p>Een traditioneel <strong>futurescontract</strong> heeft een vervaldatum. Op die datum settelt het naar de spotprijs, dus de contractprijs convergeert naar spot naarmate de expiratie nadert. Je handelt het voor een vaste termijn, daarna is het weg.</p>\n<h2>Perpetual swaps</h2><p>Een <strong>perpetual</strong> (\"perp\") vervalt nooit. Om de prijs zonder vervaldatum aan spot gekoppeld te houden, gebruiken exchanges een terugkerende <a href=\"/funding/\">fundingbetaling</a> tussen longs en shorts. Dat mechanisme vervangt de settlement.</p>\n<h2>Waarom perps crypto domineren</h2><p>Perps laten traders leverage onbeperkt aanhouden zonder rollover, en daarom vormen ze het overgrote deel van het crypto-derivatenvolume. De afweging is funding: bij hoge leverage kan het stilletjes een positie leegtrekken, zelfs als de prijs vlak blijft.</p>","faq":[["Verlopen perpetual-contracten?","Nee. Perpetual swaps verlopen nooit — een terugkerende fundingbetaling houdt hun prijs aan spot gekoppeld in plaats van aan een settlementdatum."],["Wat is het verschil tussen futures en perpetuals?","Futures met vervaldatum settelen op een expiratiedatum, terwijl perpetuals onbeperkt doorlopen en fundingbetalingen gebruiken om dicht bij spot te blijven. Crypto-trading wordt gedomineerd door perpetuals."]]},"long-vs-short-crypto":{"title":"Long vs short gaan in crypto uitgelegd","desc":"Wat het betekent om long of short te gaan met leverage, hoe elke kant geld maakt of verliest, en hoe liquidatie verschilt.","toolLabel":"Oefen long & short","body":"<h2>Long gaan</h2><p>Een <strong>long</strong> wedt dat de prijs zal stijgen. Je maakt winst als de prijs stijgt en verliest als hij daalt. Een long wordt geliquideerd wanneer de prijs ver genoeg daalt dat je margin het verlies niet langer kan dekken.</p>\n<h2>Short gaan</h2><p>Een <strong>short</strong> wedt dat de prijs zal dalen. Je maakt winst als de prijs daalt en verliest als hij stijgt — shorten laat je geld verdienen in een neerwaartse trend. Een short wordt geliquideerd wanneer de prijs ver genoeg tegen je in stijgt.</p>\n<h2>Het risico is niet symmetrisch</h2><p>Een long kan alleen naar nul vallen, maar een short heeft theoretisch onbeperkt verlies als de prijs blijft stijgen — daarom kunnen short squeezes hevig zijn. Hoe dan ook bepaalt leverage hoe dicht je <a href=\"/guides/what-is-liquidation-price/\">liquidatieprijs</a> bij de instap ligt. Test beide kanten risicovrij op <a href=\"/paper-trade\">Paper Trade</a>.</p>","faq":[["Wat betekent short gaan in crypto?","Shorten betekent wedden dat de prijs zal dalen: je maakt winst als hij daalt en verliest als hij stijgt, wat je geld laat verdienen in een neerwaartse trend."],["Is shorten riskanter dan long gaan?","Een short heeft theoretisch onbeperkt verlies als de prijs blijft stijgen, terwijl een long alleen naar nul kan vallen — dus een ongehedgde short kan riskanter zijn, en short squeezes kunnen scherp zijn."]]},"what-is-mark-price":{"title":"Wat is mark price in crypto-futures?","desc":"Waarom exchanges liquideren op mark price, niet op last price, en hoe het je beschermt tegen weggewickt worden door een dun orderboek.","toolLabel":"Liquidatiecalculator","body":"<h2>Last price vs mark price</h2><p>De <strong>last price</strong> is simpelweg de meest recente trade op die exchange. De <strong>mark price</strong> is een eerlijkere referentie — meestal opgebouwd uit een index van meerdere spotmarkten plus een fundingbasis — die pieken op één exchange afvlakt.</p>\n<h2>Waarom het ertoe doet</h2><p>Exchanges berekenen je ongerealiseerde PnL en je <a href=\"/guides/what-is-liquidation-price/\">liquidatie</a> tegen de <strong>mark price</strong>, niet de last price. Dit beschermt je tegen geliquideerd worden door een korte wick op een dun orderboek die de echte markt niet weerspiegelt.</p>\n<h2>Waar je op moet letten</h2><p>In snelle markten kan de last price ver voorbij de mark price pieken. Je positie wordt beoordeeld op de mark, dus controleer die — niet de knipperende last price — wanneer je in de buurt van je liquidatieniveau zit.</p>","faq":[["Waarom gebruiken exchanges mark price voor liquidatie?","Mark price is een index-gebaseerde reële waarde die pieken op één exchange afvlakt, zodat een korte wick op een dun orderboek een gezonde positie niet ten onrechte kan liquideren."],["Is mark price hetzelfde als last price?","Nee. Last price is de meest recente trade op die exchange; mark price is een eerlijkere, index-gebaseerde waarde die gebruikt wordt om PnL en liquidaties te berekenen."]]}},"ru":{"how-to-read-funding-rates":{"title":"Как читать ставки финансирования в крипте","desc":"Понятное объяснение ставок финансирования по перпам: что означает положительное и отрицательное финансирование, как заметить перегретые лонги и шорты и как использовать экстремумы финансирования.","toolLabel":"Живой сканер финансирования","body":"<h2>Что такое ставка финансирования</h2><p>У бессрочного фьючерса нет даты экспирации, поэтому биржи используют небольшой регулярный платёж — <strong>ставку финансирования</strong> — чтобы удерживать цену перпа привязанной к споту. Обычно она выплачивается каждые 8 часов между лонгами и шортами.</p>\n<h2>Положительное и отрицательное финансирование</h2><p><strong>Положительное финансирование</strong> означает, что перп торгуется выше спота, поэтому <em>лонги платят шортам</em> — рынок склоняется в лонг. <strong>Отрицательное финансирование</strong> означает, что перп торгуется ниже спота, поэтому <em>шорты платят лонгам</em> — рынок склоняется в шорт.</p>\n<h2>Чтение экстремумов</h2><p>Когда финансирование сильно положительное, лонгов слишком много и они платят премию за удержание; остановка цены может спровоцировать <strong>лонг-сквиз</strong>. Когда финансирование глубоко отрицательное, шортов слишком много, и отскок может вызвать <strong>шорт-сквиз</strong>. Финансирование сильнее всего как сигнал в связке с <a href=\"/open-interest/\">открытым интересом</a> и <a href=\"/long-short/\">соотношением лонг/шорт</a>.</p>\n<h2>Следите за стоимостью</h2><p>На высоком плече стоимость финансирования быстро накапливается и может незаметно истощать позицию, даже когда цена стоит на месте. Всегда учитывайте её при расчёте времени удержания.</p>","faq":[["Что означает высокая ставка финансирования?","Высокое положительное финансирование означает, что рынок сильно в лонге и лонги платят за удержание — признак перегретых лонгов, который может подпитать шорт-сквиз на откате."],["Является ли отрицательное финансирование бычьим сигналом?","Отрицательное финансирование означает, что шортов слишком много и они платят лонгам. Его часто читают контртрендово как заготовку под сквиз вверх, но это лишь один сигнал среди финансирования, открытого интереса и цены."]]},"how-to-read-liquidations":{"title":"Как читать ликвидации в крипте","desc":"Разберитесь в крипто-ликвидациях: что это такое, чем отличаются ликвидации лонгов и шортов и как каскады ликвидаций раскручивают волатильность.","toolLabel":"Живой трекер ликвидаций","body":"<h2>Что такое ликвидация</h2><p><strong>Ликвидация</strong> — это когда биржа принудительно закрывает позицию с плечом, потому что маржа трейдера больше не покрывает убыток. Позиция закрывается по рынку, и трейдер теряет свою маржу. На высоком плече цена ликвидации находится очень близко к входу.</p>\n<h2>Ликвидации лонгов и шортов</h2><p><strong>Ликвидации лонгов</strong> — это перегруженные плечом покупатели, выбитые при падении цены. <strong>Ликвидации шортов</strong> — это продавцы, выбитые при росте цены. Крупный односторонний всплеск часто отмечает локальный экстремум — волна ликвидаций лонгов может отметить дно, а волна ликвидаций шортов может подпитать ралли.</p>\n<h2>Каскады ликвидаций</h2><p>Ликвидации работают как топливо. Когда цена доходит до зоны, набитой плечом, принудительные ордера толкают цену дальше, провоцируя новые ликвидации — <strong>каскад</strong>. Отслеживание того, где плечо тяжелее всего, помогает избегать перегретой сделки.</p>\n<h2>Используйте вместе с остальным</h2><p>Сочетайте ликвидации с <a href=\"/funding/\">финансированием</a> и <a href=\"/open-interest/\">открытым интересом</a>: падение открытого интереса обычно следует за каскадом, по мере того как плечо вымывается.</p>","faq":[["Что вызывает ликвидацию?","Позиция ликвидируется, когда цена идёт против неё настолько далеко, что маржа больше не покрывает убыток, и биржа закрывает её автоматически."],["Ликвидации лонгов или шортов бычьи?","Всплеск ликвидаций лонгов (на падении) может отметить локальное дно; всплеск ликвидаций шортов (на ралли) может подпитать сквиз вверх."]]},"what-is-open-interest":{"title":"Что такое открытый интерес в крипте?","desc":"Объяснение открытого интереса: чем он отличается от объёма, что сигнализирует рост и падение OI и как читать OI вместе с ценой.","toolLabel":"Живой трекер открытого интереса","body":"<h2>Открытый интерес против объёма</h2><p><strong>Открытый интерес (OI)</strong> — это суммарная стоимость всех открытых позиций по бессрочным фьючерсам на монету. В отличие от объёма — который считает каждую сделку — OI измеряет, сколько плеча сейчас <em>открыто</em> на рынке.</p>\n<h2>Рост и падение OI</h2><p>Растущий OI означает, что в рынок входят новые позиции и свежее плечо. Падающий OI означает, что трейдеры закрываются. Резкое падение OI обычно следует за <a href=\"/liquidations/\">каскадом ликвидаций</a>, когда перегруженные плечом позиции вымываются.</p>\n<h2>Чтение OI с ценой</h2><p><strong>Цена вверх + OI вверх</strong> = новые деньги поддерживают движение (тренд сильнее). <strong>Цена вверх + OI вниз</strong> = закрытие шортов, а не свежий спрос. Сильное наращивание OI вместе с односторонним <a href=\"/funding/\">финансированием</a> сигнализирует о перегретой, хрупкой расстановке.</p>","faq":[["Высокий открытый интерес — это бычий или медвежий сигнал?","Сам по себе ни тот, ни другой — зависит от цены. Растущий OI с растущей ценой указывает на новых покупателей; растущий OI с падающей ценой указывает на новых продавцов."],["Что означает падающий открытый интерес?","Падающий OI означает, что позиции закрываются, часто после того как каскад ликвидаций вымывает плечо с рынка."]]},"long-short-ratio-explained":{"title":"Соотношение лонг/шорт в крипте — объяснение","desc":"Что соотношение лонг/шорт говорит о расстановке трейдеров, как читать перегретые экстремумы и почему его лучше использовать контртрендово.","toolLabel":"Живое соотношение лонг/шорт","body":"<h2>Что оно измеряет</h2><p><strong>Соотношение лонг/шорт</strong> показывает, какой процент аккаунтов трейдеров стоит в лонг против шорт по монете. Это срез расстановки и настроений толпы.</p>\n<h2>Чтение толпы</h2><p>Опытные трейдеры часто читают экстремумы <strong>контртрендово</strong>. Когда большинство аккаунтов уже в лонге, покупательная сила в основном исчерпана и толпа уязвима к <strong>лонг-сквизу</strong>. Когда толпа сильно в шорте, отскок может вызвать <strong>шорт-сквиз</strong>.</p>\n<h2>Один сигнал, а не вся картина</h2><p>Перегретая книга может оставаться перегретой, пока тренд идёт. Сочетайте соотношение с <a href=\"/funding/\">финансированием</a> (что толпа платит за удержание) и <a href=\"/liquidations/\">ликвидациями</a> (где вымывается плечо), прежде чем действовать.</p>","faq":[["Какое соотношение лонг/шорт хорошее?","Единого хорошего значения нет — оно полезнее всего на экстремумах. Очень высокая доля лонгов предупреждает о перегретых лонгах; очень высокая доля шортов предупреждает о перегретых шортах."],["Как трейдеры используют соотношение лонг/шорт?","Многие читают его контртрендово: отыгрывают перегруженную сторону и всегда подтверждают финансированием, открытым интересом и ценовым движением."]]},"what-is-liquidation-price":{"title":"Что такое цена ликвидации в крипте?","desc":"Что такое цена ликвидации, как плечо приближает её к вашему входу и как рассчитать её до открытия позиции.","toolLabel":"Калькулятор цены ликвидации","body":"<h2>Что это такое</h2><p>Ваша <strong>цена ликвидации</strong> — это цена, при которой биржа принудительно закрывает вашу позицию с плечом, потому что маржа больше не покрывает убыток. Пересеките её — и вы теряете маржу. Знать её до входа — самое важное число в торговле с плечом.</p>\n<h2>Как плечо её двигает</h2><p>Чем выше плечо, тем ближе цена ликвидации к вашему входу. На 5× лонг ликвидируется примерно при падении на 20%; на 100× — это примерно движение на 1%. Вот почему высокое плечо такое хрупкое — обычный фитиль может уничтожить позицию.</p>\n<h2>Как она рассчитывается</h2><p>Для изолированного лонга ликвидация ≈ вход × (1 − 1/плечо + ставка поддерживающей маржи); для шортов знак меняется. Точная цифра зависит от поддерживающей маржи и комиссий биржи, поэтому подтвердите её <a href=\"/btc-liquidation-calculator/\">калькулятором ликвидации</a> для вашей монеты и плеча.</p>\n<h2>Дайте ей запас</h2><p>Подбирайте размер и плечо так, чтобы цена ликвидации находилась за пределами шума — за очевидными поддержкой и сопротивлением и недавними фитилями — а не вплотную к вашему входу. См. также <a href=\"/guides/how-to-avoid-liquidation/\">как избежать ликвидации</a>.</p>","faq":[["Как рассчитывается цена ликвидации?","Грубо, ликвидация ≈ вход × (1 − 1/плечо + поддерживающая маржа) для лонга, для шортов наоборот. Точное значение зависит от ставки поддерживающей маржи и комиссий биржи."],["Означает ли более высокое плечо более близкую цену ликвидации?","Да. На 100× цена ликвидации всего примерно в 1% от входа, тогда как на 5× она ближе к 20% — более высокое плечо почти не оставляет цене места двигаться против вас."]]},"isolated-vs-cross-margin":{"title":"Изолированная и кросс-маржа — объяснение","desc":"Разница между изолированной и кросс-маржой, компромисс по риску и какой режим какому стилю трейдера подходит.","toolLabel":"Тренируйтесь на Paper Trade","body":"<h2>Изолированная маржа</h2><p>В режиме <strong>изолированной маржи</strong> рискует только та маржа, которую вы назначили позиции. Если она ликвидируется, убыток ограничен этой маржой, а остальной баланс остаётся нетронутым. Это более безопасный вариант по умолчанию для сделок с высоким плечом.</p>\n<h2>Кросс-маржа</h2><p>В режиме <strong>кросс-маржи</strong> позицию обеспечивает весь баланс вашего аккаунта. Это отодвигает цену ликвидации дальше, но одна неудачная сделка может опустошить весь аккаунт, а не только маржу одной позиции.</p>\n<h2>Что выбрать</h2><p>Большинство трейдеров используют <strong>изолированную</strong> для сделок с определённым риском и высоким плечом, а <strong>кросс</strong> — для позиций с меньшим плечом, которыми они активно управляют или хеджируют. Компромисс: изолированная ограничивает убыток; кросс снижает риск ликвидации, но повышает максимальный убыток. В любом случае сначала проверьте <a href=\"/guides/what-is-liquidation-price/\">цену ликвидации</a>.</p>","faq":[["Что безопаснее — изолированная или кросс-маржа?","Изолированная безопаснее для ограничения убытков — рискует только назначенная маржа. Кросс-маржу сложнее ликвидировать, но она ставит на кон весь ваш баланс."],["Когда стоит использовать кросс-маржу?","Кросс подходит для позиций с меньшим плечом, которыми вы активно управляете или хеджируете, когда хотите, чтобы сделка пережила волатильность без доливки маржи."]]},"how-to-calculate-position-size":{"title":"Как рассчитать размер позиции в крипте","desc":"Подбирайте размер каждой сделки по риску, а не по наитию: как вычислить размер позиции из вашего аккаунта, расстояния до стопа и риска на сделку.","toolLabel":"Калькулятор размера позиции","body":"<h2>Сначала риск, потом размер</h2><p>Профессиональный расчёт размера начинается с одного числа: сколько вы готовы потерять на сделке. Распространённое правило — рисковать <strong>1–2% аккаунта на сделку</strong>. Размер позиции тогда следует из расстояния до вашего стопа.</p>\n<h2>Формула</h2><p>Размер позиции = (аккаунт × риск %) ÷ (расстояние до стопа %). Если вы рискуете $20, а ваш стоп в 2% от входа, вы берёте $1,000 экспозиции — независимо от плеча. Плечо лишь задаёт необходимую маржу, а не ваш риск.</p>\n<h2>Плечо — это не риск</h2><p>Вот что упускает большинство новичков: ваш риск задаётся размером и стопом, а не плечом. 10× на небольшой позиции с грамотным стопом может быть гораздо безопаснее, чем 2× на завышенной. Используйте <a href=\"/calculators?c=size\">калькулятор размера позиции</a>, чтобы каждая сделка рисковала одинаковой суммой, и держите в поле зрения вашу <a href=\"/guides/what-is-liquidation-price/\">цену ликвидации</a>.</p>","faq":[["Сколько мне рисковать на сделку?","Широко используемая рекомендация — 1–2% аккаунта на сделку, чтобы серия убытков не могла обнулить аккаунт."],["Меняет ли плечо размер моей позиции?","Нет — ваш риск задаётся размером позиции и расстоянием до стопа. Плечо лишь определяет маржу, необходимую для удержания этой позиции."]]},"what-is-leverage-in-crypto":{"title":"Что такое плечо в крипто-торговле?","desc":"Плечо простыми словами: как работает 10× или 100×, что оно делает с вашей ценой ликвидации и как использовать его, не сливая депозит.","toolLabel":"Калькулятор ликвидации","body":"<h2>Что делает плечо</h2><p><strong>Плечо</strong> позволяет управлять позицией крупнее вашей маржи. На 10× маржа в $100 управляет экспозицией в $1,000, поэтому движение на 1% превращается в колебание 10% на вашей марже — и прибыль, и убытки усиливаются.</p>\n<h2>Подвох: ликвидация</h2><p>Обратная сторона — ваша <a href=\"/guides/what-is-liquidation-price/\">цена ликвидации</a>. Чем выше плечо, тем меньше движение, которое вас выбивает — примерно 1% на 100×, 2% на 50×, 10% на 10×. Усиленный потенциал прибыли идёт в комплекте с усиленной хрупкостью.</p>\n<h2>Разумное использование</h2><p>Плечо — это инструмент эффективности капитала, а не число, которое нужно выкручивать на максимум. Подбирайте размер по <a href=\"/guides/how-to-calculate-position-size/\">риску</a>, держите цену ликвидации за пределами шума и помните, что стоимость финансирования масштабируется с размером позиции, а не с маржой.</p>","faq":[["Что означает плечо 10x?","10× означает, что ваша позиция в десять раз больше маржи: $100 управляют $1,000, поэтому движение цены на 1% равно движению на 10% на вашей марже — в обе стороны."],["Высокое плечо — это плохо?","Высокое плечо не плохо само по себе, но оно ставит вашу цену ликвидации очень близко к входу. Большинство сливов происходит из-за завышения размера на высоком плече, а не из-за самого плеча."]]},"maker-vs-taker-fees":{"title":"Комиссии мейкера и тейкера — объяснение","desc":"Что такое комиссии мейкера и тейкера, почему тейкеры платят больше и как разница накапливается для активных трейдеров фьючерсов.","toolLabel":"Сравнить комиссии бирж","body":"<h2>Разница</h2><p>Ордер <strong>мейкера</strong> добавляет ликвидность в книгу — лимитный ордер, который стоит и ждёт исполнения. Ордер <strong>тейкера</strong> убирает ликвидность — рыночный ордер или лимитный, исполняющийся мгновенно, который забирает существующее предложение. Биржи берут с тейкеров больше, потому что мейкеры предоставляют ликвидность, против которой все торгуют.</p>\n<h2>Типичные ставки</h2><p>На основных USDT-перпах комиссии мейкера около 0.02%, а тейкера 0.04–0.06%. Звучит мелко, но дей-трейдер, делающий десятки круговых сделок, платит её снова и снова — а тейкеры платят её с обеих сторон.</p>\n<h2>Как платить меньше</h2><p>Используйте отстаивающиеся <strong>лимитные ордера</strong>, чтобы где можно претендовать на комиссию мейкера, держите токен биржи для скидки и поднимайтесь по VIP-уровням по мере роста объёма. Если комиссии для вас в приоритете, сначала <a href=\"/lowest-fee-crypto-exchange/\">сравните биржи по комиссии тейкера</a>.</p>","faq":[["Почему тейкеры платят больше мейкеров?","Тейкеры убирают ликвидность, исполняя существующие ордера, а мейкеры добавляют ликвидность, оставляя ордера в книге. Биржи вознаграждают мейкеров более низкими комиссиями, потому что они поддерживают рынок ликвидным."],["Как мне платить комиссии мейкера?","Размещайте лимитные ордера, которые стоят в книге, вместо рыночных, исполняющихся мгновенно. Если ваш ордер ждёт исполнения, он претендует на более низкую комиссию мейкера."]]},"how-to-avoid-liquidation":{"title":"Как избежать ликвидации в крипто-торговле","desc":"Практические способы уберечь позицию с плечом от ликвидации — от размера и стопов до режима маржи и финансирования.","toolLabel":"Проверьте свою цену ликвидации","body":"<h2>Знайте цену до входа</h2><p>Сначала рассчитайте свою <a href=\"/guides/what-is-liquidation-price/\">цену ликвидации</a> и убедитесь, что она находится за пределами недавних фитилей и очевидных поддержки и сопротивления — а не вплотную к вашему входу.</p>\n<h2>Используйте плечо меньше доступного</h2><p>То, что площадка предлагает 125×, не значит, что вам стоит его использовать. Меньшее плечо отодвигает цену ликвидации дальше от входа и даёт вам запас, чтобы оказаться правым со временем.</p>\n<h2>Всегда ставьте стоп-лосс</h2><p>Стоп закрывает вас по цене, которую выбираете <em>вы</em>, прежде чем это сделает движок ликвидации биржи по худшей.</p>\n<h2>Подбирайте размер по риску</h2><p>Рискуйте фиксированными 1–2% на сделку, используя <a href=\"/guides/how-to-calculate-position-size/\">калькулятор размера позиции</a>, чтобы ни одна сделка не могла нанести реальный урон.</p>\n<h2>Предпочитайте изолированную маржу</h2><p><a href=\"/guides/isolated-vs-cross-margin/\">Изолированная маржа</a> ограничивает убыток одной позицией. Доливайте маржу осознанно, а не в панике.</p>\n<h2>Помните про финансирование</h2><p>На высоком плече <a href=\"/funding/\">финансирование</a> незаметно истощает позицию, даже когда цена стоит на месте — учитывайте его при долгом удержании.</p>","faq":[["Какой лучший способ избежать ликвидации?","Используйте меньшее плечо, всегда ставьте стоп-лосс, подбирайте размер по фиксированному проценту риска и держите цену ликвидации заметно за пределами недавней волатильности."],["Предотвращает ли стоп-лосс ликвидацию?","Стоп-лосс закрывает вашу позицию по выбранной вами цене до того, как сработает ликвидация биржи, поэтому на практике он предотвращает большинство ликвидаций — при условии, что исполняется на быстрых рынках."]]},"perpetual-vs-futures":{"title":"Перп против фьючерса: в чём разница?","desc":"Бессрочные свопы против срочных фьючерсов: экспирация, финансирование и почему перпы доминируют в торговле криптой с плечом.","toolLabel":"Живой сканер финансирования","body":"<h2>Срочные фьючерсы</h2><p>У традиционного <strong>фьючерсного контракта</strong> есть дата экспирации. В эту дату он рассчитывается по цене спота, поэтому цена контракта сходится к споту по мере приближения экспирации. Вы торгуете им фиксированный срок, а затем он исчезает.</p>\n<h2>Бессрочные свопы</h2><p><strong>Перп</strong> (бессрочный своп) никогда не экспирируется. Чтобы удерживать его цену привязанной к споту без экспирации, биржи используют регулярный <a href=\"/funding/\">платёж финансирования</a> между лонгами и шортами. Этот механизм заменяет расчёт по экспирации.</p>\n<h2>Почему перпы доминируют в крипте</h2><p>Перпы позволяют трейдерам держать плечо бесконечно без роллирования, поэтому они составляют подавляющее большинство объёма крипто-деривативов. Компромисс — финансирование: на высоком плече оно может незаметно истощать позицию, даже когда цена стоит на месте.</p>","faq":[["Экспирируются ли бессрочные контракты?","Нет. Бессрочные свопы никогда не экспирируются — регулярный платёж финансирования удерживает их цену привязанной к споту вместо даты расчёта."],["В чём разница между фьючерсами и перпами?","Срочные фьючерсы рассчитываются в дату экспирации, тогда как перпы работают бессрочно и используют платежи финансирования, чтобы оставаться около спота. В крипто-торговле доминируют перпы."]]},"long-vs-short-crypto":{"title":"Лонг против шорта в крипте — объяснение","desc":"Что значит идти в лонг или шорт с плечом, как каждая сторона зарабатывает или теряет деньги и чем отличается ликвидация.","toolLabel":"Тренируйте лонг и шорт","body":"<h2>Идём в лонг</h2><p><strong>Лонг</strong> ставит на то, что цена вырастет. Вы зарабатываете при росте цены и теряете при падении. Лонг ликвидируется, когда цена падает достаточно далеко, чтобы ваша маржа больше не покрывала убыток.</p>\n<h2>Идём в шорт</h2><p><strong>Шорт</strong> ставит на то, что цена упадёт. Вы зарабатываете при падении цены и теряете при росте — шортинг позволяет зарабатывать в нисходящем тренде. Шорт ликвидируется, когда цена вырастает достаточно далеко против вас.</p>\n<h2>Риск не симметричен</h2><p>Лонг может упасть только до нуля, но у шорта теоретически неограниченный убыток, если цена продолжает расти — вот почему шорт-сквизы могут быть жестокими. В любом случае плечо задаёт, насколько близко ваша <a href=\"/guides/what-is-liquidation-price/\">цена ликвидации</a> к входу. Протестируйте обе стороны без риска на <a href=\"/paper-trade\">Paper Trade</a>.</p>","faq":[["Что значит идти в шорт в крипте?","Шортинг означает ставку на падение цены: вы зарабатываете, когда она падает, и теряете, когда растёт, что позволяет зарабатывать в нисходящем тренде."],["Шортинг рискованнее лонга?","У шорта теоретически неограниченный убыток, если цена продолжает расти, тогда как лонг может упасть только до нуля — поэтому нехеджированный шорт может быть рискованнее, а шорт-сквизы могут быть резкими."]]},"what-is-mark-price":{"title":"Что такое маркировочная цена в крипто-фьючерсах?","desc":"Почему биржи ликвидируют по маркировочной цене, а не по последней, и как это защищает вас от выбивания фитилём на тонкой книге ордеров.","toolLabel":"Калькулятор ликвидации","body":"<h2>Последняя цена против маркировочной</h2><p><strong>Последняя цена</strong> — это просто самая недавняя сделка на этой бирже. <strong>Маркировочная цена</strong> (mark price) — это более справедливый ориентир, обычно построенный из индекса нескольких спотовых рынков плюс базис финансирования, который сглаживает всплески одной биржи.</p>\n<h2>Почему это важно</h2><p>Биржи рассчитывают ваш нереализованный PnL и вашу <a href=\"/guides/what-is-liquidation-price/\">ликвидацию</a> по <strong>маркировочной цене</strong>, а не по последней. Это защищает вас от ликвидации коротким фитилём на тонкой книге, который не отражает истинный рынок.</p>\n<h2>За чем следить</h2><p>На быстрых рынках последняя цена может улететь далеко за маркировочную. Ваша позиция оценивается по марке, поэтому проверяйте её — а не мигающую последнюю цену — когда вы близко к своему уровню ликвидации.</p>","faq":[["Почему биржи используют маркировочную цену для ликвидации?","Маркировочная цена — это справедливая стоимость на основе индекса, которая сглаживает всплески одной биржи, поэтому короткий фитиль на тонкой книге ордеров не может ошибочно ликвидировать здоровую позицию."],["Маркировочная цена — это то же, что и последняя?","Нет. Последняя цена — это самая недавняя сделка на этой бирже; маркировочная цена — это более справедливая стоимость на основе индекса, используемая для расчёта PnL и ликвидаций."]]}},"tr":{"how-to-read-funding-rates":{"title":"Kripto Funding Oranları Nasıl Okunur","desc":"Perpetual funding oranları için sade bir rehber: pozitif ve negatif funding ne anlama gelir, kalabalık long ve short pozisyonlar nasıl fark edilir ve funding uçlarından nasıl yararlanılır.","toolLabel":"Canlı funding tarayıcısı","body":"<h2>Funding oranı nedir</h2><p>Bir perpetual vadeli işlemde vade sonu yoktur, bu yüzden borsalar perp fiyatını spota bağlı tutmak için küçük ve tekrarlayan bir ödeme kullanır — <strong>funding oranı</strong>. Bu ödeme genellikle longlar ile shortlar arasında her 8 saatte bir gerçekleşir.</p>\n<h2>Pozitif ve negatif funding</h2><p><strong>Pozitif funding</strong>, perpin spotun üzerinde işlem gördüğü anlamına gelir, dolayısıyla <em>longlar shortlara öder</em> — piyasa long tarafına yatkındır. <strong>Negatif funding</strong>, perpin spotun altında işlem gördüğü anlamına gelir, dolayısıyla <em>shortlar longlara öder</em> — piyasa short tarafına yatkındır.</p>\n<h2>Uçları okumak</h2><p>Funding çok pozitifken longlar kalabalıktır ve pozisyonu tutmak için prim ödüyordur; fiyattaki bir takılma <strong>long squeeze</strong> tetikleyebilir. Funding derin negatifken shortlar kalabalıktır ve bir sıçrama <strong>short squeeze</strong> zorlayabilir. Funding bir sinyal olarak en güçlü etkisini <a href=\"/open-interest/\">open interest</a> ve <a href=\"/long-short/\">long/short konumlanması</a> ile birlikte gösterir.</p>\n<h2>Maliyete dikkat edin</h2><p>Yüksek kaldıraçta funding maliyeti hızla birikir ve fiyat yatay olsa bile bir pozisyonu sessizce eritebilir. Bunu daima tutma sürenize dahil edin.</p>","faq":[["Yüksek funding oranı ne anlama gelir?","Yüksek pozitif funding, piyasanın ağırlıklı olarak long olduğu ve longların pozisyonu tutmak için ödeme yaptığı anlamına gelir — bir geri çekilmede short squeeze körükleyebilecek kalabalık longların işareti."],["Negatif funding boğa sinyali midir?","Negatif funding, shortların kalabalık olduğu ve longlara ödeme yaptığı anlamına gelir. Sık sık ters yönlü olarak yukarı yönlü bir squeeze hazırlığı olarak okunur, ancak bu funding, open interest ve fiyat arasında yalnızca bir sinyaldir."]]},"how-to-read-liquidations":{"title":"Kripto Likidasyonları Nasıl Okunur","desc":"Kripto likidasyonlarını anlayın: ne olduklarını, long ve short likidasyonları arasındaki farkı ve likidasyon zincirlerinin volatiliteyi nasıl yönlendirdiğini.","toolLabel":"Canlı likidasyon takipçisi","body":"<h2>Likidasyon nedir</h2><p>Bir <strong>likidasyon</strong>, traderın teminatı artık zararı karşılayamadığı için borsanın kaldıraçlı bir pozisyonu zorla kapatmasıdır. Pozisyon piyasa fiyatından kapatılır ve trader teminatını kaybeder. Yüksek kaldıraçta likidasyon fiyatı girişe çok yakın bulunur.</p>\n<h2>Long ve short likidasyonları</h2><p><strong>Long likidasyonları</strong>, fiyat düştüğünde silinen aşırı kaldıraçlı alıcılardır. <strong>Short likidasyonları</strong>, fiyat yükseldiğinde silinen satıcılardır. Büyük ve tek taraflı bir ani yükseliş çoğu zaman yerel bir uç noktayı işaret eder — bir long likidasyon dalgası dip oluşturabilir, bir short likidasyon dalgası ralliyi körükleyebilir.</p>\n<h2>Likidasyon zincirleri</h2><p>Likidasyonlar yakıt gibi davranır. Fiyat kaldıraçla dolu bir bölgeye çarptığında, zorla açılan emirler fiyatı daha da iter ve daha fazla likidasyon tetikler — bir <strong>zincirleme (cascade)</strong>. Kaldıracın en yoğun olduğu yeri izlemek, kalabalık işlemden kaçınmanıza yardımcı olur.</p>\n<h2>Gerisiyle birlikte kullanın</h2><p>Likidasyonları <a href=\"/funding/\">funding</a> ve <a href=\"/open-interest/\">open interest</a> ile birlikte değerlendirin: open interestteki bir düşüş, kaldıraç temizlendikçe genellikle bir zincirlemeyi izler.</p>","faq":[["Likidasyona ne sebep olur?","Fiyat pozisyona karşı yeterince hareket ettiğinde ve teminat artık zararı karşılayamadığında pozisyon likide edilir, böylece borsa onu otomatik olarak kapatır."],["Long mu yoksa short likidasyonları mı boğa sinyalidir?","Bir long likidasyon dalgası (düşüşte) yerel bir dip oluşturabilir; bir short likidasyon dalgası (rallide) yukarı yönlü bir squeeze körükleyebilir."]]},"what-is-open-interest":{"title":"Kriptoda Open Interest Nedir?","desc":"Open interest açıklandı: hacimden nasıl farklıdır, artan ve azalan OI neyi gösterir ve OI fiyatla birlikte nasıl okunur.","toolLabel":"Canlı open interest takipçisi","body":"<h2>Open interest ve hacim</h2><p><strong>Open interest (OI)</strong>, bir coindeki tüm açık perpetual-vadeli pozisyonların toplam değeridir. Her işlemi sayan hacmin aksine, OI piyasada şu anda ne kadar kaldıracın <em>açık</em> olduğunu ölçer.</p>\n<h2>Artan ve azalan OI</h2><p>Artan OI, yeni pozisyonların ve taze kaldıracın piyasaya girdiği anlamına gelir. Azalan OI, traderların pozisyon kapattığı anlamına gelir. OIdaki ani bir düşüş, genellikle aşırı kaldıraçlı pozisyonlar temizlendikçe bir <a href=\"/liquidations/\">likidasyon zincirlemesini</a> izler.</p>\n<h2>OIyı fiyatla okumak</h2><p><strong>Fiyat yukarı + OI yukarı</strong> = hareketi destekleyen yeni para (daha güçlü trend). <strong>Fiyat yukarı + OI aşağı</strong> = taze talep yerine short kapatma. Yoğun OI birikimi artı tek taraflı <a href=\"/funding/\">funding</a>, kalabalık ve kırılgan bir kurulumu işaret eder.</p>","faq":[["Yüksek open interest boğa mı ayı mı?","Tek başına ne biri ne diğeri — fiyata bağlıdır. Artan OI ile birlikte artan fiyat yeni alıcıları gösterir; artan OI ile birlikte düşen fiyat yeni satıcıları gösterir."],["Azalan open interest ne anlama gelir?","Azalan OI, pozisyonların kapatıldığı anlamına gelir, genellikle bir likidasyon zincirlemesi kaldıracı piyasadan temizledikten sonra."]]},"long-short-ratio-explained":{"title":"Kripto Long/Short Oranı Açıklandı","desc":"Long/short oranı trader konumlanması hakkında ne söyler, kalabalık uçlar nasıl okunur ve neden en iyi ters yönlü kullanılır.","toolLabel":"Canlı long/short oranı","body":"<h2>Neyi ölçer</h2><p><strong>Long/short oranı</strong>, bir coinde trader hesaplarının yüzde kaçının long, yüzde kaçının short konumlandığını gösterir. Kalabalık konumlanmasının ve duyarlılığın anlık bir görüntüsüdür.</p>\n<h2>Kalabalığı okumak</h2><p>Deneyimli traderlar uçları sık sık <strong>ters yönlü</strong> okur. Çoğu hesap zaten longken alım büyük ölçüde tükenmiştir ve kalabalık bir <strong>long squeeze</strong> riskine açıktır. Kalabalık ağır short olduğunda, bir sıçrama bir <strong>short squeeze</strong> zorlayabilir.</p>\n<h2>Bir sinyal, tüm resim değil</h2><p>Kalabalık bir emir defteri, bir trend sürerken kalabalık kalabilir. Harekete geçmeden önce oranı <a href=\"/funding/\">funding</a> (kalabalığın tutmak için ödediği) ve <a href=\"/liquidations/\">likidasyonlar</a> (kaldıracın temizlendiği yer) ile birleştirin.</p>","faq":[["İyi bir long/short oranı nedir?","Tek bir iyi değer yoktur — en faydalı olduğu yer uçlardır. Çok yüksek bir long payı kalabalık longlara karşı uyarır; çok yüksek bir short payı kalabalık shortlara karşı uyarır."],["Traderlar long/short oranını nasıl kullanır?","Çoğu onu ters yönlü okur: aşırı konumlanmış tarafa karşı pozisyon alır ve daima funding, open interest ve fiyat hareketiyle teyit eder."]]},"what-is-liquidation-price":{"title":"Kriptoda Likidasyon Fiyatı Nedir?","desc":"Likidasyon fiyatı nedir, kaldıraç onu girişinize nasıl yaklaştırır ve bir pozisyon açmadan önce nasıl hesaplanır.","toolLabel":"Likidasyon fiyatı hesaplayıcısı","body":"<h2>Nedir</h2><p><strong>Likidasyon fiyatınız</strong>, teminatınız artık zararı karşılayamadığı için borsanın kaldıraçlı pozisyonunuzu zorla kapattığı fiyattır. Onu geçtiğinizde teminatınızı kaybedersiniz. Pozisyon açmadan önce onu bilmek, kaldıraçlı işlemdeki tek en önemli rakamdır.</p>\n<h2>Kaldıraç onu nasıl hareket ettirir</h2><p>Kaldıracınız ne kadar yüksekse, likidasyon fiyatı girişinize o kadar yakın bulunur. 5× kaldıraçta bir long, kabaca %20'lik bir düşüşte likide edilir; 100× kaldıraçta ise yaklaşık %1'lik bir harekette. Yüksek kaldıracın bu kadar kırılgan olmasının nedeni budur — sıradan bir fitil bir pozisyonu silebilir.</p>\n<h2>Nasıl hesaplanır</h2><p>İzole bir long için, likidasyon ≈ giriş × (1 − 1/kaldıraç + sürdürme-teminat oranı); shortlarda işaret tersine döner. Kesin rakam borsanın sürdürme teminatına ve ücretlerine bağlıdır, bu yüzden coininiz ve kaldıracınız için bir <a href=\"/btc-liquidation-calculator/\">likidasyon hesaplayıcısı</a> ile teyit edin.</p>\n<h2>Ona alan bırakın</h2><p>Boyutunuzu ve kaldıracınızı, likidasyon fiyatı gürültünün ötesinde — belirgin destek ve dirençlerin ve son fitillerin gerisinde — kalacak şekilde ayarlayın, girişinizin tam üzerinde değil. Ayrıca bkz. <a href=\"/guides/how-to-avoid-liquidation/\">likidasyondan nasıl kaçınılır</a>.</p>","faq":[["Likidasyon fiyatı nasıl hesaplanır?","Kabaca, bir long için likidasyon ≈ giriş × (1 − 1/kaldıraç + sürdürme teminatı), shortlar tersine. Kesin değer borsanın sürdürme-teminat oranına ve ücretlerine bağlıdır."],["Daha yüksek kaldıraç daha yakın bir likidasyon fiyatı mı demektir?","Evet. 100× kaldıraçta likidasyon fiyatı girişten yalnızca yaklaşık %1 uzaktayken, 5× kaldıraçta %20'ye daha yakındır — daha yüksek kaldıraç, fiyatın size karşı hareket etmesi için neredeyse hiç alan bırakmaz."]]},"isolated-vs-cross-margin":{"title":"İzole ve Cross Margin Açıklandı","desc":"İzole ve cross margin arasındaki fark, risk dengesi ve hangi modun hangi trader tarzına uygun olduğu.","toolLabel":"Paper Trade'de pratik yapın","body":"<h2>İzole margin</h2><p><strong>İzole margin</strong> modunda yalnızca bir pozisyona atadığınız teminat risk altındadır. Likide olursa, zarar o teminatla sınırlanır ve bakiyenizin geri kalanına dokunulmaz. Yüksek kaldıraçlı işlemler için daha güvenli varsayılan moddur.</p>\n<h2>Cross margin</h2><p><strong>Cross margin</strong> modunda tüm hesap bakiyeniz pozisyonu destekler. Bu, likidasyon fiyatını daha uzağa iter, ancak tek bir kötü işlem yalnızca bir pozisyonun teminatını değil, tüm hesabı boşaltabilir.</p>\n<h2>Hangisini kullanmalı</h2><p>Çoğu trader, tanımlı riskli, yüksek kaldıraçlı kurulumlar için <strong>izole</strong>, aktif olarak yönettiği veya hedge ettiği daha düşük kaldıraçlı pozisyonlar için <strong>cross</strong> kullanır. Denge şudur: izole zararınızı sınırlar; cross likidasyon riskini düşürür ama maksimum zararınızı artırır. Her iki durumda da önce <a href=\"/guides/what-is-liquidation-price/\">likidasyon fiyatını</a> kontrol edin.</p>","faq":[["İzole mi yoksa cross margin mi daha güvenli?","İzole, zararları sınırlamak için daha güvenlidir — yalnızca atanan teminat risk altındadır. Cross margin likide edilmesi daha zordur ama tüm bakiyenizi ortaya koyar."],["Cross margin'i ne zaman kullanmalıyım?","Cross, teminat eklemeden volatiliteyi atlatmasını istediğiniz, aktif olarak yönettiğiniz veya hedge ettiğiniz daha düşük kaldıraçlı pozisyonlara uygundur."]]},"how-to-calculate-position-size":{"title":"Kriptoda Pozisyon Boyutu Nasıl Hesaplanır","desc":"Her işlemi içgüdüyle değil riskle boyutlandırın: hesabınızdan, stop mesafesinden ve işlem başına riskten pozisyon boyutu nasıl bulunur.","toolLabel":"Pozisyon boyutu hesaplayıcısı","body":"<h2>Önce risk, sonra boyut</h2><p>Profesyonel boyutlandırma tek bir rakamdan başlar: işlemde kaybetmeye razı olduğunuz miktar. Yaygın bir kural <strong>işlem başına hesabınızın %1–2'sini riske atmaktır</strong>. Pozisyon boyutunuz ardından stop mesafenizden çıkar.</p>\n<h2>Formül</h2><p>Pozisyon boyutu = (hesap × risk %) ÷ (stop mesafesi %). $20 riske atıp stopunuz %2 uzaktaysa, $1,000 maruziyet alırsınız — kaldıraçtan bağımsız olarak. Kaldıraç yalnızca gereken teminatı belirler, riskinizi değil.</p>\n<h2>Kaldıraç risk değildir</h2><p>Çoğu yeni başlayanın kaçırdığı nokta budur: riskiniz boyut ve stop tarafından belirlenir, kaldıraç tarafından değil. Küçük, iyi stop konmuş bir pozisyonda 10× kaldıraç, aşırı büyük bir pozisyonda 2× kaldıraçtan çok daha güvenli olabilir. Her işlemin aynı miktarı riske atması için bir <a href=\"/calculators?c=size\">pozisyon boyutu hesaplayıcısı</a> kullanın ve <a href=\"/guides/what-is-liquidation-price/\">likidasyon fiyatınıza</a> göz kulak olun.</p>","faq":[["İşlem başına ne kadar risk almalıyım?","Yaygın olarak kullanılan bir kılavuz işlem başına hesabınızın %1–2'sidir, böylece bir dizi zarar hesabı patlatamaz."],["Kaldıraç pozisyon boyutumu değiştirir mi?","Hayır — riskiniz pozisyon boyutu ve stop mesafesi tarafından belirlenir. Kaldıraç yalnızca o pozisyonu tutmak için gereken teminatı belirler."]]},"what-is-leverage-in-crypto":{"title":"Kripto İşlemlerinde Kaldıraç Nedir?","desc":"Kaldıraç basitçe açıklandı: 10× veya 100× nasıl çalışır, likidasyon fiyatınıza ne yapar ve patlamadan nasıl kullanılır.","toolLabel":"Likidasyon hesaplayıcısı","body":"<h2>Kaldıraç ne yapar</h2><p><strong>Kaldıraç</strong>, teminatınızdan daha büyük bir pozisyonu kontrol etmenizi sağlar. 10× kaldıraçta $100 teminat $1,000 maruziyeti kontrol eder, böylece %1'lik bir hareket teminatınızda %10'luk bir salınıma dönüşür — kazançlar ve zararlar her ikisi de büyür.</p>\n<h2>İşin püf noktası: likidasyon</h2><p>Madalyonun diğer yüzü <a href=\"/guides/what-is-liquidation-price/\">likidasyon fiyatınızdır</a>. Kaldıraç ne kadar yüksekse, sizi silen hareket o kadar küçüktür — 100× kaldıraçta kabaca %1, 50× kaldıraçta %2, 10× kaldıraçta %10. Büyütülmüş yukarı yön, büyütülmüş kırılganlıkla gelir.</p>\n<h2>Mantıklı kullanmak</h2><p>Kaldıraç, sermaye verimliliği için bir araçtır, sonuna kadar zorlanacak bir rakam değil. <a href=\"/guides/how-to-calculate-position-size/\">Riske</a> göre boyutlandırın, likidasyon fiyatını gürültünün ötesinde tutun ve funding maliyetlerinin teminatla değil pozisyon boyutuyla orantılı olduğunu unutmayın.</p>","faq":[["10x kaldıraç ne demek?","10× kaldıraç, pozisyonunuzun teminatınızın on katı olması demektir: $100, $1,000'i kontrol eder, böylece %1'lik bir fiyat hareketi teminatınızda %10'luk bir harekete eşittir — her iki yönde de."],["Yüksek kaldıraç kötü müdür?","Yüksek kaldıraç doğası gereği kötü değildir, ama likidasyon fiyatınızı girişe çok yakın getirir. Çoğu patlama, kaldıracın kendisinden değil, yüksek kaldıraçta aşırı boyutlandırmadan kaynaklanır."]]},"maker-vs-taker-fees":{"title":"Maker ve Taker Ücretleri Açıklandı","desc":"Maker ve taker ücretleri nedir, takerlar neden daha fazla öder ve bu fark aktif vadeli işlem traderları için nasıl birikir.","toolLabel":"Borsa ücretlerini karşılaştır","body":"<h2>Fark</h2><p>Bir <strong>maker</strong> emri deftere likidite ekler — dinlenip doldurulmayı bekleyen bir limit emir. Bir <strong>taker</strong> emri likidite çeker — bir market emri ya da anında dolarak mevcut bir teklifi alan bir limit emir. Borsalar takerlardan daha fazla ücret alır çünkü makerlar herkesin karşısında işlem yaptığı likiditeyi sağlar.</p>\n<h2>Tipik oranlar</h2><p>Büyük USDT perpetuallerinde maker ücretleri yaklaşık 0.02% ve taker ücretleri 0.04–0.06% civarındadır. Kulağa çok küçük gelir, ama günde onlarca gidiş-dönüş yapan bir gün traderı bunu defalarca öder — ve takerlar bunu her iki tarafta da öder.</p>\n<h2>Daha az nasıl ödenir</h2><p>Mümkün olan yerde maker ücretine hak kazanmak için dinlenen <strong>limit emirler</strong> kullanın, indirim için borsa tokenini tutun ve hacim arttıkça VIP kademelerini tırmanın. Önceliğiniz ücretlerse, önce <a href=\"/lowest-fee-crypto-exchange/\">borsaları taker ücretine göre karşılaştırın</a>.</p>","faq":[["Takerlar neden makerlardan daha fazla öder?","Takerlar mevcut emirleri doldurarak likidite çeker, makerlar ise deftere emir dinlendirerek likidite ekler. Borsalar piyasayı likit tuttukları için makerları daha düşük ücretlerle ödüllendirir."],["Maker ücretlerini nasıl öderim?","Anında dolan market emirleri yerine deftere dinlenen limit emirler yerleştirin. Emriniz eşleşmeyi beklerse, daha düşük maker ücretine hak kazanır."]]},"how-to-avoid-liquidation":{"title":"Kripto İşlemlerinde Likidasyondan Nasıl Kaçınılır","desc":"Kaldıraçlı bir pozisyonun likide edilmesini önlemenin pratik yolları — boyutlandırma ve stoplardan margin moduna ve funding'e kadar.","toolLabel":"Likidasyon fiyatınızı kontrol edin","body":"<h2>Girmeden önce fiyatı bilin</h2><p>Önce <a href=\"/guides/what-is-liquidation-price/\">likidasyon fiyatınızı</a> hesaplayın ve onun son fitillerin ve belirgin destek ile direncin ötesinde durduğundan emin olun — girişinizin tam yanında değil.</p>\n<h2>Kullanabileceğinizden daha az kaldıraç kullanın</h2><p>Bir platform 125× kaldıraç sunuyor diye onu kullanmanız gerekmez. Daha düşük kaldıraç, likidasyon fiyatını girişten daha uzağa iter ve zamanla haklı çıkmanız için size alan kazandırır.</p>\n<h2>Daima bir stop-loss koyun</h2><p>Bir stop, borsanın likidasyon motoru sizi daha kötü bir fiyattan kapatmadan önce, <em>sizin</em> seçtiğiniz bir fiyattan sizi kapatır.</p>\n<h2>Riske göre boyutlandırın</h2><p>Bir <a href=\"/guides/how-to-calculate-position-size/\">pozisyon boyutu hesaplayıcısı</a> kullanarak işlem başına sabit %1–2 riske atın, böylece hiçbir tek işlem gerçek bir hasar veremez.</p>\n<h2>İzole margin'i tercih edin</h2><p><a href=\"/guides/isolated-vs-cross-margin/\">İzole margin</a> zararı tek bir pozisyonla sınırlar. Teminatı panikle değil, bilinçli olarak ekleyin.</p>\n<h2>Funding'e dikkat edin</h2><p>Yüksek kaldıraçta, <a href=\"/funding/\">funding</a> fiyat yatay olsa bile bir pozisyonu sessizce eritir — uzun tutuşlara bunu dahil edin.</p>","faq":[["Likidasyondan kaçınmanın en iyi yolu nedir?","Daha düşük kaldıraç kullanın, daima bir stop-loss koyun, sabit bir risk yüzdesiyle boyutlandırın ve likidasyon fiyatınızı son volatilitenin epeyce ötesinde tutun."],["Stop-loss likidasyonu önler mi?","Bir stop-loss, borsa likidasyonu tetiklenmeden önce pozisyonunuzu seçtiğiniz fiyattan kapatır, bu yüzden pratikte çoğu likidasyonu önler — hızlı piyasalarda dolması koşuluyla."]]},"perpetual-vs-futures":{"title":"Perpetual ve Vadeli İşlemler: Fark Nedir?","desc":"Perpetual swaplar ve vadeli (dated) futures: vade sonu, funding ve perplerin kripto kaldıraç işlemlerine neden hâkim olduğu.","toolLabel":"Canlı funding tarayıcısı","body":"<h2>Vadeli (dated) futures</h2><p>Geleneksel bir <strong>vadeli işlem sözleşmesinin</strong> bir vade sonu tarihi vardır. O tarihte spot fiyata göre uzlaşır, böylece vade sonu yaklaştıkça sözleşme fiyatı spota yakınsar. Onu belirli bir süre için işlem yaparsınız, sonra ortadan kalkar.</p>\n<h2>Perpetual swaplar</h2><p>Bir <strong>perpetual</strong> (\"perp\") asla vade sonuna ermez. Vade sonu olmadan fiyatını spota bağlı tutmak için borsalar longlar ile shortlar arasında tekrarlayan bir <a href=\"/funding/\">funding ödemesi</a> kullanır. Bu mekanizma uzlaşmanın yerini alır.</p>\n<h2>Perpler kriptoda neden hâkim</h2><p>Perpler, traderların hiçbir rollover olmadan kaldıracı süresiz tutmasını sağlar, bu yüzden kripto türev hacminin büyük çoğunluğunu oluştururlar. Bunun bedeli funding'dir: yüksek kaldıraçta fiyat yatay olsa bile bir pozisyonu sessizce eritebilir.</p>","faq":[["Perpetual sözleşmelerin vadesi dolar mı?","Hayır. Perpetual swaplar asla vade sonuna ermez — tekrarlayan bir funding ödemesi, fiyatlarını bir uzlaşma tarihi yerine spota bağlı tutar."],["Vadeli işlemler ile perpetualler arasındaki fark nedir?","Vadeli (dated) futures bir vade sonu tarihinde uzlaşırken, perpetualler süresiz çalışır ve spota yakın kalmak için funding ödemeleri kullanır. Kripto işlemlerine perpetualler hâkimdir."]]},"long-vs-short-crypto":{"title":"Kriptoda Long ve Short Gitmek Açıklandı","desc":"Kaldıraçla long veya short gitmek ne demektir, her taraf nasıl para kazanır veya kaybeder ve likidasyon nasıl farklılaşır.","toolLabel":"Long ve short pratiği yapın","body":"<h2>Long gitmek</h2><p>Bir <strong>long</strong>, fiyatın yükseleceğine oynar. Fiyat yükseldikçe kâr eder, düştükçe kaybedersiniz. Bir long, fiyat teminatınızın zararı artık karşılayamayacağı kadar düştüğünde likide edilir.</p>\n<h2>Short gitmek</h2><p>Bir <strong>short</strong>, fiyatın düşeceğine oynar. Fiyat düştükçe kâr eder, yükseldikçe kaybedersiniz — short pozisyon, bir düşüş trendinde para kazanmanızı sağlar. Bir short, fiyat size karşı yeterince yükseldiğinde likide edilir.</p>\n<h2>Risk simetrik değildir</h2><p>Bir long yalnızca sıfıra düşebilir, ama bir short fiyat yükselmeye devam ederse teorik olarak sınırsız zarara sahiptir — short squeeze'lerin bu kadar şiddetli olabilmesinin nedeni budur. Her iki durumda da kaldıraç, <a href=\"/guides/what-is-liquidation-price/\">likidasyon fiyatınızın</a> girişe ne kadar yakın duracağını belirler. Her iki tarafı da <a href=\"/paper-trade\">Paper Trade</a> üzerinde risksiz test edin.</p>","faq":[["Kriptoda short gitmek ne demek?","Short pozisyon almak, fiyatın düşeceğine oynamak demektir: düştüğünde kâr eder, yükseldiğinde kaybedersiniz, bu da bir düşüş trendinde para kazanmanızı sağlar."],["Short gitmek long gitmekten daha mı riskli?","Bir short, fiyat yükselmeye devam ederse teorik olarak sınırsız zarara sahiptir, bir long ise yalnızca sıfıra düşebilir — bu yüzden hedge edilmemiş bir short daha riskli olabilir ve short squeeze'ler keskin olabilir."]]},"what-is-mark-price":{"title":"Kripto Vadeli İşlemlerinde Mark Price Nedir?","desc":"Borsalar neden son fiyattan değil mark price'tan likide eder ve bu, ince bir emir defteri tarafından fitillenip silinmekten sizi nasıl korur.","toolLabel":"Likidasyon hesaplayıcısı","body":"<h2>Son fiyat ve mark price</h2><p><strong>Son fiyat</strong>, o borsadaki en son işlemden ibarettir. <strong>Mark price</strong>, daha adil bir referanstır — genellikle birkaç spot piyasanın endeksinden artı bir funding bazından oluşturulur — ve tek borsa kaynaklı ani sıçramaları yumuşatır.</p>\n<h2>Neden önemli</h2><p>Borsalar gerçekleşmemiş PnL'inizi ve <a href=\"/guides/what-is-liquidation-price/\">likidasyonunuzu</a> son fiyat üzerinden değil, <strong>mark price</strong> üzerinden hesaplar. Bu, gerçek piyasayı yansıtmayan ince bir defterdeki kısa bir fitil yüzünden likide edilmekten sizi korur.</p>\n<h2>Neye dikkat etmeli</h2><p>Hızlı piyasalarda son fiyat mark price'ı epeyce aşacak şekilde sıçrayabilir. Pozisyonunuz mark üzerinden değerlendirilir, bu yüzden likidasyon seviyenize yakınken yanıp sönen son fiyatı değil — markı kontrol edin.</p>","faq":[["Borsalar likidasyon için neden mark price kullanır?","Mark price, tek borsa kaynaklı sıçramaları yumuşatan endeks tabanlı bir adil değerdir, böylece ince bir emir defterindeki kısa bir fitil sağlıklı bir pozisyonu yanlışlıkla likide edemez."],["Mark price son fiyatla aynı mıdır?","Hayır. Son fiyat, o borsadaki en son işlemdir; mark price ise PnL ve likidasyonları hesaplamak için kullanılan daha adil, endeks tabanlı bir değerdir."]]}},"zh":{"how-to-read-funding-rates":{"title":"如何解读加密货币资金费率","desc":"用大白话讲清永续资金费率：正负资金费率分别意味着什么、如何识别拥挤的多头与空头，以及如何利用资金费率的极端值。","toolLabel":"实时资金费率扫描器","body":"<h2>什么是资金费率</h2><p>永续合约没有到期日，所以交易所用一笔小额的周期性付款——<strong>资金费率</strong>——来把永续价格锚定在现货价格上。它通常每 8 小时在多头和空头之间结算一次。</p>\n<h2>正资金费率 vs 负资金费率</h2><p><strong>正资金费率</strong>意味着永续价格高于现货，所以<em>多头付钱给空头</em>——市场偏多。<strong>负资金费率</strong>意味着永续价格低于现货，所以<em>空头付钱给多头</em>——市场偏空。</p>\n<h2>解读极端值</h2><p>当资金费率非常高（正）时，多头拥挤，要付出溢价才能持仓；价格一旦停滞，就可能触发<strong>多头挤压</strong>。当资金费率深度为负时，空头拥挤，一波反弹就可能引发<strong>逼空</strong>。资金费率作为信号时，配合<a href=\"/open-interest/\">未平仓合约</a>和<a href=\"/long-short/\">多空持仓</a>一起看最有力。</p>\n<h2>留意成本</h2><p>在高杠杆下，资金费用复利累积得很快，即使价格横盘，也能悄悄耗尽一个仓位。一定要把它计入你的持仓时间。</p>","faq":[["资金费率高意味着什么？","高的正资金费率意味着市场严重偏多、多头在付钱持仓——这是多头拥挤的信号，回调时可能引发逼空。"],["负资金费率是看涨吗？","负资金费率意味着空头拥挤、在付钱给多头。它常被反向解读为一个向上挤压的布局信号，但它只是资金费率、未平仓合约和价格中的一个信号而已。"]]},"how-to-read-liquidations":{"title":"如何解读加密货币爆仓","desc":"理解加密货币爆仓：它们是什么、多头爆仓与空头爆仓的区别，以及爆仓连锁如何驱动波动。","toolLabel":"实时爆仓追踪器","body":"<h2>什么是爆仓</h2><p><strong>爆仓</strong>是指交易所强制平掉一个杠杆仓位，因为交易者的保证金已经无法覆盖亏损。仓位以市价被平掉，交易者损失全部保证金。在高杠杆下，爆仓价离开仓价非常近。</p>\n<h2>多头爆仓 vs 空头爆仓</h2><p><strong>多头爆仓</strong>是过度加杠杆的买家在价格下跌时被清洗。<strong>空头爆仓</strong>是卖家在价格上涨时被清洗。一边倒的大规模爆仓峰值往往标志着一个局部极值——一波多头爆仓的清洗可能标志着底部，一波空头爆仓则可能助推上涨。</p>\n<h2>爆仓连锁</h2><p>爆仓就像燃料。当价格触及一个堆满杠杆的区域时，强平订单会把价格推得更远，触发更多爆仓——形成<strong>连锁反应</strong>。观察杠杆最密集的地方，能帮你避开拥挤的交易。</p>\n<h2>结合其余指标</h2><p>把爆仓和<a href=\"/funding/\">资金费率</a>以及<a href=\"/open-interest/\">未平仓合约</a>一起看：连锁爆仓之后，未平仓合约通常会随杠杆被清洗而下降。</p>","faq":[["是什么导致了爆仓？","当价格逆着仓位移动到足够远、保证金再也无法覆盖亏损时，仓位就会被爆仓，交易所会自动平掉它。"],["多头爆仓还是空头爆仓更看涨？","一波多头爆仓的峰值（在下跌中）可能标志着局部底部；一波空头爆仓的峰值（在上涨中）则可能助推向上的逼空。"]]},"what-is-open-interest":{"title":"加密货币中的未平仓合约是什么？","desc":"未平仓合约详解：它与成交量有何不同、未平仓上升和下降分别意味着什么，以及如何结合价格解读未平仓合约。","toolLabel":"实时未平仓合约追踪器","body":"<h2>未平仓合约 vs 成交量</h2><p><strong>未平仓合约（OI）</strong>是某个币种所有未平永续合约仓位的总价值。和成交量不同——成交量统计每一笔交易——OI 衡量的是市场中当前<em>开着的</em>杠杆有多少。</p>\n<h2>未平仓上升和下降</h2><p>未平仓上升意味着新仓位和新杠杆正在进场。未平仓下降意味着交易者正在平仓。OI 的骤降通常出现在一波<a href=\"/liquidations/\">爆仓连锁</a>之后，因为过度加杠杆的仓位被清洗了。</p>\n<h2>结合价格解读未平仓</h2><p><strong>价格涨 + OI 涨</strong> = 有新资金在支撑这波行情（趋势更强）。<strong>价格涨 + OI 跌</strong> = 是空头回补，而非新的买盘需求。OI 大量堆积加上一边倒的<a href=\"/funding/\">资金费率</a>，预示着一个拥挤、脆弱的布局。</p>","faq":[["未平仓合约高是看涨还是看跌？","单看它本身都不是——要看价格。OI 上升伴随价格上涨意味着新买家进场；OI 上升伴随价格下跌则意味着新卖家进场。"],["未平仓合约下降意味着什么？","未平仓下降意味着仓位正在被平掉，通常发生在一波爆仓连锁把杠杆清洗出市场之后。"]]},"long-short-ratio-explained":{"title":"加密货币多空比详解","desc":"多空比能告诉你关于交易者持仓的什么信息、如何解读拥挤的极端值，以及为什么它最适合反向使用。","toolLabel":"实时多空比","body":"<h2>它衡量什么</h2><p><strong>多空比</strong>显示在某个币种上，交易者账户中做多与做空的百分比各是多少。它是群体持仓和市场情绪的一张快照。</p>\n<h2>解读群体</h2><p>有经验的交易者常常<strong>反向</strong>解读极端值。当大多数账户已经做多时，买盘基本耗尽，群体就暴露在<strong>多头挤压</strong>的风险下。当群体严重做空时，一波反弹就可能引发<strong>逼空</strong>。</p>\n<h2>只是一个信号，不是全貌</h2><p>一个拥挤的盘口可以在趋势延续时一直保持拥挤。在行动之前，把这个比率和<a href=\"/funding/\">资金费率</a>（群体为持仓付出的代价）以及<a href=\"/liquidations/\">爆仓</a>（杠杆被清洗的地方）结合起来看。</p>","faq":[["多少的多空比算好？","没有单一的好数值——它在极端处最有用。多头占比非常高警示多头拥挤；空头占比非常高则警示空头拥挤。"],["交易者如何使用多空比？","很多人反向使用它：与持仓过度的一方对着干，并始终用资金费率、未平仓合约和价格走势来确认。"]]},"what-is-liquidation-price":{"title":"加密货币中的爆仓价是什么？","desc":"什么是爆仓价、杠杆如何把它推近你的开仓价，以及如何在开仓前算出它。","toolLabel":"爆仓价计算器","body":"<h2>它是什么</h2><p>你的<strong>爆仓价</strong>是交易所强制平掉你杠杆仓位的价格，因为你的保证金已经无法覆盖亏损。一旦越过它，你就损失全部保证金。在开仓前就知道这个数字，是杠杆交易中最重要的一个数。</p>\n<h2>杠杆如何移动它</h2><p>杠杆越高，爆仓价离你的开仓价就越近。在 5× 时，一个多头大约下跌 20% 就会被爆仓；在 100× 时大约 1% 的波动就够了。这就是为什么高杠杆如此脆弱——一根普通的插针就能清掉一个仓位。</p>\n<h2>它是如何计算的</h2><p>对于一个逐仓多头，爆仓价 ≈ 开仓价 ×（1 − 1/杠杆 + 维持保证金率）；空头则把符号反过来。具体数值取决于交易所的维持保证金和手续费，所以请用一个针对你的币种和杠杆的<a href=\"/btc-liquidation-calculator/\">爆仓价计算器</a>来确认。</p>\n<h2>给它留出空间</h2><p>设置你的仓位大小和杠杆，让爆仓价落在噪音之外——越过明显的支撑阻力和近期的插针——而不是紧贴着你的开仓价。另见<a href=\"/guides/how-to-avoid-liquidation/\">如何避免爆仓</a>。</p>","faq":[["爆仓价是怎么计算的？","大致来说，多头的爆仓价 ≈ 开仓价 ×（1 − 1/杠杆 + 维持保证金），空头则反过来。精确值取决于交易所的维持保证金率和手续费。"],["更高的杠杆意味着更近的爆仓价吗？","是的。在 100× 时爆仓价离开仓价只有约 1%，而在 5× 时接近 20%——更高的杠杆几乎不给价格留下逆向波动的空间。"]]},"isolated-vs-cross-margin":{"title":"逐仓 vs 全仓保证金详解","desc":"逐仓保证金和全仓保证金的区别、风险权衡，以及哪种模式适合哪种风格的交易者。","toolLabel":"在模拟交易中练习","body":"<h2>逐仓保证金</h2><p>在<strong>逐仓保证金</strong>模式下，只有你分配给某个仓位的保证金面临风险。如果它爆仓，亏损被限制在那笔保证金内，你余额的其余部分毫发无损。对于高杠杆交易，它是更安全的默认选择。</p>\n<h2>全仓保证金</h2><p>在<strong>全仓保证金</strong>模式下，你整个账户余额都在为这个仓位兜底。这会把爆仓价推得更远，但一笔糟糕的交易就可能耗尽整个账户，而不只是一个仓位的保证金。</p>\n<h2>该用哪个</h2><p>大多数交易者在风险明确的高杠杆布局上用<strong>逐仓</strong>，在他们主动管理或对冲的低杠杆仓位上用<strong>全仓</strong>。这个权衡是：逐仓限制了你的亏损；全仓降低了爆仓风险但提高了你的最大亏损。无论哪种，先查看<a href=\"/guides/what-is-liquidation-price/\">爆仓价</a>。</p>","faq":[["逐仓还是全仓更安全？","逐仓在限制亏损方面更安全——只有分配的保证金面临风险。全仓更难被爆仓，但会把你整个余额押上去。"],["我什么时候该用全仓保证金？","全仓适合你主动管理或对冲的低杠杆仓位，在这种情况下你希望交易能挺过波动而无需追加保证金。"]]},"how-to-calculate-position-size":{"title":"如何计算加密货币的仓位大小","desc":"按风险给每笔交易定大小，而非凭感觉：如何根据你的账户、止损距离和每笔交易的风险算出仓位大小。","toolLabel":"仓位大小计算器","body":"<h2>先定风险，再定大小</h2><p>专业的仓位定大小从一个数字开始：你愿意在这笔交易上亏多少。一个常见的规则是<strong>每笔交易冒账户 1–2% 的风险</strong>。你的仓位大小随后由你的止损距离推导出来。</p>\n<h2>公式</h2><p>仓位大小 =（账户 × 风险 %）÷（止损距离 %）。如果你冒 $20 的风险、止损在 2% 之外，那么你就建立 $1,000 的敞口——和杠杆无关。杠杆只决定所需的保证金，而不是你的风险。</p>\n<h2>杠杆不等于风险</h2><p>这是大多数新手没搞懂的关键：你的风险由仓位大小和止损决定，而非杠杆。在一个小而止损良好的仓位上用 10× 杠杆，可能远比在一个过大的仓位上用 2× 安全得多。用一个<a href=\"/calculators?c=size\">仓位大小计算器</a>，让每笔交易都冒相同金额的风险，并留意你的<a href=\"/guides/what-is-liquidation-price/\">爆仓价</a>。</p>","faq":[["每笔交易我该冒多少风险？","一个被广泛采用的准则是每笔交易冒账户 1–2% 的风险，这样一连串的亏损也无法搞垮账户。"],["杠杆会改变我的仓位大小吗？","不会——你的风险由仓位大小和止损距离决定。杠杆只决定持有那个仓位所需的保证金。"]]},"what-is-leverage-in-crypto":{"title":"什么是加密货币交易中的杠杆？","desc":"用简单方式讲清杠杆：10× 或 100× 是怎么运作的、它会对你的爆仓价做什么，以及如何在不爆仓的前提下使用它。","toolLabel":"爆仓价计算器","body":"<h2>杠杆的作用</h2><p><strong>杠杆</strong>让你控制一个比保证金更大的仓位。在 10× 时，$100 的保证金控制着 $1,000 的敞口，所以 1% 的波动就会变成你保证金上 10% 的涨跌——盈利和亏损都被放大。</p>\n<h2>代价：爆仓</h2><p>另一面就是你的<a href=\"/guides/what-is-liquidation-price/\">爆仓价</a>。杠杆越高，清掉你所需的波动就越小——大约在 100× 时 1%、50× 时 2%、10× 时 10%。被放大的上行空间伴随着被放大的脆弱性。</p>\n<h2>理智地使用它</h2><p>杠杆是提高资金效率的工具，不是一个要拉满的数字。按<a href=\"/guides/how-to-calculate-position-size/\">风险</a>来定仓位大小，让爆仓价远离噪音，并记住资金费用随仓位大小而非保证金缩放。</p>","faq":[["10 倍杠杆是什么意思？","10× 意味着你的仓位是保证金的十倍：$100 控制 $1,000，所以 1% 的价格波动等于你保证金上 10% 的波动——两个方向都是。"],["高杠杆不好吗？","高杠杆本身并不坏，但它会把你的爆仓价推到离开仓价非常近的地方。大多数爆仓源于在高杠杆下仓位过大，而不是杠杆本身。"]]},"maker-vs-taker-fees":{"title":"挂单 vs 吃单手续费详解","desc":"什么是挂单和吃单手续费、为什么吃单者付得更多，以及这个差异对活跃的合约交易者如何累积起来。","toolLabel":"比较交易所手续费","body":"<h2>区别</h2><p>一个<strong>挂单（maker）</strong>订单为盘口增加流动性——一个挂在那里等待成交的限价单。一个<strong>吃单（taker）</strong>订单移除流动性——一个市价单，或一个立即成交、吃掉现有报价的限价单。交易所对吃单者收费更高，因为挂单者提供了大家用来交易的流动性。</p>\n<h2>典型费率</h2><p>在主流 USDT 永续上，挂单手续费大约是 0.02%，吃单手续费是 0.04–0.06%。听起来很小，但一个一天做几十个来回的日内交易者会一遍又一遍地付它——而且吃单者两边都要付。</p>\n<h2>如何少付</h2><p>尽可能使用挂着的<strong>限价单</strong>来符合挂单费的条件，持有交易所平台币以获得折扣，并随着成交量增长往上爬 VIP 等级。如果手续费是你的首要考量，先<a href=\"/lowest-fee-crypto-exchange/\">按吃单费比较各交易所</a>。</p>","faq":[["为什么吃单者比挂单者付得多？","吃单者通过成交现有订单移除流动性，而挂单者通过把订单挂在盘口上增加流动性。交易所用更低的手续费奖励挂单者，因为他们让市场保持流动性。"],["我怎样才能付挂单费？","下挂在盘口上的限价单，而不是立即成交的市价单。如果你的订单等待被撮合，它就符合更低的挂单费条件。"]]},"how-to-avoid-liquidation":{"title":"如何在加密货币交易中避免爆仓","desc":"让杠杆仓位免于被爆仓的实用方法——从仓位定大小和止损，到保证金模式和资金费率。","toolLabel":"查看你的爆仓价","body":"<h2>开仓前就知道价格</h2><p>先算出你的<a href=\"/guides/what-is-liquidation-price/\">爆仓价</a>，并确保它落在近期插针和明显的支撑阻力之外——而不是紧挨着你的开仓价。</p>\n<h2>用比你能用的更低的杠杆</h2><p>某个平台提供 125× 并不意味着你就该用它。更低的杠杆把爆仓价推得离开仓价更远，为你随时间证明自己正确买来空间。</p>\n<h2>永远设置止损</h2><p>止损会在交易所的爆仓引擎以更糟的价格替你平仓之前，在一个<em>你</em>选定的价格把你平掉。</p>\n<h2>按风险定大小</h2><p>用一个<a href=\"/guides/how-to-calculate-position-size/\">仓位大小计算器</a>，每笔交易冒固定的 1–2% 风险，这样任何单笔交易都无法造成真正的伤害。</p>\n<h2>优先用逐仓保证金</h2><p><a href=\"/guides/isolated-vs-cross-margin/\">逐仓保证金</a>把亏损限制在一个仓位内。要刻意地、而非在恐慌中追加保证金。</p>\n<h2>留意资金费率</h2><p>在高杠杆下，<a href=\"/funding/\">资金费率</a>即使在价格横盘时也会悄悄耗尽一个仓位——把它计入长时间的持仓。</p>","faq":[["避免爆仓最好的方法是什么？","使用更低的杠杆，永远设置止损，按固定的风险百分比定仓位大小，并让你的爆仓价远远落在近期波动之外。"],["止损能阻止爆仓吗？","止损会在交易所爆仓触发之前，在你选定的价格平掉你的仓位，所以实际上它能阻止大多数爆仓——前提是它能在快速行情中成交。"]]},"perpetual-vs-futures":{"title":"永续 vs 交割合约：有什么区别？","desc":"永续合约对比有到期日的交割合约：到期、资金费率，以及为什么永续主导着加密货币的杠杆交易。","toolLabel":"实时资金费率扫描器","body":"<h2>交割合约</h2><p>传统的<strong>期货合约</strong>有一个到期日。在那一天它按现货价格结算，所以随着到期临近，合约价格会向现货收敛。你按一个固定期限交易它，然后它就消失了。</p>\n<h2>永续合约</h2><p>一个<strong>永续合约</strong>（\"perp\"）永不到期。为了在没有到期日的情况下把它的价格锚定在现货上，交易所在多头和空头之间使用一笔周期性的<a href=\"/funding/\">资金费用</a>。这个机制取代了结算。</p>\n<h2>为什么永续主导加密货币</h2><p>永续让交易者无需展期就能无限期持有杠杆，这就是为什么它们占据了加密货币衍生品成交量的绝大部分。代价是资金费率：在高杠杆下，即使价格横盘，它也能悄悄耗尽一个仓位。</p>","faq":[["永续合约会到期吗？","不会。永续合约永不到期——一笔周期性的资金费用让它们的价格锚定在现货上，而非锚定在某个结算日。"],["交割合约和永续合约有什么区别？","有到期日的交割合约在到期日结算，而永续合约无限期运行，并用资金费用来保持靠近现货。加密货币交易由永续合约主导。"]]},"long-vs-short-crypto":{"title":"加密货币做多 vs 做空详解","desc":"用杠杆做多或做空意味着什么、每一方如何盈亏，以及爆仓有何不同。","toolLabel":"练习做多和做空","body":"<h2>做多</h2><p>一个<strong>多头</strong>押注价格会上涨。价格上涨你盈利，下跌你亏损。当价格下跌到足够远、你的保证金再也无法覆盖亏损时，多头就会被爆仓。</p>\n<h2>做空</h2><p>一个<strong>空头</strong>押注价格会下跌。价格下跌你盈利，上涨你亏损——做空让你能在下跌趋势中赚钱。当价格逆着你上涨到足够远时，空头就会被爆仓。</p>\n<h2>风险并不对称</h2><p>一个多头最多只能跌到零，但一个空头如果价格持续上涨，理论上亏损是无限的——这就是为什么逼空可能非常猛烈。无论哪种，杠杆决定了你的<a href=\"/guides/what-is-liquidation-price/\">爆仓价</a>离开仓价有多近。在<a href=\"/paper-trade\">模拟交易</a>上无风险地测试两边。</p>","faq":[["在加密货币中做空是什么意思？","做空意味着押注价格会下跌：价格下跌你盈利、上涨你亏损，这让你能在下跌趋势中赚钱。"],["做空比做多风险更大吗？","如果价格持续上涨，空头理论上有无限亏损，而多头最多只能跌到零——所以一个未对冲的空头可能风险更大，而且逼空可能很剧烈。"]]},"what-is-mark-price":{"title":"加密货币合约中的标记价格是什么？","desc":"为什么交易所按标记价格而非最新价格爆仓，以及它如何保护你不被一个稀薄的盘口插针清洗出局。","toolLabel":"爆仓价计算器","body":"<h2>最新价格 vs 标记价格</h2><p><strong>最新价格</strong>就是那个交易所上最近的一笔成交。<strong>标记价格</strong>是一个更公平的参考——通常由多个现货市场的指数加上一个资金费率基差构成——它平滑掉了单一交易所的尖峰。</p>\n<h2>为什么它重要</h2><p>交易所计算你的未实现盈亏和<a href=\"/guides/what-is-liquidation-price/\">爆仓</a>时，依据的是<strong>标记价格</strong>，而非最新价格。这能保护你不被一个稀薄盘口上、不反映真实市场的短暂插针爆仓。</p>\n<h2>该留意什么</h2><p>在快速行情中，最新价格可能远远冲过标记价格。你的仓位是按标记价格来判定的，所以当你接近爆仓水平时，要查看它——而不是那个闪烁的最新价格。</p>","faq":[["为什么交易所用标记价格来爆仓？","标记价格是一个基于指数的公平价值，它平滑掉了单一交易所的尖峰，所以稀薄盘口上的一次短暂插针无法错误地爆掉一个健康的仓位。"],["标记价格和最新价格一样吗？","不一样。最新价格是那个交易所最近的一笔成交；标记价格是用来计算盈亏和爆仓的、更公平的基于指数的价值。"]]}},"ja":{"how-to-read-funding-rates":{"title":"暗号資産の資金調達率の読み方","desc":"無期限先物の資金調達率をやさしく解説。プラスとマイナスの資金調達が何を意味するか、ロングとショートの偏りの見つけ方、資金調達率の極端値の使い方。","toolLabel":"ライブ資金調達スキャナー","body":"<h2>資金調達率とは</h2><p>無期限先物には満期がないため、取引所は無期限価格を現物に連動させるために、小さな定期的な支払い — <strong>資金調達率</strong> — を用います。通常は8時間ごとにロングとショートの間でやり取りされます。</p>\n<h2>プラスの資金調達とマイナスの資金調達</h2><p><strong>プラスの資金調達</strong>は無期限価格が現物を上回って取引されていることを意味し、<em>ロングがショートに支払う</em> — 市場がロングに傾いている状態です。<strong>マイナスの資金調達</strong>は無期限価格が現物を下回って取引されていることを意味し、<em>ショートがロングに支払う</em> — 市場がショートに傾いている状態です。</p>\n<h2>極端値を読む</h2><p>資金調達が非常にプラスのときは、ロングが過密でプレミアムを払って保有しており、価格が伸び悩むと<strong>ロングスクイーズ</strong>を引き起こすことがあります。資金調達が大きくマイナスのときは、ショートが過密で、反発が<strong>ショートスクイーズ</strong>を強制することがあります。資金調達は<a href=\"/open-interest/\">建玉</a>や<a href=\"/long-short/\">ロング/ショートのポジショニング</a>と組み合わせるとシグナルとして最も強力になります。</p>\n<h2>コストに注意</h2><p>高いレバレッジでは資金調達コストが急速に複利的に膨らみ、価格が横ばいでもポジションを静かに削っていくことがあります。常に保有期間に織り込んでおきましょう。</p>","faq":[["高い資金調達率は何を意味しますか？","高いプラスの資金調達は市場が大きくロングに傾いており、ロングが保有のために支払っていることを意味します — 過密なロングの兆候で、押し目でショートスクイーズの燃料になり得ます。"],["マイナスの資金調達は強気ですか？","マイナスの資金調達はショートが過密でロングに支払っていることを意味します。しばしば逆張り的に、上方向へのスクイーズの仕込みと読まれますが、資金調達・建玉・価格のうちの一つのシグナルにすぎません。"]]},"how-to-read-liquidations":{"title":"暗号資産の清算（ロスカット）の読み方","desc":"暗号資産の清算を理解する。清算とは何か、ロング清算とショート清算の違い、そして清算カスケードがどのようにボラティリティを生むか。","toolLabel":"ライブ清算トラッカー","body":"<h2>清算とは</h2><p><strong>清算</strong>とは、トレーダーの証拠金が損失をカバーしきれなくなったために、取引所がレバレッジポジションを強制的に決済することです。ポジションは成行で決済され、トレーダーは証拠金を失います。高いレバレッジでは清算価格はエントリーのすぐ近くに位置します。</p>\n<h2>ロング清算とショート清算</h2><p><strong>ロング清算</strong>は、価格下落時に一掃される過剰レバレッジの買い手です。<strong>ショート清算</strong>は、価格上昇時に一掃される売り手です。大きな一方向のスパイクはしばしば局所的な極値を示します — ロング清算の大量発生は底を示すことがあり、ショート清算の波は上昇を煽ることがあります。</p>\n<h2>清算カスケード</h2><p>清算は燃料のように働きます。価格がレバレッジの密集するゾーンに到達すると、強制注文が価格をさらに押し進め、より多くの清算を引き起こします — これが<strong>カスケード</strong>です。レバレッジがどこに最も厚いかを観察することで、過密なトレードを避ける助けになります。</p>\n<h2>他の指標と併用する</h2><p>清算は<a href=\"/funding/\">資金調達</a>や<a href=\"/open-interest/\">建玉</a>と組み合わせましょう。建玉の減少は通常、レバレッジが一掃されるカスケードの後に続きます。</p>","faq":[["清算は何が原因で起きますか？","ポジションは、価格が逆行して証拠金が損失をカバーできなくなったときに清算され、取引所が自動的に決済します。"],["ロング清算とショート清算、どちらが強気ですか？","ロング清算のスパイク（下落時）は局所的な底を示すことがあり、ショート清算のスパイク（上昇時）は上方向へのスクイーズを煽ることがあります。"]]},"what-is-open-interest":{"title":"暗号資産の建玉（オープンインタレスト）とは？","desc":"建玉を解説。出来高との違い、建玉の増加と減少が示すもの、そして価格と並べて建玉を読む方法。","toolLabel":"ライブ建玉トラッカー","body":"<h2>建玉と出来高</h2><p><strong>建玉（OI）</strong>は、ある銘柄のすべての未決済の無期限先物ポジションの合計額です。すべての取引を数える出来高とは異なり、建玉は現在どれだけのレバレッジが<em>未決済</em>で市場に開いているかを測ります。</p>\n<h2>建玉の増加と減少</h2><p>建玉の増加は、新規ポジションと新しいレバレッジが入ってきていることを意味します。建玉の減少は、トレーダーが手仕舞いしていることを意味します。建玉の急減は通常、過剰レバレッジのポジションが一掃される<a href=\"/liquidations/\">清算カスケード</a>の後に続きます。</p>\n<h2>価格と併せて建玉を読む</h2><p><strong>価格上昇＋建玉増加</strong>＝新規資金が動きを支えている（より強いトレンド）。<strong>価格上昇＋建玉減少</strong>＝新規需要ではなくショートの買い戻し。建玉の大幅な積み上がりと一方向の<a href=\"/funding/\">資金調達</a>が重なると、過密で脆い仕込みを示唆します。</p>","faq":[["高い建玉は強気ですか弱気ですか？","それ単独ではどちらでもなく、価格次第です。建玉の増加と価格の上昇は新規の買い手を示唆し、建玉の増加と価格の下落は新規の売り手を示唆します。"],["建玉の減少は何を意味しますか？","建玉の減少はポジションが手仕舞いされていることを意味し、しばしば清算カスケードが市場からレバレッジを一掃した後に起こります。"]]},"long-short-ratio-explained":{"title":"暗号資産のロング/ショート比率を解説","desc":"ロング/ショート比率がトレーダーのポジショニングについて何を教えてくれるか、過密な極端値の読み方、そしてなぜ逆張り的に使うのが最適なのか。","toolLabel":"ライブ ロング/ショート比率","body":"<h2>何を測っているか</h2><p><strong>ロング/ショート比率</strong>は、ある銘柄でトレーダーの口座の何割がロングとショートのどちらにポジションを取っているかを示します。これは群衆のポジショニングとセンチメントのスナップショットです。</p>\n<h2>群衆を読む</h2><p>経験豊富なトレーダーはしばしば極端値を<strong>逆張り的</strong>に読みます。すでにほとんどの口座がロングのとき、買いはほぼ出尽くしており、群衆は<strong>ロングスクイーズ</strong>にさらされています。群衆が大きくショートに偏っているとき、反発は<strong>ショートスクイーズ</strong>を強制することがあります。</p>\n<h2>一つのシグナルであり、全体像ではない</h2><p>過密な板はトレンドが続く間、過密なままでいることもあります。行動する前に、この比率を<a href=\"/funding/\">資金調達</a>（群衆が保有のために何を払っているか）や<a href=\"/liquidations/\">清算</a>（レバレッジがどこで一掃されるか）と組み合わせましょう。</p>","faq":[["良いロング/ショート比率とは？","単一の良い値というものはなく、極端値で最も役立ちます。非常に高いロング比率は過密なロングを警告し、非常に高いショート比率は過密なショートを警告します。"],["トレーダーはロング/ショート比率をどう使いますか？","多くは逆張り的に読み、ポジションが偏りすぎた側を逆張りし、常に資金調達・建玉・値動きで確認します。"]]},"what-is-liquidation-price":{"title":"暗号資産の清算価格とは？","desc":"清算価格とは何か、レバレッジがどのように清算価格をエントリーに近づけるか、そしてポジションを開く前にそれを計算する方法。","toolLabel":"清算価格計算機","body":"<h2>清算価格とは</h2><p>あなたの<strong>清算価格</strong>は、証拠金が損失をカバーしきれなくなったために取引所がレバレッジポジションを強制決済する価格です。これを超えると証拠金を失います。エントリー前にこれを知っておくことが、レバレッジ取引で最も重要な数字です。</p>\n<h2>レバレッジがどう動かすか</h2><p>レバレッジが高いほど、清算価格はエントリーに近づきます。5×ではロングはおよそ20%の下落で清算され、100×ではおよそ1%の動きで清算されます。だからこそ高いレバレッジは非常に脆いのです — ありふれたヒゲ一本でポジションが一掃され得ます。</p>\n<h2>どう計算されるか</h2><p>分離（アイソレーテッド）のロングの場合、清算 ≈ エントリー × (1 − 1/レバレッジ + 維持証拠金率)、ショートは符号が反転します。正確な数値は取引所の維持証拠金と手数料に依存するため、あなたの銘柄とレバレッジについては<a href=\"/btc-liquidation-calculator/\">清算計算機</a>で確認してください。</p>\n<h2>余裕を持たせる</h2><p>清算価格がノイズの外側 — 明白なサポートとレジスタンスや直近のヒゲの先 — に位置するように、サイズとレバレッジを設定し、エントリーの真上に置かないようにしましょう。<a href=\"/guides/how-to-avoid-liquidation/\">清算を避ける方法</a>も参照してください。</p>","faq":[["清算価格はどう計算されますか？","おおまかに、ロングでは清算 ≈ エントリー × (1 − 1/レバレッジ + 維持証拠金)、ショートはその逆です。正確な値は取引所の維持証拠金率と手数料に依存します。"],["レバレッジが高いほど清算価格は近くなりますか？","はい。100×では清算価格はエントリーからわずか約1%、5×では約20%です — レバレッジが高いほど、価格が逆行する余地はほとんど残りません。"]]},"isolated-vs-cross-margin":{"title":"分離証拠金と全体証拠金（アイソレーテッドとクロス）を解説","desc":"分離証拠金と全体証拠金の違い、リスクのトレードオフ、そしてどのモードがどのスタイルのトレーダーに合うか。","toolLabel":"ペーパートレードで練習","body":"<h2>分離証拠金（アイソレーテッド）</h2><p><strong>分離証拠金</strong>では、ポジションに割り当てた証拠金だけがリスクにさらされます。清算されても損失はその証拠金に限定され、残りの残高は無傷です。高レバレッジのトレードでは、より安全なデフォルトです。</p>\n<h2>全体証拠金（クロス）</h2><p><strong>全体証拠金</strong>では、口座残高全体がポジションを支えます。これにより清算価格はさらに遠ざかりますが、一つの悪いトレードが、一つのポジションの証拠金だけでなく口座全体を空にし得ます。</p>\n<h2>どちらを使うか</h2><p>ほとんどのトレーダーは、リスクが定義された高レバレッジの仕込みには<strong>分離</strong>を、能動的に管理またはヘッジする低レバレッジのポジションには<strong>全体</strong>を使います。トレードオフは、分離は損失を限定し、全体は清算リスクを下げるが最大損失を高めることです。いずれにせよ、まず<a href=\"/guides/what-is-liquidation-price/\">清算価格</a>を確認しましょう。</p>","faq":[["分離証拠金と全体証拠金、どちらが安全ですか？","損失を限定するという点では分離が安全です — 割り当てた証拠金だけがリスクにさらされます。全体証拠金は清算されにくいですが、残高全体を賭けることになります。"],["いつ全体証拠金を使うべきですか？","全体証拠金は、能動的に管理またはヘッジする低レバレッジのポジションに向いており、証拠金を追加せずにトレードがボラティリティを乗り切ってほしい場合に適します。"]]},"how-to-calculate-position-size":{"title":"暗号資産でのポジションサイズの計算方法","desc":"勘ではなくリスクであらゆるトレードのサイズを決める。口座・ストップ距離・トレードあたりのリスクからポジションサイズを算出する方法。","toolLabel":"ポジションサイズ計算機","body":"<h2>まずリスク、次にサイズ</h2><p>プロのサイジングは一つの数字から始まります。そのトレードでいくら失う覚悟があるか、です。一般的なルールは<strong>トレードあたり口座の1–2%をリスクにさらす</strong>ことです。ポジションサイズはそこからストップ距離に従って決まります。</p>\n<h2>計算式</h2><p>ポジションサイズ ＝ (口座 × リスク%) ÷ (ストップ距離%)。$20をリスクにさらし、ストップが2%離れているなら、レバレッジに関係なく$1,000のエクスポージャーを取ります。レバレッジは必要な証拠金を決めるだけで、あなたのリスクは決めません。</p>\n<h2>レバレッジはリスクではない</h2><p>これは初心者が最も見落とす点です。あなたのリスクはサイズとストップによって決まり、レバレッジによってではありません。小さくストップがしっかりしたポジションでの10×は、過大なポジションでの2×よりはるかに安全になり得ます。すべてのトレードが同じ額をリスクにさらすように<a href=\"/calculators?c=size\">ポジションサイズ計算機</a>を使い、<a href=\"/guides/what-is-liquidation-price/\">清算価格</a>に目を配りましょう。</p>","faq":[["1トレードあたりどれくらいリスクを取るべきですか？","広く使われる指針はトレードあたり口座の1–2%で、連敗しても口座が吹き飛ばないようにします。"],["レバレッジはポジションサイズを変えますか？","いいえ — あなたのリスクはポジションサイズとストップ距離で決まります。レバレッジはそのポジションを保有するために必要な証拠金を決めるだけです。"]]},"what-is-leverage-in-crypto":{"title":"暗号資産取引のレバレッジとは？","desc":"レバレッジをシンプルに解説。10×や100×がどう機能するか、清算価格に何をするか、そして吹き飛ばずに使う方法。","toolLabel":"清算計算機","body":"<h2>レバレッジが何をするか</h2><p><strong>レバレッジ</strong>は、証拠金より大きいポジションをコントロールできるようにします。10×では$100の証拠金が$1,000のエクスポージャーをコントロールするので、1%の動きが証拠金に対する10%のスイングになります — 利益も損失も両方が拡大されます。</p>\n<h2>落とし穴：清算</h2><p>裏側はあなたの<a href=\"/guides/what-is-liquidation-price/\">清算価格</a>です。レバレッジが高いほど、あなたを一掃する動きは小さくなります — 100×でおよそ1%、50×で2%、10×で10%です。拡大された上昇は、拡大された脆さを伴います。</p>\n<h2>賢く使う</h2><p>レバレッジは資本効率のためのツールであり、限界まで上げる数字ではありません。<a href=\"/guides/how-to-calculate-position-size/\">リスク</a>でサイズを決め、清算価格をノイズの外側に保ち、資金調達コストは証拠金ではなくポジションサイズに比例することを忘れないでください。</p>","faq":[["10倍レバレッジとは何を意味しますか？","10×はあなたのポジションが証拠金の10倍であることを意味します。$100が$1,000をコントロールするので、1%の値動きが証拠金に対する10%の動きに等しくなります — 両方向にです。"],["高いレバレッジは悪いですか？","高いレバレッジは本質的に悪いわけではありませんが、清算価格をエントリーの非常に近くに置きます。ほとんどの吹き飛びは、レバレッジそのものではなく、高いレバレッジでのサイズの取りすぎから来ます。"]]},"maker-vs-taker-fees":{"title":"メイカー手数料とテイカー手数料を解説","desc":"メイカー手数料とテイカー手数料とは何か、なぜテイカーの方が多く払うのか、そしてその差がアクティブな先物トレーダーにどう積み上がるか。","toolLabel":"取引所の手数料を比較","body":"<h2>違い</h2><p><strong>メイカー</strong>注文は板に流動性を加えます — 板に乗って約定を待つ指値注文です。<strong>テイカー</strong>注文は流動性を取り除きます — 成行注文、または既存の提示を取って即座に約定する指値です。メイカーが皆の取引相手となる流動性を提供するため、取引所はテイカーにより多くの手数料を課します。</p>\n<h2>典型的なレート</h2><p>主要なUSDT無期限では、メイカー手数料はおよそ0.02%、テイカー手数料は0.04–0.06%です。ごくわずかに聞こえますが、1日に何十回も往復するデイトレーダーは何度も何度もそれを払い — テイカーは両側で払います。</p>\n<h2>支払いを減らす方法</h2><p>可能なところでメイカー手数料の対象になるよう、板に乗る<strong>指値注文</strong>を使い、割引のために取引所トークンを保有し、出来高が増えるにつれてVIPティアを上げていきましょう。手数料が最優先なら、まず<a href=\"/lowest-fee-crypto-exchange/\">テイカー手数料で取引所を比較</a>してください。</p>","faq":[["なぜテイカーはメイカーより多く払うのですか？","テイカーは既存の注文を約定させて流動性を取り除き、メイカーは板に注文を乗せて流動性を加えます。取引所は市場の流動性を保つメイカーに低い手数料で報います。"],["どうすればメイカー手数料で取引できますか？","即座に約定する成行注文ではなく、板に乗る指値注文を出してください。注文が約定を待つ状態になれば、より低いメイカー手数料の対象になります。"]]},"how-to-avoid-liquidation":{"title":"暗号資産取引で清算を避ける方法","desc":"レバレッジポジションが清算されないようにする実践的な方法 — サイジングやストップから、証拠金モードや資金調達まで。","toolLabel":"清算価格をチェック","body":"<h2>エントリー前に価格を知る</h2><p>まず<a href=\"/guides/what-is-liquidation-price/\">清算価格</a>を計算し、それが直近のヒゲや明白なサポートとレジスタンスの外側に位置し、エントリーのすぐ隣ではないことを確認しましょう。</p>\n<h2>使えるより少ないレバレッジを使う</h2><p>取引所が125×を提供しているからといって、それを使うべきというわけではありません。低いレバレッジは清算価格をエントリーからさらに遠ざけ、時間をかけて正しくいられる余地を買ってくれます。</p>\n<h2>必ずストップロスを設定する</h2><p>ストップは、取引所の清算エンジンがより悪い価格で執行する前に、<em>あなた</em>が選んだ価格であなたを決済します。</p>\n<h2>リスクでサイズを決める</h2><p><a href=\"/guides/how-to-calculate-position-size/\">ポジションサイズ計算機</a>を使って、トレードあたり1–2%の固定リスクを取り、単一のトレードが本当のダメージを与えられないようにしましょう。</p>\n<h2>分離証拠金を優先する</h2><p><a href=\"/guides/isolated-vs-cross-margin/\">分離証拠金</a>は損失を一つのポジションに限定します。証拠金はパニックではなく、意図的に追加しましょう。</p>\n<h2>資金調達に注意する</h2><p>高いレバレッジでは、<a href=\"/funding/\">資金調達</a>が価格が横ばいでもポジションを静かに削っていきます — 長期保有には織り込んでおきましょう。</p>","faq":[["清算を避ける最良の方法は何ですか？","低いレバレッジを使い、必ずストップロスを設定し、固定のリスク割合でサイズを決め、清算価格を直近のボラティリティの十分外側に保つことです。"],["ストップロスは清算を防ぎますか？","ストップロスは取引所の清算が発動する前に、あなたの選んだ価格でポジションを決済するため、実際にはほとんどの清算を防ぎます — 速い相場でも約定すれば、です。"]]},"perpetual-vs-futures":{"title":"無期限（パープ）と先物：何が違うのか？","desc":"無期限スワップと期限付き先物：満期、資金調達、そしてなぜパープが暗号資産のレバレッジ取引を席巻しているのか。","toolLabel":"ライブ資金調達スキャナー","body":"<h2>期限付き先物</h2><p>従来の<strong>先物契約</strong>には満期日があります。その日に現物価格で決済されるため、満期が近づくにつれて契約価格は現物に収束します。決まった期間だけ取引し、その後は消滅します。</p>\n<h2>無期限スワップ</h2><p><strong>無期限</strong>（「パープ」）は決して満期を迎えません。満期なしで価格を現物に連動させるため、取引所はロングとショートの間で定期的な<a href=\"/funding/\">資金調達の支払い</a>を用います。その仕組みが決済の代わりになります。</p>\n<h2>なぜパープが暗号資産を席巻するのか</h2><p>パープはトレーダーがロールオーバーなしで無期限にレバレッジを保有できるようにするため、暗号資産デリバティブ出来高の大半を占めます。トレードオフは資金調達で、高いレバレッジでは価格が横ばいでもポジションを静かに削っていくことがあります。</p>","faq":[["無期限契約は満期を迎えますか？","いいえ。無期限スワップは決して満期を迎えません — 定期的な資金調達の支払いが、決済日ではなく現物に価格を結びつけ続けます。"],["先物と無期限の違いは何ですか？","期限付き先物は満期日に決済され、無期限は無期限に続いて資金調達の支払いで現物近辺にとどまります。暗号資産取引は無期限が席巻しています。"]]},"long-vs-short-crypto":{"title":"暗号資産でのロングとショートを解説","desc":"レバレッジをかけてロングまたはショートを取るとはどういう意味か、それぞれの側がどう利益を得たり損をしたりするか、そして清算がどう異なるか。","toolLabel":"ロングとショートを練習","body":"<h2>ロングを取る</h2><p><strong>ロング</strong>は価格が上がることに賭けます。価格が上がると利益を得て、下がると損をします。ロングは、証拠金が損失をカバーしきれなくなるほど価格が下落したときに清算されます。</p>\n<h2>ショートを取る</h2><p><strong>ショート</strong>は価格が下がることに賭けます。価格が下がると利益を得て、上がると損をします — ショートは下落トレンドで利益を得ることを可能にします。ショートは、あなたに逆行して価格が十分に上昇したときに清算されます。</p>\n<h2>リスクは対称ではない</h2><p>ロングはゼロまでしか下がれませんが、ショートは価格が上がり続けると理論上は無限の損失になり得ます — だからこそショートスクイーズは激しくなり得るのです。いずれにせよ、レバレッジが<a href=\"/guides/what-is-liquidation-price/\">清算価格</a>がエントリーからどれだけ近くに位置するかを決めます。両方の側を<a href=\"/paper-trade\">ペーパートレード</a>でリスクなしに試してみましょう。</p>","faq":[["暗号資産でショートを取るとはどういう意味ですか？","ショートとは価格が下がることに賭けることです。下がると利益を得て、上がると損をするので、下落トレンドで利益を得ることができます。"],["ショートはロングよりリスクが高いですか？","ショートは価格が上がり続けると理論上は無限の損失になり、ロングはゼロまでしか下がれません — そのためヘッジされていないショートはよりリスクが高くなり得て、ショートスクイーズは鋭くなり得ます。"]]},"what-is-mark-price":{"title":"暗号資産先物のマーク価格とは？","desc":"なぜ取引所は最終価格ではなくマーク価格で清算するのか、そしてそれが薄い板でヒゲにより一掃されることからどう守ってくれるか。","toolLabel":"清算計算機","body":"<h2>最終価格とマーク価格</h2><p><strong>最終価格</strong>は単にその取引所での直近の取引です。<strong>マーク価格</strong>はより公正な基準で — 通常は複数の現物市場のインデックスに資金調達ベーシスを加えて構成され — 単一取引所のスパイクを平滑化します。</p>\n<h2>なぜ重要か</h2><p>取引所はあなたの未実現損益と<a href=\"/guides/what-is-liquidation-price/\">清算</a>を、最終価格ではなく<strong>マーク価格</strong>に対して計算します。これにより、真の市場を反映しない薄い板の一瞬のヒゲによって清算されることから守られます。</p>\n<h2>何に注意するか</h2><p>速い相場では、最終価格がマーク価格を大きく超えてスパイクすることがあります。あなたのポジションはマークで判断されるため、清算レベルに近いときは点滅する最終価格ではなく、マークを確認してください。</p>","faq":[["なぜ取引所は清算にマーク価格を使うのですか？","マーク価格は単一取引所のスパイクを平滑化するインデックスベースの公正価値なので、薄い板の一瞬のヒゲが健全なポジションを誤って清算することができません。"],["マーク価格は最終価格と同じですか？","いいえ。最終価格はその取引所での直近の取引で、マーク価格は損益と清算の計算に使われる、より公正なインデックスベースの価値です。"]]}},"ko":{"how-to-read-funding-rates":{"title":"암호화폐 펀딩비 읽는 법","desc":"무기한 펀딩비를 쉬운 말로 풀어낸 가이드: 양수 펀딩과 음수 펀딩이 무엇을 뜻하는지, 과밀된 롱과 숏을 어떻게 포착하는지, 펀딩 극단값을 어떻게 활용하는지 설명합니다.","toolLabel":"실시간 펀딩 스캐너","body":"<h2>펀딩비란 무엇인가</h2><p>무기한 선물(perp)에는 만기가 없기 때문에, 거래소는 무기한 가격을 현물 가격에 묶어두기 위해 작은 주기적 결제 — 즉 <strong>펀딩비</strong> — 를 사용합니다. 보통 롱과 숏 사이에서 8시간마다 주고받습니다.</p>\n<h2>양수 펀딩 대 음수 펀딩</h2><p><strong>양수 펀딩</strong>은 무기한 가격이 현물보다 위에서 거래된다는 뜻으로, <em>롱이 숏에게 지불</em>합니다 — 시장이 롱으로 기울어 있는 것입니다. <strong>음수 펀딩</strong>은 무기한 가격이 현물보다 아래에서 거래된다는 뜻으로, <em>숏이 롱에게 지불</em>합니다 — 시장이 숏으로 기울어 있는 것입니다.</p>\n<h2>극단값 읽기</h2><p>펀딩비가 매우 높을 때는 롱이 과밀하고 보유에 프리미엄을 지불하고 있는 상태로, 가격이 멈추면 <strong>롱 스퀴즈</strong>가 촉발될 수 있습니다. 펀딩비가 깊은 음수일 때는 숏이 과밀한 상태로, 반등이 <strong>숏 스퀴즈</strong>를 강제할 수 있습니다. 펀딩은 <a href=\"/open-interest/\">미결제약정</a> 및 <a href=\"/long-short/\">롱/숏 포지셔닝</a>과 함께 볼 때 신호로서 가장 강력합니다.</p>\n<h2>비용을 주시하라</h2><p>높은 레버리지에서는 펀딩 비용이 빠르게 복리로 불어나, 가격이 횡보할 때조차 포지션을 조용히 갉아먹을 수 있습니다. 항상 보유 시간에 이를 반영하세요.</p>","faq":[["높은 펀딩비는 무엇을 의미하나요?","높은 양수 펀딩은 시장이 강하게 롱에 쏠려 있고 롱이 보유 비용을 지불하고 있다는 뜻으로 — 과밀된 롱의 신호이며, 조정이 나오면 숏 스퀴즈를 부추길 수 있습니다."],["음수 펀딩은 강세 신호인가요?","음수 펀딩은 숏이 과밀하고 롱에게 비용을 지불하고 있다는 뜻입니다. 흔히 역발상적으로 위쪽 스퀴즈의 셋업으로 읽지만, 펀딩·미결제약정·가격 가운데 하나의 신호일 뿐입니다."]]},"how-to-read-liquidations":{"title":"암호화폐 청산 읽는 법","desc":"암호화폐 청산을 이해하세요: 청산이 무엇인지, 롱 청산과 숏 청산의 차이, 그리고 청산 캐스케이드가 어떻게 변동성을 이끄는지 알아봅니다.","toolLabel":"실시간 청산 트래커","body":"<h2>청산이란 무엇인가</h2><p><strong>청산</strong>은 트레이더의 증거금이 더 이상 손실을 감당할 수 없어 거래소가 레버리지 포지션을 강제로 종료하는 것입니다. 포지션은 시장가로 청산되고 트레이더는 증거금을 잃습니다. 높은 레버리지에서는 청산 가격이 진입가에 매우 가깝게 위치합니다.</p>\n<h2>롱 청산 대 숏 청산</h2><p><strong>롱 청산</strong>은 가격이 하락할 때 쓸려나가는 과도한 레버리지의 매수자들입니다. <strong>숏 청산</strong>은 가격이 상승할 때 쓸려나가는 매도자들입니다. 한쪽으로 크게 치우친 급등은 흔히 국지적 극단을 나타냅니다 — 롱 청산의 쓸림은 바닥을 표시할 수 있고, 숏 청산의 물결은 랠리를 부추길 수 있습니다.</p>\n<h2>청산 캐스케이드</h2><p>청산은 연료처럼 작용합니다. 가격이 레버리지가 가득 찬 구간에 닿으면, 강제 주문이 가격을 더 밀어붙여 더 많은 청산을 촉발합니다 — 이것이 <strong>캐스케이드</strong>입니다. 레버리지가 가장 무거운 곳을 지켜보면 과밀된 거래를 피하는 데 도움이 됩니다.</p>\n<h2>나머지와 함께 활용하라</h2><p>청산을 <a href=\"/funding/\">펀딩</a> 및 <a href=\"/open-interest/\">미결제약정</a>과 짝지어 보세요: 미결제약정의 감소는 레버리지가 쓸려나가면서 보통 캐스케이드 뒤에 따라옵니다.</p>","faq":[["청산은 무엇이 원인인가요?","가격이 포지션에 불리하게 충분히 움직여 증거금이 더 이상 손실을 감당할 수 없게 되면 포지션이 청산되며, 거래소가 자동으로 이를 종료합니다."],["롱 청산과 숏 청산 중 어느 쪽이 강세 신호인가요?","(하락 중) 롱 청산의 급등은 국지적 바닥을 표시할 수 있고, (랠리 중) 숏 청산의 급등은 위쪽 스퀴즈를 부추길 수 있습니다."]]},"what-is-open-interest":{"title":"암호화폐에서 미결제약정이란?","desc":"미결제약정 설명: 거래량과 어떻게 다른지, 미결제약정의 상승과 하락이 무엇을 신호하는지, 가격과 함께 미결제약정을 어떻게 읽는지 알아봅니다.","toolLabel":"실시간 미결제약정 트래커","body":"<h2>미결제약정 대 거래량</h2><p><strong>미결제약정(OI)</strong>은 한 코인에 대해 열려 있는 모든 무기한 선물 포지션의 총 가치입니다. 모든 거래를 세는 거래량과 달리, 미결제약정은 현재 시장에 얼마나 많은 레버리지가 <em>열려</em> 있는지를 측정합니다.</p>\n<h2>상승하는 미결제약정과 하락하는 미결제약정</h2><p>미결제약정의 상승은 새로운 포지션과 신규 레버리지가 진입하고 있다는 뜻입니다. 미결제약정의 하락은 트레이더들이 청산하고 있다는 뜻입니다. 미결제약정의 갑작스러운 하락은 보통 과도한 레버리지 포지션이 쓸려나가면서 <a href=\"/liquidations/\">청산 캐스케이드</a> 뒤에 따라옵니다.</p>\n<h2>가격과 함께 미결제약정 읽기</h2><p><strong>가격 상승 + 미결제약정 상승</strong> = 새 자금이 움직임을 뒷받침(더 강한 추세). <strong>가격 상승 + 미결제약정 하락</strong> = 신규 수요가 아니라 숏 커버링. 무거운 미결제약정 축적에 더해 한쪽으로 치우친 <a href=\"/funding/\">펀딩</a>은 과밀하고 취약한 셋업을 알립니다.</p>","faq":[["높은 미결제약정은 강세인가요 약세인가요?","그 자체만으로는 어느 쪽도 아닙니다 — 가격에 달려 있습니다. 가격 상승과 함께 미결제약정이 상승하면 새로운 매수자를, 가격 하락과 함께 미결제약정이 상승하면 새로운 매도자를 시사합니다."],["미결제약정의 하락은 무엇을 의미하나요?","미결제약정의 하락은 포지션이 종료되고 있다는 뜻으로, 흔히 청산 캐스케이드가 시장에서 레버리지를 쓸어낸 뒤에 일어납니다."]]},"long-short-ratio-explained":{"title":"암호화폐 롱/숏 비율 설명","desc":"롱/숏 비율이 트레이더 포지셔닝에 관해 무엇을 알려주는지, 과밀된 극단값을 어떻게 읽는지, 그리고 왜 역발상적으로 쓰는 것이 가장 좋은지 알아봅니다.","toolLabel":"실시간 롱/숏 비율","body":"<h2>무엇을 측정하는가</h2><p><strong>롱/숏 비율</strong>은 한 코인에 대해 트레이더 계정 가운데 몇 퍼센트가 롱에, 몇 퍼센트가 숏에 포지션을 잡고 있는지를 보여줍니다. 군중의 포지셔닝과 심리의 스냅샷입니다.</p>\n<h2>군중 읽기</h2><p>숙련된 트레이더는 흔히 극단값을 <strong>역발상적으로</strong> 읽습니다. 대부분의 계정이 이미 롱일 때는 매수세가 대체로 소진되었고 군중이 <strong>롱 스퀴즈</strong>에 노출되어 있습니다. 군중이 강하게 숏일 때는 반등이 <strong>숏 스퀴즈</strong>를 강제할 수 있습니다.</p>\n<h2>하나의 신호일 뿐, 전체 그림은 아니다</h2><p>과밀된 장부는 추세가 진행되는 동안 계속 과밀한 상태로 남아 있을 수 있습니다. 행동에 옮기기 전에 이 비율을 <a href=\"/funding/\">펀딩</a>(군중이 보유에 지불하는 비용) 및 <a href=\"/liquidations/\">청산</a>(레버리지가 쓸려나가는 곳)과 결합하세요.</p>","faq":[["좋은 롱/숏 비율은 얼마인가요?","단 하나의 좋은 값은 없습니다 — 극단값에서 가장 유용합니다. 매우 높은 롱 비중은 과밀된 롱을, 매우 높은 숏 비중은 과밀된 숏을 경고합니다."],["트레이더는 롱/숏 비율을 어떻게 활용하나요?","많은 이들이 역발상적으로 읽습니다: 과도하게 포지션이 잡힌 쪽을 페이드하고, 항상 펀딩·미결제약정·가격 움직임으로 확인합니다."]]},"what-is-liquidation-price":{"title":"암호화폐에서 청산 가격이란?","desc":"청산 가격이 무엇인지, 레버리지가 어떻게 그것을 진입가에 더 가깝게 끌어오는지, 그리고 포지션을 열기 전에 어떻게 계산하는지 알아봅니다.","toolLabel":"청산 가격 계산기","body":"<h2>청산 가격이란</h2><p><strong>청산 가격</strong>은 증거금이 더 이상 손실을 감당할 수 없어 거래소가 레버리지 포지션을 강제 종료하는 가격입니다. 이를 넘어서면 증거금을 잃습니다. 진입하기 전에 이를 아는 것이 레버리지 거래에서 가장 중요한 단 하나의 숫자입니다.</p>\n<h2>레버리지가 그것을 어떻게 움직이는가</h2><p>레버리지가 높을수록 청산 가격이 진입가에 더 가깝게 위치합니다. 5×에서 롱은 대략 20% 하락에 청산되고, 100×에서는 대략 1% 움직임에 청산됩니다. 이것이 높은 레버리지가 그토록 취약한 이유입니다 — 평범한 꼬리(wick)가 포지션을 쓸어버릴 수 있습니다.</p>\n<h2>어떻게 계산하는가</h2><p>격리 롱의 경우, 청산 ≈ 진입가 × (1 − 1/레버리지 + 유지증거금률)이며, 숏은 부호가 뒤집힙니다. 정확한 수치는 거래소의 유지증거금과 수수료에 달려 있으므로, 본인의 코인과 레버리지에 맞춰 <a href=\"/btc-liquidation-calculator/\">청산 계산기</a>로 확인하세요.</p>\n<h2>여유를 두라</h2><p>청산 가격이 노이즈 너머에 — 명백한 지지·저항과 최근의 꼬리 너머에 — 위치하고 진입가 바로 위에 놓이지 않도록 사이즈와 레버리지를 설정하세요. <a href=\"/guides/how-to-avoid-liquidation/\">청산을 피하는 법</a>도 참고하세요.</p>","faq":[["청산 가격은 어떻게 계산하나요?","대략적으로, 롱의 경우 청산 ≈ 진입가 × (1 − 1/레버리지 + 유지증거금)이며 숏은 반대입니다. 정확한 값은 거래소의 유지증거금률과 수수료에 달려 있습니다."],["레버리지가 높으면 청산 가격이 더 가까워지나요?","네. 100×에서는 청산 가격이 진입가에서 약 1%밖에 떨어져 있지 않은 반면, 5×에서는 20%에 가깝습니다 — 레버리지가 높을수록 가격이 불리하게 움직일 여지가 거의 남지 않습니다."]]},"isolated-vs-cross-margin":{"title":"격리 마진 대 교차 마진 설명","desc":"격리 마진과 교차 마진의 차이, 위험의 트레이드오프, 그리고 어떤 모드가 어떤 스타일의 트레이더에게 맞는지 알아봅니다.","toolLabel":"페이퍼 트레이드로 연습하기","body":"<h2>격리 마진</h2><p><strong>격리 마진</strong>에서는 포지션에 배정한 증거금만 위험에 노출됩니다. 청산되더라도 손실은 그 증거금으로 제한되고 나머지 잔고는 건드려지지 않습니다. 높은 레버리지 거래에서 더 안전한 기본값입니다.</p>\n<h2>교차 마진</h2><p><strong>교차 마진</strong>에서는 계정 잔고 전체가 포지션을 뒷받침합니다. 그 덕에 청산 가격은 더 멀어지지만, 단 한 번의 잘못된 거래가 한 포지션의 증거금만이 아니라 계정 전체를 비울 수 있습니다.</p>\n<h2>어느 것을 쓸까</h2><p>대부분의 트레이더는 위험이 정해진 높은 레버리지 셋업에는 <strong>격리</strong>를, 적극적으로 관리하거나 헤지하는 낮은 레버리지 포지션에는 <strong>교차</strong>를 사용합니다. 트레이드오프: 격리는 손실을 제한하고, 교차는 청산 위험을 낮추되 최대 손실을 키웁니다. 어느 쪽이든 먼저 <a href=\"/guides/what-is-liquidation-price/\">청산 가격</a>을 확인하세요.</p>","faq":[["격리 마진과 교차 마진 중 어느 쪽이 더 안전한가요?","손실을 제한하는 데는 격리가 더 안전합니다 — 배정된 증거금만 위험에 노출됩니다. 교차 마진은 청산되기는 더 어렵지만 잔고 전체를 걸게 됩니다."],["언제 교차 마진을 써야 하나요?","교차는 적극적으로 관리하거나 헤지하는 낮은 레버리지 포지션에 맞으며, 증거금을 추가로 채우지 않고도 거래가 변동성을 버텨내길 원할 때 적합합니다."]]},"how-to-calculate-position-size":{"title":"암호화폐에서 포지션 크기 계산하는 법","desc":"감이 아니라 위험으로 모든 거래의 크기를 정하세요: 계정, 손절 거리, 거래당 위험으로 포지션 크기를 산출하는 법을 알아봅니다.","toolLabel":"포지션 크기 계산기","body":"<h2>위험이 먼저, 크기는 그다음</h2><p>전문적인 사이징은 하나의 숫자에서 시작합니다: 그 거래에서 얼마를 잃을 의향이 있는가. 흔한 규칙은 <strong>거래당 계정의 1–2%를 위험에 두는 것</strong>입니다. 그러면 포지션 크기는 손절 거리에서 따라 나옵니다.</p>\n<h2>공식</h2><p>포지션 크기 = (계정 × 위험 %) ÷ (손절 거리 %). $20를 위험에 두고 손절이 2% 떨어져 있다면, 레버리지와 무관하게 $1,000의 노출을 잡습니다. 레버리지는 필요한 증거금만 정할 뿐, 위험을 정하지는 않습니다.</p>\n<h2>레버리지는 위험이 아니다</h2><p>대부분의 초보자가 놓치는 핵심이 이것입니다: 위험은 레버리지가 아니라 크기와 손절로 정해집니다. 손절이 잘 잡힌 작은 포지션에서의 10×가 과도한 크기의 포지션에서의 2×보다 훨씬 안전할 수 있습니다. <a href=\"/calculators?c=size\">포지션 크기 계산기</a>를 써서 모든 거래가 같은 금액을 위험에 두게 하고, <a href=\"/guides/what-is-liquidation-price/\">청산 가격</a>을 주시하세요.</p>","faq":[["거래당 얼마를 위험에 둬야 하나요?","널리 쓰이는 지침은 거래당 계정의 1–2%로, 연속된 손실이 계정을 날려버릴 수 없게 합니다."],["레버리지가 제 포지션 크기를 바꾸나요?","아니요 — 위험은 포지션 크기와 손절 거리로 정해집니다. 레버리지는 그 포지션을 보유하는 데 필요한 증거금만 결정합니다."]]},"what-is-leverage-in-crypto":{"title":"암호화폐 거래에서 레버리지란?","desc":"레버리지를 쉽게 설명합니다: 10×나 100×가 어떻게 작동하는지, 그것이 청산 가격에 무엇을 하는지, 그리고 계정을 날리지 않고 어떻게 쓰는지 알아봅니다.","toolLabel":"청산 계산기","body":"<h2>레버리지가 하는 일</h2><p><strong>레버리지</strong>는 증거금보다 큰 포지션을 통제하게 해줍니다. 10×에서는 $100 증거금이 $1,000의 노출을 통제하므로, 1% 움직임이 증거금 기준 10% 변동이 됩니다 — 이익과 손실이 모두 증폭됩니다.</p>\n<h2>함정: 청산</h2><p>그 이면이 바로 <a href=\"/guides/what-is-liquidation-price/\">청산 가격</a>입니다. 레버리지가 높을수록 당신을 쓸어버리는 움직임이 작아집니다 — 100×에서 대략 1%, 50×에서 2%, 10×에서 10%. 증폭된 상승 여력에는 증폭된 취약성이 따라옵니다.</p>\n<h2>현명하게 쓰기</h2><p>레버리지는 자본 효율을 위한 도구이지, 최대로 끌어올릴 숫자가 아닙니다. <a href=\"/guides/how-to-calculate-position-size/\">위험</a>으로 크기를 정하고, 청산 가격을 노이즈 너머에 두며, 펀딩 비용은 증거금이 아니라 포지션 크기에 비례해 커진다는 점을 기억하세요.</p>","faq":[["10x 레버리지는 무슨 뜻인가요?","10×는 포지션이 증거금의 열 배라는 뜻입니다: $100가 $1,000를 통제하므로 1% 가격 움직임이 증거금 기준 10% 움직임이 됩니다 — 양방향 모두에서요."],["높은 레버리지는 나쁜가요?","높은 레버리지가 본질적으로 나쁜 것은 아니지만, 청산 가격을 진입가에 매우 가깝게 놓습니다. 대부분의 계정 폭파는 레버리지 자체가 아니라 높은 레버리지에서 과도하게 크기를 잡는 데서 나옵니다."]]},"maker-vs-taker-fees":{"title":"메이커 수수료 대 테이커 수수료 설명","desc":"메이커 수수료와 테이커 수수료가 무엇인지, 왜 테이커가 더 많이 내는지, 그리고 그 차이가 활발한 선물 트레이더에게 어떻게 쌓이는지 알아봅니다.","toolLabel":"거래소 수수료 비교","body":"<h2>차이</h2><p><strong>메이커</strong> 주문은 장부에 유동성을 더합니다 — 호가에 걸려 체결을 기다리는 지정가 주문입니다. <strong>테이커</strong> 주문은 유동성을 제거합니다 — 기존 호가를 가져가는 시장가 주문, 또는 즉시 체결되는 지정가 주문입니다. 거래소는 테이커에게 더 많은 수수료를 부과하는데, 메이커가 모두가 거래할 유동성을 제공하기 때문입니다.</p>\n<h2>일반적인 요율</h2><p>주요 USDT 무기한에서 메이커 수수료는 약 0.02%, 테이커 수수료는 0.04–0.06% 수준입니다. 사소해 보이지만, 하루에 수십 번 왕복 거래하는 데이 트레이더는 이를 거듭거듭 지불합니다 — 게다가 테이커는 양쪽 모두에서 지불합니다.</p>\n<h2>덜 내는 법</h2><p>가능하면 호가에 걸리는 <strong>지정가 주문</strong>을 사용해 메이커 수수료 자격을 얻고, 할인을 위해 거래소 토큰을 보유하며, 거래량이 늘어남에 따라 VIP 등급을 올리세요. 수수료가 우선이라면, 먼저 <a href=\"/lowest-fee-crypto-exchange/\">테이커 수수료로 거래소를 비교</a>하세요.</p>","faq":[["왜 테이커가 메이커보다 더 많이 내나요?","테이커는 기존 주문을 체결해 유동성을 제거하는 반면, 메이커는 장부에 주문을 걸어 유동성을 더합니다. 거래소는 시장을 유동적으로 유지하는 메이커에게 더 낮은 수수료로 보상합니다."],["메이커 수수료는 어떻게 내나요?","즉시 체결되는 시장가 주문 대신 장부에 걸리는 지정가 주문을 넣으세요. 주문이 체결되길 기다리면 더 낮은 메이커 수수료 자격을 얻습니다."]]},"how-to-avoid-liquidation":{"title":"암호화폐 거래에서 청산을 피하는 법","desc":"레버리지 포지션이 청산되지 않도록 지키는 실용적인 방법들 — 사이징과 손절부터 마진 모드와 펀딩까지.","toolLabel":"청산 가격 확인하기","body":"<h2>진입하기 전에 가격을 알라</h2><p>먼저 <a href=\"/guides/what-is-liquidation-price/\">청산 가격</a>을 계산하고, 그것이 진입가 바로 옆이 아니라 최근의 꼬리와 명백한 지지·저항 너머에 위치하도록 하세요.</p>\n<h2>쓸 수 있는 것보다 낮은 레버리지를 써라</h2><p>거래소가 125×를 제공한다고 해서 그것을 써야 하는 것은 아닙니다. 낮은 레버리지는 청산 가격을 진입가에서 더 멀리 밀어내고, 시간을 두고 옳을 여유를 사줍니다.</p>\n<h2>항상 손절을 설정하라</h2><p>손절은 거래소의 청산 엔진이 더 나쁜 가격에 처리하기 전에, <em>당신</em>이 고른 가격에서 당신을 종료시킵니다.</p>\n<h2>위험으로 크기를 정하라</h2><p><a href=\"/guides/how-to-calculate-position-size/\">포지션 크기 계산기</a>를 써서 거래당 1–2%의 고정된 위험을 두면, 단 한 번의 거래도 실질적인 타격을 줄 수 없습니다.</p>\n<h2>격리 마진을 선호하라</h2><p><a href=\"/guides/isolated-vs-cross-margin/\">격리 마진</a>은 손실을 한 포지션으로 제한합니다. 패닉이 아니라 의도적으로 증거금을 추가하세요.</p>\n<h2>펀딩을 유의하라</h2><p>높은 레버리지에서는 가격이 횡보할 때조차 <a href=\"/funding/\">펀딩</a>이 포지션을 조용히 갉아먹습니다 — 긴 보유에 이를 반영하세요.</p>","faq":[["청산을 피하는 가장 좋은 방법은 무엇인가요?","낮은 레버리지를 쓰고, 항상 손절을 설정하며, 고정된 위험 비율로 크기를 정하고, 청산 가격을 최근 변동성 너머에 충분히 두세요."],["손절이 청산을 막아주나요?","손절은 거래소 청산이 촉발되기 전에 당신이 고른 가격에서 포지션을 종료하므로, 실제로 대부분의 청산을 막아줍니다 — 빠른 시장에서 체결된다는 전제하에요."]]},"perpetual-vs-futures":{"title":"무기한 대 선물: 무엇이 다른가?","desc":"무기한 스왑 대 만기 선물: 만기, 펀딩, 그리고 왜 무기한이 암호화폐 레버리지 거래를 지배하는지 알아봅니다.","toolLabel":"실시간 펀딩 스캐너","body":"<h2>만기 선물</h2><p>전통적인 <strong>선물 계약</strong>에는 만기일이 있습니다. 그날 현물 가격으로 정산되므로, 만기가 다가올수록 계약 가격이 현물에 수렴합니다. 정해진 기간 동안 거래하고 나면 사라집니다.</p>\n<h2>무기한 스왑</h2><p><strong>무기한</strong>(\"perp\")은 결코 만기되지 않습니다. 만기 없이 가격을 현물에 묶어두기 위해, 거래소는 롱과 숏 사이의 주기적인 <a href=\"/funding/\">펀딩 결제</a>를 사용합니다. 그 메커니즘이 정산을 대신합니다.</p>\n<h2>왜 무기한이 암호화폐를 지배하는가</h2><p>무기한은 롤오버 없이 레버리지를 무기한으로 보유하게 해주며, 그래서 암호화폐 파생상품 거래량의 절대다수를 차지합니다. 트레이드오프는 펀딩입니다: 높은 레버리지에서는 가격이 횡보할 때조차 포지션을 조용히 갉아먹을 수 있습니다.</p>","faq":[["무기한 계약은 만기가 있나요?","아니요. 무기한 스왑은 결코 만기되지 않습니다 — 주기적인 펀딩 결제가 정산일 대신 가격을 현물에 묶어둡니다."],["선물과 무기한의 차이는 무엇인가요?","만기 선물은 만기일에 정산되는 반면, 무기한은 무기한으로 운영되며 펀딩 결제를 통해 현물 근처에 머뭅니다. 암호화폐 거래는 무기한이 지배합니다."]]},"long-vs-short-crypto":{"title":"암호화폐에서 롱 대 숏 설명","desc":"레버리지로 롱이나 숏을 잡는 것이 무엇을 뜻하는지, 각 방향이 어떻게 돈을 벌거나 잃는지, 그리고 청산이 어떻게 다른지 알아봅니다.","toolLabel":"롱 & 숏 연습","body":"<h2>롱 잡기</h2><p><strong>롱</strong>은 가격이 오를 것에 베팅합니다. 가격이 오르면 이익을 보고 내리면 손실을 봅니다. 롱은 가격이 충분히 하락해 증거금이 더 이상 손실을 감당할 수 없을 때 청산됩니다.</p>\n<h2>숏 잡기</h2><p><strong>숏</strong>은 가격이 내릴 것에 베팅합니다. 가격이 내리면 이익을 보고 오르면 손실을 봅니다 — 숏은 하락 추세에서 돈을 벌게 해줍니다. 숏은 가격이 당신에게 불리하게 충분히 상승할 때 청산됩니다.</p>\n<h2>위험은 대칭이 아니다</h2><p>롱은 0까지만 떨어질 수 있지만, 숏은 가격이 계속 오르면 이론적으로 무한한 손실을 봅니다 — 그래서 숏 스퀴즈가 격렬할 수 있습니다. 어느 쪽이든 레버리지가 <a href=\"/guides/what-is-liquidation-price/\">청산 가격</a>이 진입가에 얼마나 가까운지를 정합니다. <a href=\"/paper-trade\">페이퍼 트레이드</a>에서 양쪽을 위험 없이 테스트하세요.</p>","faq":[["암호화폐에서 숏을 잡는다는 게 무슨 뜻인가요?","숏은 가격이 내릴 것에 베팅하는 것입니다: 내리면 이익을 보고 오르면 손실을 보며, 이는 하락 추세에서 돈을 벌게 해줍니다."],["숏이 롱보다 더 위험한가요?","숏은 가격이 계속 오르면 이론적으로 무한한 손실을 보는 반면 롱은 0까지만 떨어질 수 있습니다 — 그래서 헤지되지 않은 숏이 더 위험할 수 있고, 숏 스퀴즈는 날카로울 수 있습니다."]]},"what-is-mark-price":{"title":"암호화폐 선물에서 마크 가격이란?","desc":"거래소가 왜 마지막 가격이 아닌 마크 가격으로 청산하는지, 그리고 그것이 얕은 호가창에 의한 꼬리 청산으로부터 당신을 어떻게 보호하는지 알아봅니다.","toolLabel":"청산 계산기","body":"<h2>마지막 가격 대 마크 가격</h2><p><strong>마지막 가격</strong>은 단순히 그 거래소에서의 가장 최근 거래입니다. <strong>마크 가격</strong>은 더 공정한 기준 — 보통 여러 현물 시장의 지수에 펀딩 베이시스를 더해 구성됩니다 — 으로, 단일 거래소의 급등을 평탄화합니다.</p>\n<h2>왜 중요한가</h2><p>거래소는 당신의 미실현 손익과 <a href=\"/guides/what-is-liquidation-price/\">청산</a>을 마지막 가격이 아니라 <strong>마크 가격</strong>으로 계산합니다. 이는 진정한 시장을 반영하지 않는, 얕은 장부에서의 짧은 꼬리에 의해 청산되는 것으로부터 당신을 보호합니다.</p>\n<h2>무엇을 지켜볼까</h2><p>빠른 시장에서는 마지막 가격이 마크 가격을 한참 넘어 급등할 수 있습니다. 당신의 포지션은 마크 가격으로 판단되므로, 청산 수준에 가까울 때는 깜빡이는 마지막 가격이 아니라 그것을 확인하세요.</p>","faq":[["거래소는 왜 청산에 마크 가격을 쓰나요?","마크 가격은 지수 기반의 공정 가치로 단일 거래소의 급등을 평탄화하므로, 얕은 호가창에서의 짧은 꼬리가 건강한 포지션을 잘못 청산시킬 수 없습니다."],["마크 가격은 마지막 가격과 같은가요?","아니요. 마지막 가격은 그 거래소에서의 가장 최근 거래이고, 마크 가격은 손익과 청산을 계산하는 데 쓰이는 더 공정한 지수 기반 가치입니다."]]}},"ar":{"how-to-read-funding-rates":{"title":"كيفية قراءة معدلات التمويل في الكريبتو","desc":"دليل مبسّط لمعدلات التمويل في العقود الدائمة: ماذا يعني التمويل الموجب والسالب، كيف ترصد ازدحام مراكز الشراء والبيع، وكيف تستفيد من حدود التمويل القصوى.","toolLabel":"ماسح التمويل المباشر","body":"<h2>ما هو معدل التمويل</h2><p>في العقد الدائم لا يوجد تاريخ انتهاء، لذلك تستخدم المنصات دفعة دورية صغيرة — <strong>معدل التمويل</strong> — لإبقاء سعر العقد الدائم مرتبطاً بالسعر الفوري. يُتبادل عادةً كل 8 ساعات بين مراكز الشراء ومراكز البيع.</p>\n<h2>التمويل الموجب مقابل السالب</h2><p><strong>التمويل الموجب</strong> يعني أن العقد الدائم يُتداول فوق السعر الفوري، لذا <em>يدفع المشترون للبائعين</em> — السوق يميل نحو الشراء. <strong>التمويل السالب</strong> يعني أن العقد الدائم يُتداول دون السعر الفوري، لذا <em>يدفع البائعون للمشترين</em> — السوق يميل نحو البيع.</p>\n<h2>قراءة الحدود القصوى</h2><p>عندما يكون التمويل موجباً جداً، تكون مراكز الشراء مزدحمة وتدفع علاوة للاحتفاظ بها؛ وأي توقف في السعر قد يؤدي إلى <strong>انضغاط مراكز الشراء</strong>. وعندما يكون التمويل سالباً بشدة، تكون مراكز البيع مزدحمة وقد يفرض الارتداد <strong>انضغاط مراكز البيع</strong>. يكون التمويل أقوى كإشارة عند دمجه مع <a href=\"/open-interest/\">المراكز المفتوحة</a> و<a href=\"/long-short/\">توزيع الشراء/البيع</a>.</p>\n<h2>انتبه للتكلفة</h2><p>عند الرافعة المالية العالية تتراكم تكلفة التمويل بسرعة وقد تستنزف المركز بهدوء حتى عندما يكون السعر ثابتاً. احسبها دائماً ضمن مدة احتفاظك بالمركز.</p>","faq":[["ماذا يعني معدل التمويل المرتفع؟","التمويل الموجب المرتفع يعني أن السوق ممتلئ بمراكز الشراء وأن المشترين يدفعون للاحتفاظ بمراكزهم — علامة على ازدحام مراكز الشراء قد تشعل انضغاط مراكز البيع عند أي تراجع."],["هل التمويل السالب إشارة صعودية؟","التمويل السالب يعني أن مراكز البيع مزدحمة وأنها تدفع للمشترين. كثيراً ما يُقرأ على نحو معاكس باعتباره تمهيداً لانضغاط صعودي، لكنه إشارة واحدة بين التمويل والمراكز المفتوحة والسعر."]]},"how-to-read-liquidations":{"title":"كيفية قراءة التصفيات في الكريبتو","desc":"افهم التصفيات في الكريبتو: ما هي، الفرق بين تصفية مراكز الشراء والبيع، وكيف تقود سلاسل التصفيات التقلبات.","toolLabel":"متتبع التصفيات المباشر","body":"<h2>ما هي التصفية</h2><p><strong>التصفية</strong> هي عندما تغلق المنصة مركزاً برافعة مالية قسراً لأن هامش المتداول لم يعد قادراً على تغطية الخسارة. يُغلق المركز بسعر السوق ويخسر المتداول هامشه. عند الرافعة المالية العالية يكون سعر التصفية قريباً جداً من سعر الدخول.</p>\n<h2>تصفية مراكز الشراء مقابل البيع</h2><p><strong>تصفيات مراكز الشراء</strong> هي مشترون مفرطون في الرافعة يُمحَون عند هبوط السعر. <strong>تصفيات مراكز البيع</strong> هي بائعون يُمحَون عند ارتفاع السعر. غالباً ما تشير الموجة الكبيرة أحادية الجانب إلى حد قصوى محلي — قد تشير موجة من تصفيات مراكز الشراء إلى قاع، وقد تشعل موجة من تصفيات مراكز البيع صعوداً.</p>\n<h2>سلاسل التصفيات</h2><p>تعمل التصفيات كالوقود. عندما يصل السعر إلى منطقة مكتظة بالرافعة المالية، تدفع الأوامر القسرية السعر أبعد، ما يطلق المزيد من التصفيات — وهي <strong>سلسلة</strong>. مراقبة المناطق التي تتركز فيها الرافعة المالية تساعدك على تجنّب الصفقة المزدحمة.</p>\n<h2>استخدمها مع البقية</h2><p>اقرن التصفيات مع <a href=\"/funding/\">التمويل</a> و<a href=\"/open-interest/\">المراكز المفتوحة</a>: عادةً ما يتبع هبوطُ المراكز المفتوحة السلسلةَ مع استنزاف الرافعة المالية.</p>","faq":[["ما الذي يسبب التصفية؟","يُصفّى المركز عندما يتحرك السعر ضده بما يكفي بحيث لا يعود الهامش قادراً على تغطية الخسارة، فتغلقه المنصة تلقائياً."],["هل تصفيات مراكز الشراء أم البيع هي الصعودية؟","قد تشير موجة من تصفيات مراكز الشراء (أثناء هبوط) إلى قاع محلي؛ وقد تشعل موجة من تصفيات مراكز البيع (أثناء صعود) انضغاطاً صعودياً."]]},"what-is-open-interest":{"title":"ما هي المراكز المفتوحة في الكريبتو؟","desc":"شرح المراكز المفتوحة: كيف تختلف عن الحجم، ماذا يشير إليه ارتفاعها وانخفاضها، وكيف تقرؤها مع السعر.","toolLabel":"متتبع المراكز المفتوحة المباشر","body":"<h2>المراكز المفتوحة مقابل الحجم</h2><p><strong>المراكز المفتوحة</strong> هي القيمة الإجمالية لكل المراكز المفتوحة في العقود الدائمة على عملة ما. وخلافاً للحجم — الذي يحسب كل صفقة — تقيس المراكز المفتوحة مقدار الرافعة المالية <em>المفتوحة</em> حالياً في السوق.</p>\n<h2>ارتفاع وانخفاض المراكز المفتوحة</h2><p>ارتفاع المراكز المفتوحة يعني دخول مراكز جديدة ورافعة مالية طازجة. انخفاضها يعني أن المتداولين يغلقون مراكزهم. عادةً ما يتبع الهبوط المفاجئ في المراكز المفتوحة <a href=\"/liquidations/\">سلسلة تصفيات</a> مع استنزاف المراكز المفرطة في الرافعة.</p>\n<h2>قراءة المراكز المفتوحة مع السعر</h2><p><strong>ارتفاع السعر + ارتفاع المراكز المفتوحة</strong> = أموال جديدة تدعم الحركة (اتجاه أقوى). <strong>ارتفاع السعر + انخفاض المراكز المفتوحة</strong> = تغطية مراكز بيع لا طلب جديد. تراكم كبير في المراكز المفتوحة مع <a href=\"/funding/\">تمويل</a> أحادي الجانب يشير إلى تمهيد مزدحم وهشّ.</p>","faq":[["هل المراكز المفتوحة المرتفعة صعودية أم هبوطية؟","لا هذا ولا ذاك بمفردها — يعتمد على السعر. ارتفاع المراكز المفتوحة مع ارتفاع السعر يوحي بمشترين جدد؛ وارتفاعها مع هبوط السعر يوحي ببائعين جدد."],["ماذا يعني انخفاض المراكز المفتوحة؟","انخفاض المراكز المفتوحة يعني أن المراكز تُغلق، غالباً بعد أن تستنزف سلسلة تصفيات الرافعة المالية من السوق."]]},"long-short-ratio-explained":{"title":"شرح نسبة الشراء/البيع في الكريبتو","desc":"ما الذي تخبرك به نسبة الشراء/البيع عن توزيع مراكز المتداولين، كيف تقرأ الحدود القصوى المزدحمة، ولماذا يُفضّل استخدامها على نحو معاكس.","toolLabel":"نسبة الشراء/البيع المباشرة","body":"<h2>ما الذي تقيسه</h2><p>تُظهر <strong>نسبة الشراء/البيع</strong> النسبة المئوية لحسابات المتداولين الموزّعة على الشراء مقابل البيع على عملة ما. إنها لقطة لتوزيع الحشد ومعنوياته.</p>\n<h2>قراءة الحشد</h2><p>كثيراً ما يقرأ المتداولون المحنّكون الحدود القصوى <strong>على نحو معاكس</strong>. عندما تكون معظم الحسابات في الشراء بالفعل، يكون الشراء قد استُنفد إلى حد كبير ويصبح الحشد معرّضاً لـ<strong>انضغاط مراكز الشراء</strong>. وعندما يكون الحشد في البيع بكثافة، قد يفرض الارتداد <strong>انضغاط مراكز البيع</strong>.</p>\n<h2>إشارة واحدة لا الصورة كاملة</h2><p>قد يبقى السوق المزدحم مزدحماً بينما يستمر الاتجاه. اجمع النسبة مع <a href=\"/funding/\">التمويل</a> (ما يدفعه الحشد للاحتفاظ) و<a href=\"/liquidations/\">التصفيات</a> (أين تُستنزف الرافعة المالية) قبل أن تتصرف.</p>","faq":[["ما هي نسبة الشراء/البيع الجيدة؟","لا توجد قيمة جيدة واحدة — تكون أكثر فائدة عند الحدود القصوى. حصة شراء عالية جداً تحذّر من ازدحام مراكز الشراء؛ وحصة بيع عالية جداً تحذّر من ازدحام مراكز البيع."],["كيف يستخدم المتداولون نسبة الشراء/البيع؟","كثيرون يقرؤونها على نحو معاكس: يتلاشى الجانب المفرط في التوزيع، مع التأكيد دائماً عبر التمويل والمراكز المفتوحة وحركة السعر."]]},"what-is-liquidation-price":{"title":"ما هو سعر التصفية في الكريبتو؟","desc":"ما هو سعر التصفية، كيف تقرّبه الرافعة المالية من سعر دخولك، وكيف تحسبه قبل فتح مركز.","toolLabel":"حاسبة سعر التصفية","body":"<h2>ما هو</h2><p><strong>سعر التصفية</strong> هو السعر الذي تغلق عنده المنصة مركزك ذا الرافعة قسراً لأن هامشك لم يعد قادراً على تغطية الخسارة. إذا تجاوزته خسرت هامشك. معرفته قبل الدخول هي أهم رقم منفرد في التداول بالرافعة المالية.</p>\n<h2>كيف تحرّكه الرافعة المالية</h2><p>كلما زادت رافعتك المالية، اقترب سعر التصفية من سعر دخولك. عند 5× يُصفّى مركز الشراء عند هبوط بنحو 20%؛ وعند 100× يكون عند حركة بنحو 1%. لهذا تكون الرافعة العالية هشّة جداً — قد يمحو ذيلٌ عادي مركزاً.</p>\n<h2>كيف يُحسب</h2><p>لمركز شراء معزول، التصفية ≈ الدخول × (1 − 1/الرافعة + معدل هامش الصيانة)؛ ومراكز البيع تعكس الإشارة. يعتمد الرقم الدقيق على هامش الصيانة والرسوم لدى المنصة، لذا تحقق منه باستخدام <a href=\"/btc-liquidation-calculator/\">حاسبة التصفية</a> لعملتك ورافعتك.</p>\n<h2>اترك له مجالاً</h2><p>اضبط حجمك ورافعتك بحيث يقع سعر التصفية خارج التشويش — بعد مستويات الدعم والمقاومة الواضحة والذيول الأخيرة — لا فوق سعر دخولك مباشرةً. انظر أيضاً <a href=\"/guides/how-to-avoid-liquidation/\">كيفية تجنّب التصفية</a>.</p>","faq":[["كيف يُحسب سعر التصفية؟","تقريباً، التصفية ≈ الدخول × (1 − 1/الرافعة + هامش الصيانة) لمركز شراء، مع عكس ذلك لمراكز البيع. تعتمد القيمة الدقيقة على معدل هامش الصيانة ورسوم المنصة."],["هل تعني الرافعة المالية الأعلى سعر تصفية أقرب؟","نعم. عند 100× يكون سعر التصفية على بعد نحو 1% فقط من الدخول، بينما عند 5× يقترب من 20% — الرافعة الأعلى لا تترك تقريباً أي مجال لتحرّك السعر ضدك."]]},"isolated-vs-cross-margin":{"title":"شرح الهامش المعزول مقابل الهامش المتقاطع","desc":"الفرق بين الهامش المعزول والمتقاطع، المفاضلة في المخاطرة، وأي وضع يناسب أي أسلوب تداول.","toolLabel":"تدرّب على التداول التجريبي","body":"<h2>الهامش المعزول</h2><p>في <strong>الهامش المعزول</strong>، يكون الهامش الذي تخصّصه للمركز فقط هو المعرّض للخطر. إذا صُفّي، تُحَدّ الخسارة عند ذلك الهامش ويبقى باقي رصيدك سليماً. إنه الخيار الافتراضي الأكثر أماناً للصفقات ذات الرافعة العالية.</p>\n<h2>الهامش المتقاطع</h2><p>في <strong>الهامش المتقاطع</strong>، يدعم رصيد حسابك كاملاً المركز. وهذا يُبعد سعر التصفية أكثر، لكن صفقة سيئة واحدة قد تستنزف الحساب بأكمله، لا هامش مركز واحد فقط.</p>\n<h2>أيّهما تستخدم</h2><p>يستخدم معظم المتداولين <strong>المعزول</strong> للصفقات ذات المخاطرة المحدّدة والرافعة العالية، و<strong>المتقاطع</strong> للمراكز ذات الرافعة المنخفضة التي يديرونها أو يحوّطونها بنشاط. المفاضلة: المعزول يحدّ خسارتك؛ والمتقاطع يخفض مخاطر التصفية لكنه يرفع أقصى خسارة لك. في كلتا الحالتين، تحقق من <a href=\"/guides/what-is-liquidation-price/\">سعر التصفية</a> أولاً.</p>","faq":[["هل الهامش المعزول أم المتقاطع أكثر أماناً؟","المعزول أكثر أماناً لحدّ الخسائر — الهامش المخصّص فقط هو المعرّض للخطر. الهامش المتقاطع أصعب تصفيةً لكنه يضع رصيدك كاملاً على المحك."],["متى ينبغي أن أستخدم الهامش المتقاطع؟","يناسب المتقاطع المراكز ذات الرافعة المنخفضة التي تديرها أو تحوّطها بنشاط، حيث تريد للصفقة أن تنجو من التقلبات دون إضافة هامش."]]},"how-to-calculate-position-size":{"title":"كيفية حساب حجم المركز في الكريبتو","desc":"حدّد حجم كل صفقة بناءً على المخاطرة لا الحدس: كيف تحسب حجم المركز من حسابك ومسافة وقف الخسارة والمخاطرة لكل صفقة.","toolLabel":"حاسبة حجم المركز","body":"<h2>المخاطرة أولاً، الحجم ثانياً</h2><p>يبدأ التحجيم الاحترافي من رقم واحد: كم أنت مستعد لخسارته في الصفقة. القاعدة الشائعة هي المخاطرة بـ<strong>1–2% من حسابك لكل صفقة</strong>. ومن ثم يتبع حجم مركزك مسافة وقف الخسارة لديك.</p>\n<h2>المعادلة</h2><p>حجم المركز = (الحساب × نسبة المخاطرة) ÷ (نسبة مسافة وقف الخسارة). إذا خاطرت بـ$20 وكان وقف الخسارة على بعد 2%، فإنك تأخذ تعرّضاً قدره $1,000 — بصرف النظر عن الرافعة المالية. الرافعة تحدّد الهامش المطلوب فقط، لا مخاطرتك.</p>\n<h2>الرافعة المالية ليست مخاطرة</h2><p>هذه هي النقطة التي يفوتها معظم المبتدئين: تتحدّد مخاطرتك بالحجم ووقف الخسارة، لا بالرافعة المالية. قد يكون 10× على مركز صغير محكم الوقف أكثر أماناً بكثير من 2× على مركز مفرط الحجم. استخدم <a href=\"/calculators?c=size\">حاسبة حجم المركز</a> بحيث تخاطر كل صفقة بالمقدار نفسه، وراقب <a href=\"/guides/what-is-liquidation-price/\">سعر التصفية</a>.</p>","faq":[["كم ينبغي أن أخاطر لكل صفقة؟","إرشاد شائع الاستخدام هو 1–2% من حسابك لكل صفقة، بحيث لا تستطيع سلسلة من الخسائر تفجير الحساب."],["هل تغيّر الرافعة المالية حجم مركزي؟","لا — تتحدّد مخاطرتك بحجم المركز ومسافة وقف الخسارة. الرافعة تحدّد فقط الهامش اللازم للاحتفاظ بذلك المركز."]]},"what-is-leverage-in-crypto":{"title":"ما هي الرافعة المالية في تداول الكريبتو؟","desc":"شرح مبسّط للرافعة المالية: كيف تعمل 10× أو 100×، ماذا تفعل بسعر تصفيتك، وكيف تستخدمها دون أن تتفجّر.","toolLabel":"حاسبة التصفية","body":"<h2>ماذا تفعل الرافعة المالية</h2><p>تتيح لك <strong>الرافعة المالية</strong> التحكم في مركز أكبر من هامشك. عند 10× يتحكم هامش قدره $100 في تعرّض قدره $1,000، فتصبح حركة بنسبة 1% تأرجحاً بنسبة 10% على هامشك — تتضخّم الأرباح والخسائر معاً.</p>\n<h2>المأزق: التصفية</h2><p>الوجه الآخر هو <a href=\"/guides/what-is-liquidation-price/\">سعر تصفيتك</a>. كلما زادت الرافعة، صغرت الحركة التي تمحوك — نحو 1% عند 100×، و2% عند 50×، و10% عند 10×. الجانب الصاعد المتضخّم يأتي بهشاشة متضخّمة.</p>\n<h2>استخدامها بحكمة</h2><p>الرافعة المالية أداة لكفاءة رأس المال، لا رقماً تستنفده إلى أقصاه. حجّم حسب <a href=\"/guides/how-to-calculate-position-size/\">المخاطرة</a>، وأبقِ سعر التصفية خارج التشويش، وتذكّر أن تكاليف التمويل تتناسب مع حجم المركز لا الهامش.</p>","faq":[["ماذا تعني الرافعة المالية 10x؟","10× تعني أن مركزك يساوي عشرة أضعاف هامشك: $100 يتحكم في $1,000، فتساوي حركة سعرية بنسبة 1% حركة بنسبة 10% على هامشك — في كلا الاتجاهين."],["هل الرافعة المالية العالية سيئة؟","الرافعة العالية ليست سيئة بطبيعتها، لكنها تضع سعر تصفيتك قريباً جداً من الدخول. معظم حالات التفجّر تأتي من فرط التحجيم عند الرافعة العالية، لا من الرافعة نفسها."]]},"maker-vs-taker-fees":{"title":"شرح رسوم الصانع مقابل الآخذ","desc":"ما هي رسوم الصانع والآخذ، لماذا يدفع الآخذ أكثر، وكيف يتراكم الفرق على المتداولين النشطين في العقود.","toolLabel":"قارن رسوم المنصات","body":"<h2>الفرق</h2><p>أمر <strong>الصانع</strong> يضيف سيولة إلى دفتر الأوامر — وهو أمر محدّد يستقر وينتظر التنفيذ. أمر <strong>الآخذ</strong> يزيل سيولة — وهو أمر سوقي، أو أمر محدّد يُنفَّذ فوراً، يأخذ عرضاً قائماً. تفرض المنصات رسوماً أعلى على الآخذين لأن الصانعين يوفّرون السيولة التي يتداول الجميع مقابلها.</p>\n<h2>المعدلات النموذجية</h2><p>على عقود USDT الدائمة الكبرى، تبلغ رسوم الصانع نحو 0.02% ورسوم الآخذ 0.04–0.06%. تبدو ضئيلة، لكن متداول اليوم الذي ينفّذ عشرات الجولات يدفعها مراراً وتكراراً — والآخذون يدفعونها على الجانبين.</p>\n<h2>كيف تدفع أقل</h2><p>استخدم <strong>الأوامر المحدّدة</strong> المستقرة لتأهّل لرسوم الصانع حيثما أمكن، واحتفظ برمز المنصة للحصول على خصم، وتسلّق مستويات VIP مع نمو حجمك. إذا كانت الرسوم أولويتك، <a href=\"/lowest-fee-crypto-exchange/\">قارن المنصات حسب رسوم الآخذ</a> أولاً.</p>","faq":[["لماذا يدفع الآخذون أكثر من الصانعين؟","يزيل الآخذون السيولة بتنفيذ الأوامر القائمة، بينما يضيف الصانعون السيولة بترك أوامرهم على الدفتر. تكافئ المنصات الصانعين برسوم أقل لأنهم يبقون السوق سائلاً."],["كيف أدفع رسوم الصانع؟","ضع أوامر محدّدة تستقر على الدفتر بدلاً من الأوامر السوقية التي تُنفَّذ فوراً. إذا انتظر أمرك ليُطابَق، فإنه يتأهّل لرسوم الصانع الأقل."]]},"how-to-avoid-liquidation":{"title":"كيفية تجنّب التصفية في تداول الكريبتو","desc":"طرق عملية لمنع تصفية مركز ذي رافعة مالية — من التحجيم ووقف الخسارة إلى وضع الهامش والتمويل.","toolLabel":"تحقق من سعر تصفيتك","body":"<h2>اعرف السعر قبل الدخول</h2><p>احسب <a href=\"/guides/what-is-liquidation-price/\">سعر تصفيتك</a> أولاً وتأكد من أنه يقع بعد الذيول الأخيرة ومستويات الدعم والمقاومة الواضحة — لا بجوار سعر دخولك مباشرةً.</p>\n<h2>استخدم رافعة أقل مما تستطيع</h2><p>مجرد أن منصةً تعرض 125× لا يعني أن عليك استخدامها. الرافعة الأقل تبعد سعر التصفية عن الدخول وتمنحك مجالاً لتكون على صواب مع الوقت.</p>\n<h2>اضبط وقف الخسارة دائماً</h2><p>وقف الخسارة يغلق مركزك عند سعر تختاره <em>أنت</em>، قبل أن يفعل ذلك محرّك تصفية المنصة نيابةً عنك بسعر أسوأ.</p>\n<h2>حجّم حسب المخاطرة</h2><p>خاطر بنسبة ثابتة 1–2% لكل صفقة باستخدام <a href=\"/guides/how-to-calculate-position-size/\">حاسبة حجم المركز</a>، بحيث لا تستطيع أي صفقة منفردة إحداث ضرر حقيقي.</p>\n<h2>فضّل الهامش المعزول</h2><p><a href=\"/guides/isolated-vs-cross-margin/\">الهامش المعزول</a> يحدّ الخسارة عند مركز واحد. أضف الهامش بتعمّد، لا في حالة ذعر.</p>\n<h2>انتبه للتمويل</h2><p>عند الرافعة العالية، يستنزف <a href=\"/funding/\">التمويل</a> المركز بهدوء حتى عندما يكون السعر ثابتاً — احسبه ضمن فترات الاحتفاظ الطويلة.</p>","faq":[["ما أفضل طريقة لتجنّب التصفية؟","استخدم رافعة أقل، واضبط وقف الخسارة دائماً، وحجّم حسب نسبة مخاطرة ثابتة، وأبقِ سعر تصفيتك بعيداً جداً عن التقلبات الأخيرة."],["هل يمنع وقف الخسارة التصفية؟","يغلق وقف الخسارة مركزك عند السعر الذي تختاره قبل أن تنطلق تصفية المنصة، لذا فإنه عملياً يمنع معظم التصفيات — شريطة أن يُنفَّذ في الأسواق السريعة."]]},"perpetual-vs-futures":{"title":"العقود الدائمة مقابل الآجلة: ما الفرق؟","desc":"المبادلات الدائمة مقابل العقود الآجلة المؤرَّخة: تاريخ الانتهاء، التمويل، ولماذا تهيمن العقود الدائمة على التداول بالرافعة في الكريبتو.","toolLabel":"ماسح التمويل المباشر","body":"<h2>العقود الآجلة المؤرَّخة</h2><p>للعقد <strong>الآجل</strong> التقليدي تاريخ انتهاء. في ذلك التاريخ يُسوّى إلى السعر الفوري، فيتقارب سعر العقد مع السعر الفوري كلما اقترب الانتهاء. تتداوله لمدة محدّدة، ثم يزول.</p>\n<h2>المبادلات الدائمة</h2><p>العقد <strong>الدائم</strong> لا ينتهي أبداً. وللإبقاء على سعره مرتبطاً بالسعر الفوري دون تاريخ انتهاء، تستخدم المنصات <a href=\"/funding/\">دفعة تمويل</a> دورية بين مراكز الشراء ومراكز البيع. تحلّ هذه الآلية محلّ التسوية.</p>\n<h2>لماذا تهيمن العقود الدائمة على الكريبتو</h2><p>تتيح العقود الدائمة للمتداولين الاحتفاظ بالرافعة المالية إلى أجل غير مسمى دون تجديد، ولهذا تشكّل الغالبية العظمى من حجم مشتقات الكريبتو. المفاضلة هي التمويل: عند الرافعة العالية قد يستنزف المركز بهدوء حتى عندما يكون السعر ثابتاً.</p>","faq":[["هل تنتهي العقود الدائمة؟","لا. لا تنتهي المبادلات الدائمة أبداً — تُبقي دفعة تمويل دورية سعرها مرتبطاً بالسعر الفوري بدلاً من تاريخ تسوية."],["ما الفرق بين العقود الآجلة والدائمة؟","تُسوّى العقود الآجلة المؤرَّخة في تاريخ انتهاء، بينما تستمر العقود الدائمة إلى أجل غير مسمى وتستخدم دفعات التمويل للبقاء قرب السعر الفوري. يهيمن على تداول الكريبتو العقود الدائمة."]]},"long-vs-short-crypto":{"title":"شرح الشراء مقابل البيع في الكريبتو","desc":"ما الذي يعنيه الشراء أو البيع بالرافعة المالية، كيف يربح كل جانب أو يخسر، وكيف تختلف التصفية.","toolLabel":"تدرّب على الشراء والبيع","body":"<h2>الشراء (لونغ)</h2><p>مركز <strong>الشراء</strong> يراهن على أن السعر سيرتفع. تربح مع صعود السعر وتخسر مع هبوطه. يُصفّى مركز الشراء عندما يهبط السعر بما يكفي بحيث لا يعود هامشك قادراً على تغطية الخسارة.</p>\n<h2>البيع (شورت)</h2><p>مركز <strong>البيع</strong> يراهن على أن السعر سيهبط. تربح مع هبوط السعر وتخسر مع ارتفاعه — يتيح لك البيع جني المال في الاتجاه الهابط. يُصفّى مركز البيع عندما يرتفع السعر بما يكفي ضدك.</p>\n<h2>المخاطرة ليست متماثلة</h2><p>مركز الشراء لا يمكن أن يهبط إلا إلى الصفر، لكن مركز البيع يحمل خسارة نظرية غير محدودة إذا استمر السعر في الارتفاع — ولهذا قد تكون عمليات انضغاط مراكز البيع عنيفة. في كلتا الحالتين، تحدّد الرافعة المالية مدى قرب <a href=\"/guides/what-is-liquidation-price/\">سعر تصفيتك</a> من الدخول. اختبر كلا الجانبين دون مخاطرة على <a href=\"/paper-trade\">التداول التجريبي</a>.</p>","faq":[["ماذا يعني البيع (شورت) في الكريبتو؟","البيع يعني المراهنة على أن السعر سيهبط: تربح عند هبوطه وتخسر عند ارتفاعه، ما يتيح لك جني المال في الاتجاه الهابط."],["هل البيع أكثر خطورة من الشراء؟","يحمل مركز البيع خسارة نظرية غير محدودة إذا استمر السعر في الارتفاع، بينما لا يمكن لمركز الشراء أن يهبط إلا إلى الصفر — لذا قد يكون مركز البيع غير المحوَّط أكثر خطورة، وقد يكون انضغاط مراكز البيع حاداً."]]},"what-is-mark-price":{"title":"ما هو سعر التحديد (Mark Price) في عقود الكريبتو الآجلة؟","desc":"لماذا تُصفّي المنصات وفق سعر التحديد لا السعر الأخير، وكيف يحميك من المحو بسبب دفتر أوامر رقيق.","toolLabel":"حاسبة التصفية","body":"<h2>السعر الأخير مقابل سعر التحديد</h2><p><strong>السعر الأخير</strong> هو ببساطة آخر صفقة على تلك المنصة. <strong>سعر التحديد</strong> مرجع أكثر إنصافاً — يُبنى عادةً من مؤشر لعدة أسواق فورية مضافاً إليه أساس التمويل — يُنعّم تقلبات منصة واحدة.</p>\n<h2>لماذا يهم</h2><p>تحسب المنصات أرباحك وخسائرك غير المحقّقة و<a href=\"/guides/what-is-liquidation-price/\">تصفيتك</a> مقابل <strong>سعر التحديد</strong> لا السعر الأخير. هذا يحميك من التصفية بسبب ذيل قصير على دفتر رقيق لا يعكس السوق الحقيقي.</p>\n<h2>ما الذي تراقبه</h2><p>في الأسواق السريعة قد يقفز السعر الأخير متجاوزاً سعر التحديد بكثير. يُحكَم على مركزك وفق سعر التحديد، لذا تحقق منه — لا من السعر الأخير الوامض — عندما تكون قرب مستوى تصفيتك.</p>","faq":[["لماذا تستخدم المنصات سعر التحديد للتصفية؟","سعر التحديد قيمة عادلة قائمة على مؤشر تُنعّم تقلبات منصة واحدة، بحيث لا يستطيع ذيل قصير على دفتر أوامر رقيق أن يصفّي خطأً مركزاً سليماً."],["هل سعر التحديد هو نفسه السعر الأخير؟","لا. السعر الأخير هو آخر صفقة على تلك المنصة؛ أما سعر التحديد فهو قيمة أكثر إنصافاً قائمة على مؤشر تُستخدم لحساب الأرباح والخسائر والتصفيات."]]}},"id":{"how-to-read-funding-rates":{"title":"Cara Membaca Funding Rate Kripto","desc":"Panduan dengan bahasa sederhana tentang funding rate perpetual: apa arti funding positif dan negatif, cara mengenali posisi long dan short yang terlalu padat, dan cara memanfaatkan funding yang ekstrem.","toolLabel":"Pemindai funding langsung","body":"<h2>Apa itu funding rate</h2><p>Pada perpetual future tidak ada tanggal kedaluwarsa, sehingga bursa menggunakan pembayaran berulang kecil — <strong>funding rate</strong> — untuk menjaga harga perp tetap menempel pada harga spot. Pembayaran ini biasanya dipertukarkan setiap 8 jam antara posisi long dan short.</p>\n<h2>Funding positif vs negatif</h2><p><strong>Funding positif</strong> berarti perp diperdagangkan di atas spot, jadi <em>long membayar short</em> — pasar condong ke long. <strong>Funding negatif</strong> berarti perp diperdagangkan di bawah spot, jadi <em>short membayar long</em> — pasar condong ke short.</p>\n<h2>Membaca kondisi ekstrem</h2><p>Ketika funding sangat positif, posisi long terlalu padat dan membayar premi untuk bertahan; harga yang macet bisa memicu <strong>long squeeze</strong>. Ketika funding sangat negatif, posisi short terlalu padat dan pantulan harga bisa memaksa <strong>short squeeze</strong>. Funding paling kuat sebagai sinyal jika dipadukan dengan <a href=\"/open-interest/\">open interest</a> dan <a href=\"/long-short/\">posisi long/short</a>.</p>\n<h2>Perhatikan biayanya</h2><p>Pada leverage tinggi, biaya funding bertambah dengan cepat dan bisa diam-diam menggerus posisi bahkan saat harga datar. Selalu perhitungkan dalam lama waktu menahan posisimu.</p>","faq":[["Apa arti funding rate yang tinggi?","Funding positif yang tinggi berarti pasar sangat condong ke long dan posisi long membayar untuk bertahan — tanda long yang terlalu padat yang bisa memicu short squeeze saat terjadi pullback."],["Apakah funding negatif itu bullish?","Funding negatif berarti posisi short terlalu padat dan membayar long. Sering dibaca secara kontrarian sebagai persiapan squeeze ke atas, tetapi ini hanya satu sinyal di antara funding, open interest, dan harga."]]},"how-to-read-liquidations":{"title":"Cara Membaca Likuidasi Kripto","desc":"Pahami likuidasi kripto: apa itu likuidasi, perbedaan antara likuidasi long dan short, dan bagaimana cascade likuidasi mendorong volatilitas.","toolLabel":"Pelacak likuidasi langsung","body":"<h2>Apa itu likuidasi</h2><p>Sebuah <strong>likuidasi</strong> terjadi ketika bursa menutup paksa posisi ber-leverage karena margin trader sudah tidak bisa menutupi kerugian. Posisi ditutup di harga pasar dan trader kehilangan margin-nya. Pada leverage tinggi, harga likuidasi berada sangat dekat dengan harga masuk.</p>\n<h2>Likuidasi long vs short</h2><p><strong>Likuidasi long</strong> adalah para pembeli yang terlalu ber-leverage yang tersapu saat harga turun. <strong>Likuidasi short</strong> adalah para penjual yang tersapu saat harga naik. Lonjakan besar di satu sisi sering menandai titik ekstrem lokal — banjir likuidasi long bisa menandai dasar, sedangkan gelombang likuidasi short bisa memicu reli.</p>\n<h2>Cascade likuidasi</h2><p>Likuidasi bekerja seperti bahan bakar. Ketika harga mencapai zona yang penuh leverage, order paksa mendorong harga lebih jauh, memicu lebih banyak likuidasi — sebuah <strong>cascade</strong>. Mengamati di mana leverage paling padat membantumu menghindari trade yang terlalu ramai.</p>\n<h2>Gunakan bersama yang lain</h2><p>Padukan likuidasi dengan <a href=\"/funding/\">funding</a> dan <a href=\"/open-interest/\">open interest</a>: penurunan open interest biasanya mengikuti cascade karena leverage tersapu keluar.</p>","faq":[["Apa yang menyebabkan likuidasi?","Sebuah posisi dilikuidasi ketika harga bergerak melawannya cukup jauh sehingga margin tidak lagi bisa menutupi kerugian, jadi bursa menutupnya secara otomatis."],["Apakah likuidasi long atau short itu bullish?","Lonjakan likuidasi long (saat harga turun) bisa menandai dasar lokal; lonjakan likuidasi short (saat harga naik) bisa memicu squeeze ke atas."]]},"what-is-open-interest":{"title":"Apa Itu Open Interest dalam Kripto?","desc":"Penjelasan open interest: bagaimana ia berbeda dari volume, apa sinyal OI yang naik dan turun, dan cara membaca OI bersama harga.","toolLabel":"Pelacak open interest langsung","body":"<h2>Open interest vs volume</h2><p><strong>Open interest (OI)</strong> adalah nilai total dari semua posisi perpetual-future yang terbuka pada sebuah koin. Berbeda dengan volume — yang menghitung setiap transaksi — OI mengukur seberapa banyak leverage yang saat ini <em>terbuka</em> di pasar.</p>\n<h2>OI yang naik dan turun</h2><p>OI yang naik berarti posisi baru dan leverage segar masuk. OI yang turun berarti trader sedang menutup posisi. Penurunan OI yang tiba-tiba biasanya mengikuti <a href=\"/liquidations/\">cascade likuidasi</a> saat posisi yang terlalu ber-leverage tersapu.</p>\n<h2>Membaca OI bersama harga</h2><p><strong>Harga naik + OI naik</strong> = uang baru menopang pergerakan (tren lebih kuat). <strong>Harga naik + OI turun</strong> = short covering, bukan permintaan baru. Penumpukan OI yang besar plus <a href=\"/funding/\">funding</a> sepihak menandai kondisi yang padat dan rapuh.</p>","faq":[["Apakah open interest yang tinggi itu bullish atau bearish?","Tidak keduanya secara mandiri — tergantung harga. OI naik dengan harga naik menunjukkan pembeli baru; OI naik dengan harga turun menunjukkan penjual baru."],["Apa arti open interest yang turun?","OI yang turun berarti posisi sedang ditutup, sering setelah cascade likuidasi menyapu leverage keluar dari pasar."]]},"long-short-ratio-explained":{"title":"Penjelasan Rasio Long/Short Kripto","desc":"Apa yang diberitahukan rasio long/short tentang posisi trader, cara membaca titik ekstrem yang padat, dan kenapa paling baik digunakan secara kontrarian.","toolLabel":"Rasio long/short langsung","body":"<h2>Apa yang diukur</h2><p><strong>Rasio long/short</strong> menunjukkan berapa persen akun trader yang berposisi long versus short pada sebuah koin. Ini adalah potret posisi dan sentimen kerumunan.</p>\n<h2>Membaca kerumunan</h2><p>Trader berpengalaman sering membaca kondisi ekstrem secara <strong>kontrarian</strong>. Ketika sebagian besar akun sudah long, tenaga beli sebagian besar sudah habis dan kerumunan rentan terhadap <strong>long squeeze</strong>. Ketika kerumunan sangat short, pantulan harga bisa memaksa <strong>short squeeze</strong>.</p>\n<h2>Satu sinyal, bukan keseluruhan gambar</h2><p>Order book yang padat bisa tetap padat selama tren berjalan. Padukan rasio ini dengan <a href=\"/funding/\">funding</a> (apa yang dibayar kerumunan untuk bertahan) dan <a href=\"/liquidations/\">likuidasi</a> (di mana leverage tersapu) sebelum bertindak.</p>","faq":[["Berapa rasio long/short yang bagus?","Tidak ada satu nilai yang bagus — ini paling berguna pada titik ekstrem. Porsi long yang sangat tinggi memperingatkan long yang padat; porsi short yang sangat tinggi memperingatkan short yang padat."],["Bagaimana trader menggunakan rasio long/short?","Banyak yang membacanya secara kontrarian: melawan sisi yang terlalu padat, dan selalu mengonfirmasi dengan funding, open interest, dan aksi harga."]]},"what-is-liquidation-price":{"title":"Apa Itu Harga Likuidasi dalam Kripto?","desc":"Apa itu harga likuidasi, bagaimana leverage menggesernya lebih dekat ke harga masuk, dan cara menghitungnya sebelum membuka posisi.","toolLabel":"Kalkulator harga likuidasi","body":"<h2>Apa itu</h2><p><strong>Harga likuidasi</strong>-mu adalah harga di mana bursa menutup paksa posisi ber-leverage-mu karena margin sudah tidak bisa menutupi kerugian. Melewatinya dan kamu kehilangan margin-mu. Mengetahuinya sebelum masuk adalah angka tunggal terpenting dalam trading ber-leverage.</p>\n<h2>Bagaimana leverage menggesernya</h2><p>Semakin tinggi leverage-mu, semakin dekat harga likuidasi ke harga masuk. Pada 5× sebuah long dilikuidasi sekitar penurunan 20%; pada 100× kira-kira pergerakan 1%. Itulah kenapa leverage tinggi begitu rapuh — sebuah wick biasa bisa menyapu posisi.</p>\n<h2>Bagaimana dihitung</h2><p>Untuk long terisolasi, likuidasi ≈ harga masuk × (1 − 1/leverage + maintenance-margin rate); short membalik tandanya. Angka pastinya tergantung pada maintenance margin dan biaya bursa, jadi konfirmasikan dengan <a href=\"/btc-liquidation-calculator/\">kalkulator likuidasi</a> untuk koin dan leverage-mu.</p>\n<h2>Beri ruang</h2><p>Atur ukuran dan leverage-mu agar harga likuidasi berada di luar noise — melewati support dan resistance yang jelas serta wick terbaru — bukan tepat di atas harga masuk-mu. Lihat juga <a href=\"/guides/how-to-avoid-liquidation/\">cara menghindari likuidasi</a>.</p>","faq":[["Bagaimana harga likuidasi dihitung?","Secara kasar, likuidasi ≈ harga masuk × (1 − 1/leverage + maintenance margin) untuk long, dengan short dibalik. Nilai presisinya tergantung pada maintenance-margin rate dan biaya bursa."],["Apakah leverage yang lebih tinggi berarti harga likuidasi lebih dekat?","Ya. Pada 100× harga likuidasi hanya sekitar 1% dari harga masuk, sedangkan pada 5× lebih dekat ke 20% — leverage yang lebih tinggi nyaris tidak menyisakan ruang bagi harga untuk bergerak melawanmu."]]},"isolated-vs-cross-margin":{"title":"Penjelasan Isolated vs Cross Margin","desc":"Perbedaan antara isolated dan cross margin, trade-off risikonya, dan mode mana yang cocok untuk gaya trader yang mana.","toolLabel":"Latihan di Paper Trade","body":"<h2>Isolated margin</h2><p>Dalam <strong>isolated margin</strong>, hanya margin yang kamu alokasikan ke sebuah posisi yang berisiko. Jika terlikuidasi, kerugian dibatasi pada margin itu dan sisa saldomu tidak tersentuh. Ini adalah default yang lebih aman untuk trade ber-leverage tinggi.</p>\n<h2>Cross margin</h2><p>Dalam <strong>cross margin</strong>, seluruh saldo akunmu menopang posisi. Itu mendorong harga likuidasi lebih jauh, tetapi satu trade buruk bisa menguras seluruh akun, bukan hanya margin satu posisi.</p>\n<h2>Mana yang dipakai</h2><p>Sebagian besar trader menggunakan <strong>isolated</strong> untuk setup ber-leverage tinggi dengan risiko terdefinisi, dan <strong>cross</strong> untuk posisi ber-leverage rendah yang mereka kelola atau hedge secara aktif. Trade-off-nya: isolated membatasi kerugianmu; cross menurunkan risiko likuidasi tetapi menaikkan kerugian maksimummu. Bagaimanapun, periksa dulu <a href=\"/guides/what-is-liquidation-price/\">harga likuidasi</a>.</p>","faq":[["Mana yang lebih aman, isolated atau cross margin?","Isolated lebih aman untuk membatasi kerugian — hanya margin yang dialokasikan yang berisiko. Cross margin lebih sulit terlikuidasi tetapi mempertaruhkan seluruh saldomu."],["Kapan saya harus menggunakan cross margin?","Cross cocok untuk posisi ber-leverage rendah yang kamu kelola atau hedge secara aktif, di mana kamu ingin trade bertahan menghadapi volatilitas tanpa menambah margin."]]},"how-to-calculate-position-size":{"title":"Cara Menghitung Ukuran Posisi dalam Kripto","desc":"Tentukan ukuran setiap trade berdasarkan risiko, bukan firasat: cara menghitung ukuran posisi dari akun, jarak stop, dan risiko per trade.","toolLabel":"Kalkulator ukuran posisi","body":"<h2>Risiko dulu, ukuran kemudian</h2><p>Penentuan ukuran yang profesional dimulai dari satu angka: berapa banyak yang siap kamu rugikan pada trade itu. Aturan umum adalah merisikokan <strong>1–2% dari akunmu per trade</strong>. Ukuran posisimu kemudian mengikuti jarak stop-mu.</p>\n<h2>Rumusnya</h2><p>Ukuran posisi = (akun × risiko %) ÷ (jarak stop %). Jika kamu merisikokan $20 dan stop-mu berjarak 2%, kamu mengambil eksposur $1,000 — terlepas dari leverage. Leverage hanya menentukan margin yang dibutuhkan, bukan risikomu.</p>\n<h2>Leverage bukan risiko</h2><p>Inilah poin yang dilewatkan kebanyakan pemula: risikomu ditentukan oleh ukuran dan stop, bukan oleh leverage. 10× pada posisi kecil yang ber-stop bagus bisa jauh lebih aman daripada 2× pada posisi yang kebesaran. Gunakan <a href=\"/calculators?c=size\">kalkulator ukuran posisi</a> agar setiap trade merisikokan jumlah yang sama, dan awasi <a href=\"/guides/what-is-liquidation-price/\">harga likuidasi</a>-mu.</p>","faq":[["Berapa banyak yang harus saya risikokan per trade?","Pedoman yang banyak dipakai adalah 1–2% dari akunmu per trade, agar serangkaian kerugian tidak bisa meledakkan akun."],["Apakah leverage mengubah ukuran posisi saya?","Tidak — risikomu ditentukan oleh ukuran posisi dan jarak stop. Leverage hanya menentukan margin yang dibutuhkan untuk menahan posisi itu."]]},"what-is-leverage-in-crypto":{"title":"Apa Itu Leverage dalam Trading Kripto?","desc":"Penjelasan leverage secara sederhana: bagaimana 10× atau 100× bekerja, apa pengaruhnya terhadap harga likuidasimu, dan cara menggunakannya tanpa meledak.","toolLabel":"Kalkulator likuidasi","body":"<h2>Apa yang dilakukan leverage</h2><p><strong>Leverage</strong> memungkinkanmu mengendalikan posisi yang lebih besar dari margin-mu. Pada 10×, margin $100 mengendalikan eksposur $1,000, jadi pergerakan 1% menjadi ayunan 10% pada margin-mu — keuntungan maupun kerugian sama-sama diperbesar.</p>\n<h2>Jebakannya: likuidasi</h2><p>Sisi lainnya adalah <a href=\"/guides/what-is-liquidation-price/\">harga likuidasi</a>-mu. Semakin tinggi leverage, semakin kecil pergerakan yang menyapumu — kira-kira 1% pada 100×, 2% pada 50×, 10% pada 10×. Potensi naik yang diperbesar datang bersama kerapuhan yang diperbesar.</p>\n<h2>Menggunakannya dengan bijak</h2><p>Leverage adalah alat untuk efisiensi modal, bukan angka untuk dimaksimalkan. Tentukan ukuran berdasarkan <a href=\"/guides/how-to-calculate-position-size/\">risiko</a>, jaga harga likuidasi di luar noise, dan ingat biaya funding berskala dengan ukuran posisi, bukan margin.</p>","faq":[["Apa arti leverage 10x?","10× berarti posisimu sepuluh kali margin-mu: $100 mengendalikan $1,000, jadi pergerakan harga 1% setara pergerakan 10% pada margin-mu — di kedua arah."],["Apakah leverage tinggi itu buruk?","Leverage tinggi tidak secara inheren buruk, tetapi menempatkan harga likuidasimu sangat dekat dengan harga masuk. Sebagian besar kebangkrutan datang dari ukuran berlebih pada leverage tinggi, bukan dari leverage itu sendiri."]]},"maker-vs-taker-fees":{"title":"Penjelasan Biaya Maker vs Taker","desc":"Apa itu biaya maker dan taker, kenapa taker membayar lebih, dan bagaimana selisihnya menumpuk bagi trader futures yang aktif.","toolLabel":"Bandingkan biaya bursa","body":"<h2>Perbedaannya</h2><p>Sebuah order <strong>maker</strong> menambah likuiditas ke order book — order limit yang menetap dan menunggu untuk diisi. Sebuah order <strong>taker</strong> menghapus likuiditas — order market, atau order limit yang terisi seketika, yang mengambil penawaran yang ada. Bursa membebankan biaya lebih pada taker karena maker menyediakan likuiditas yang diperdagangkan semua orang.</p>\n<h2>Tarif umum</h2><p>Pada perpetual USDT utama, biaya maker sekitar 0.02% dan biaya taker 0.04–0.06%. Terdengar sangat kecil, tetapi day trader yang melakukan puluhan round trip membayarnya berulang kali — dan taker membayarnya di kedua sisi.</p>\n<h2>Cara membayar lebih sedikit</h2><p>Gunakan <strong>order limit</strong> yang menetap untuk memenuhi syarat biaya maker bila bisa, tahan token bursa untuk diskon, dan naiki tingkatan VIP seiring volume bertumbuh. Jika biaya adalah prioritasmu, <a href=\"/lowest-fee-crypto-exchange/\">bandingkan bursa berdasarkan biaya taker</a> lebih dulu.</p>","faq":[["Kenapa taker membayar lebih dari maker?","Taker menghapus likuiditas dengan mengisi order yang ada, sedangkan maker menambah likuiditas dengan menaruh order di book. Bursa memberi imbalan biaya lebih rendah kepada maker karena mereka menjaga pasar tetap likuid."],["Bagaimana cara saya membayar biaya maker?","Pasang order limit yang menetap di book alih-alih order market yang terisi seketika. Jika order-mu menunggu untuk dipasangkan, ia memenuhi syarat biaya maker yang lebih rendah."]]},"how-to-avoid-liquidation":{"title":"Cara Menghindari Likuidasi dalam Trading Kripto","desc":"Cara praktis menjaga posisi ber-leverage agar tidak terlikuidasi — dari penentuan ukuran dan stop hingga mode margin dan funding.","toolLabel":"Periksa harga likuidasimu","body":"<h2>Ketahui harganya sebelum masuk</h2><p>Hitung <a href=\"/guides/what-is-liquidation-price/\">harga likuidasi</a>-mu lebih dulu dan pastikan berada di luar wick terbaru serta support dan resistance yang jelas — bukan tepat di sebelah harga masuk-mu.</p>\n<h2>Gunakan leverage lebih kecil daripada yang bisa kamu pakai</h2><p>Hanya karena sebuah platform menawarkan 125× bukan berarti kamu harus menggunakannya. Leverage yang lebih rendah mendorong harga likuidasi lebih jauh dari harga masuk dan memberimu ruang untuk benar dari waktu ke waktu.</p>\n<h2>Selalu pasang stop-loss</h2><p>Sebuah stop menutup posisimu di harga yang <em>kamu</em> pilih, sebelum mesin likuidasi bursa melakukannya untukmu di harga yang lebih buruk.</p>\n<h2>Tentukan ukuran berdasarkan risiko</h2><p>Risikokan 1–2% tetap per trade menggunakan <a href=\"/guides/how-to-calculate-position-size/\">kalkulator ukuran posisi</a>, agar tidak ada satu trade pun yang bisa menimbulkan kerusakan nyata.</p>\n<h2>Utamakan isolated margin</h2><p><a href=\"/guides/isolated-vs-cross-margin/\">Isolated margin</a> membatasi kerugian pada satu posisi. Tambah margin secara sengaja, bukan dalam panik.</p>\n<h2>Perhatikan funding</h2><p>Pada leverage tinggi, <a href=\"/funding/\">funding</a> diam-diam menggerus posisi bahkan saat harga datar — perhitungkan dalam penahanan jangka panjang.</p>","faq":[["Apa cara terbaik untuk menghindari likuidasi?","Gunakan leverage lebih rendah, selalu pasang stop-loss, tentukan ukuran berdasarkan persentase risiko tetap, dan jaga harga likuidasimu jauh di luar volatilitas terbaru."],["Apakah stop-loss mencegah likuidasi?","Stop-loss menutup posisimu di harga pilihanmu sebelum likuidasi bursa terpicu, jadi pada praktiknya ia mencegah sebagian besar likuidasi — asalkan terisi di pasar yang bergerak cepat."]]},"perpetual-vs-futures":{"title":"Perpetual vs Futures: Apa Perbedaannya?","desc":"Perpetual swap versus futures bertanggal: kedaluwarsa, funding, dan kenapa perp mendominasi trading leverage kripto.","toolLabel":"Pemindai funding langsung","body":"<h2>Futures bertanggal</h2><p>Sebuah <strong>kontrak futures</strong> tradisional memiliki tanggal kedaluwarsa. Pada tanggal itu ia diselesaikan ke harga spot, sehingga harga kontrak menyatu dengan spot saat kedaluwarsa mendekat. Kamu memperdagangkannya untuk jangka waktu tetap, lalu ia hilang.</p>\n<h2>Perpetual swap</h2><p>Sebuah <strong>perpetual</strong> (\"perp\") tidak pernah kedaluwarsa. Untuk menjaga harganya tetap menempel pada spot tanpa kedaluwarsa, bursa menggunakan <a href=\"/funding/\">pembayaran funding</a> berulang antara long dan short. Mekanisme itu menggantikan penyelesaian.</p>\n<h2>Kenapa perp mendominasi kripto</h2><p>Perp memungkinkan trader menahan leverage tanpa batas tanpa rollover, itulah kenapa mereka menyumbang sebagian besar volume derivatif kripto. Trade-off-nya adalah funding: pada leverage tinggi ia bisa diam-diam menggerus posisi bahkan saat harga datar.</p>","faq":[["Apakah kontrak perpetual kedaluwarsa?","Tidak. Perpetual swap tidak pernah kedaluwarsa — pembayaran funding berulang menjaga harganya tetap terikat ke spot alih-alih ke tanggal penyelesaian."],["Apa perbedaan antara futures dan perpetual?","Futures bertanggal diselesaikan pada tanggal kedaluwarsa, sedangkan perpetual berjalan tanpa batas dan menggunakan pembayaran funding untuk tetap dekat dengan spot. Trading kripto didominasi oleh perpetual."]]},"long-vs-short-crypto":{"title":"Penjelasan Long vs Short dalam Kripto","desc":"Apa artinya membuka posisi long atau short dengan leverage, bagaimana masing-masing sisi menghasilkan atau kehilangan uang, dan bagaimana likuidasinya berbeda.","toolLabel":"Latihan long & short","body":"<h2>Membuka posisi long</h2><p>Sebuah <strong>long</strong> bertaruh bahwa harga akan naik. Kamu untung saat harga naik dan rugi saat harga turun. Sebuah long dilikuidasi ketika harga turun cukup jauh sehingga margin-mu tidak lagi bisa menutupi kerugian.</p>\n<h2>Membuka posisi short</h2><p>Sebuah <strong>short</strong> bertaruh bahwa harga akan turun. Kamu untung saat harga turun dan rugi saat harga naik — shorting memungkinkanmu menghasilkan uang dalam tren turun. Sebuah short dilikuidasi ketika harga naik cukup jauh melawanmu.</p>\n<h2>Risikonya tidak simetris</h2><p>Sebuah long hanya bisa jatuh hingga nol, tetapi sebuah short memiliki kerugian teoretis tak terbatas jika harga terus naik — itulah kenapa short squeeze bisa dahsyat. Bagaimanapun, leverage menentukan seberapa dekat <a href=\"/guides/what-is-liquidation-price/\">harga likuidasi</a>-mu ke harga masuk. Uji kedua sisi tanpa risiko di <a href=\"/paper-trade\">Paper Trade</a>.</p>","faq":[["Apa arti membuka posisi short dalam kripto?","Shorting berarti bertaruh bahwa harga akan turun: kamu untung saat harga turun dan rugi saat harga naik, yang memungkinkanmu menghasilkan uang dalam tren turun."],["Apakah shorting lebih berisiko daripada long?","Sebuah short memiliki kerugian teoretis tak terbatas jika harga terus naik, sedangkan long hanya bisa jatuh hingga nol — jadi short tanpa hedge bisa lebih berisiko, dan short squeeze bisa tajam."]]},"what-is-mark-price":{"title":"Apa Itu Mark Price dalam Crypto Futures?","desc":"Kenapa bursa melikuidasi berdasarkan mark price, bukan last price, dan bagaimana ini melindungimu agar tidak tersapu oleh order book yang tipis.","toolLabel":"Kalkulator likuidasi","body":"<h2>Last price vs mark price</h2><p><strong>Last price</strong> adalah sekadar transaksi terbaru pada bursa itu. <strong>Mark price</strong> adalah acuan yang lebih adil — biasanya dibangun dari indeks beberapa pasar spot ditambah basis funding — yang menghaluskan lonjakan satu bursa.</p>\n<h2>Kenapa ini penting</h2><p>Bursa menghitung PnL belum terealisasi dan <a href=\"/guides/what-is-liquidation-price/\">likuidasi</a>-mu berdasarkan <strong>mark price</strong>, bukan last price. Ini melindungimu agar tidak terlikuidasi oleh wick sesaat pada book yang tipis yang tidak mencerminkan pasar yang sebenarnya.</p>\n<h2>Apa yang perlu diperhatikan</h2><p>Di pasar yang bergerak cepat, last price bisa melonjak jauh melewati mark price. Posisimu dinilai berdasarkan mark, jadi periksa itu — bukan last price yang berkedip — saat kamu dekat dengan level likuidasimu.</p>","faq":[["Kenapa bursa menggunakan mark price untuk likuidasi?","Mark price adalah nilai wajar berbasis indeks yang menghaluskan lonjakan satu bursa, jadi wick sesaat pada order book yang tipis tidak bisa salah melikuidasi posisi yang sehat."],["Apakah mark price sama dengan last price?","Tidak. Last price adalah transaksi terbaru pada bursa itu; mark price adalah nilai berbasis indeks yang lebih adil yang dipakai untuk menghitung PnL dan likuidasi."]]}}};

module.exports = { SHARED, CASES };
